import type { CSSProperties } from "react";

/**
 * Transparent pictures sit on a checkerboard, so a baked-in background shows
 * as a block. Every picture grid uses this one. A plain module (no "use
 * client"), so server pages get the value, not a client reference.
 */
export const CHECKER_STYLE: CSSProperties = {
    background: "repeating-conic-gradient(rgb(var(--md-sys-color-surface-container-rgb)) 0 25%, rgb(var(--md-sys-color-surface-container-lowest-rgb)) 0 50%) 50% / 16px 16px",
};

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";
import { typescale, shape, elevation } from "./tokens/tokens";
import { text as legacyText } from "./tokens/legacy";

/**
 * Class merging that knows the M3 scales.
 *
 * Plain tailwind-merge treats any unknown `text-*` as a colour, so
 * `cn("text-title-md", "text-on-surface")` silently DROPPED the size and kept
 * only the colour. Registering the scale's role names as font sizes fixes that
 * for every component in @/ui — and the same trap applies to the spelled-out
 * shape steps (`rounded-medium`) and the elevation levels (`shadow-level-2`).
 *
 * The legacy step names are registered too, so a half-migrated file still
 * merges correctly. They go with `legacy.ts` in S11.
 */
const twMerge = extendTailwindMerge({
    classGroups: {
        "font-size": [{
            text: [
                ...Object.keys(typescale),
                ...Object.keys(legacyText),
                "d1", "d2", "d3", "d4", "legacy-lg", "body-xs", "body-2xs", "body-3xs",
            ],
        }],
        rounded: [{ rounded: Object.keys(shape) }],
        // The 48dp touch floor, so `min-h-0` on a Button can replace it.
        "min-h": [{ "min-h": ["touch"] }],
        shadow: [{
            shadow: [
                ...Object.keys(elevation).map(l => `level-${l}`),
                "elevation-1", "elevation-2", "elevation-3", "elevation-4", "highlight",
            ],
        }],
    },
});

export function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

import type { ReactNode } from "react";
import { cn } from "../cn";

const SIZE = { sm: "h-8 w-8 text-label-md", md: "h-10 w-10 text-label-lg", lg: "h-14 w-14 text-title-md", xl: "h-20 w-20 text-headline-sm" } as const;
export type AvatarSize = keyof typeof SIZE;

/** "Ada Lovelace" → "AL", "ada@x.com" → "AD". Never empty. */
export function initials(name?: string | null): string {
    const s = (name ?? "").split("@")[0].trim();
    const words = s.split(/[\s._-]+/).filter(Boolean);
    const two = words.length > 1 ? words[0][0] + words[1][0] : s.slice(0, 2);
    return (two || "?").toUpperCase();
}

export type AvatarProps = {
    /** A name or an email: gives the initials and the accessible label. */
    name?: string | null;
    src?: string | null;
    size?: AvatarSize;
    /** A small dot on the corner: online, busy. */
    status?: "online" | "away" | "busy";
    className?: string;
};

const DOT = { online: "bg-primary", away: "bg-tertiary", busy: "bg-error" } as const;

/**
 * A person or a team: a picture when there is one, two letters when there isn't.
 * Square like everything else in Ink. The letters sit on ink, never on a
 * random colour, so a list of people stays one colour and the art stays the art.
 */
export function Avatar({ name, src, size = "md", status, className }: AvatarProps) {
    return (
        <span role="img" aria-label={name ?? "User"} className={cn("relative inline-flex shrink-0 select-none items-center justify-center overflow-hidden rounded-small bg-inverse-surface font-medium text-inverse-on-surface", SIZE[size], className)}>
            {src ? (
                // eslint-disable-next-line @next/next/no-img-element -- any host, any format
                <img src={src} alt="" className="h-full w-full object-cover" />
            ) : (
                <span aria-hidden>{initials(name)}</span>
            )}
            {status ? <span aria-hidden className={cn("absolute bottom-0 right-0 h-2.5 w-2.5 ring-2 ring-surface", DOT[status])} /> : null}
        </span>
    );
}

export type AvatarGroupProps = {
    people: { name?: string | null; src?: string | null }[];
    /** How many to draw before "+3". */
    max?: number;
    size?: AvatarSize;
    className?: string;
};

/** A row of faces that overlap: the members of a team, who's on a document. */
export function AvatarGroup({ people, max = 4, size = "sm", className }: AvatarGroupProps) {
    const shown = people.slice(0, max);
    const more = people.length - shown.length;
    return (
        <span className={cn("inline-flex items-center", className)} aria-label={`${people.length} people`}>
            {shown.map((p, i) => (
                <Avatar key={i} name={p.name} src={p.src} size={size} className={cn("ring-2 ring-surface", i > 0 && "-ml-2")} />
            ))}
            {more > 0 ? (
                <span className={cn("-ml-2 inline-flex items-center justify-center rounded-small bg-surface-container-highest text-on-surface ring-2 ring-surface", SIZE[size])}>+{more}</span>
            ) : null}
        </span>
    );
}

/** Avatar + name + one line, the way a person appears in a row or a menu. */
export function Person({ name, email, src, size = "md", trailing }: { name?: string | null; email?: string | null; src?: string | null; size?: AvatarSize; trailing?: ReactNode }) {
    return (
        <span className="flex min-w-0 items-center gap-3">
            <Avatar name={name || email} src={src} size={size} />
            <span className="min-w-0 flex-1">
                <span className="block truncate text-body-md text-on-surface">{name || email}</span>
                {name && email ? <span className="block truncate text-label-md text-on-surface-variant">{email}</span> : null}
            </span>
            {trailing}
        </span>
    );
}

import type { ReactNode } from "react";
import { cn } from "../cn";
import { lift } from "../state-layer";

export type CardProps = {
    /** Turns the whole card into one hit target. Use with an <a> inside for the real link. */
    interactive?: boolean;
    /**
     * Which step of the container ladder the card sits on. A card is told apart
     * from the page by its FILL, never by a border (law 11), so the step has to
     * clear the page by two — `surface` → `surface-container` is the default
     * pair. `high` is for a card on a page that is already a container;
     * `page` is the flat, unraised case (a card on the studio canvas).
     */
    surface?: "card" | "high" | "page";
    padding?: "none" | "sm" | "md" | "lg";
    className?: string;
    children: ReactNode;
};

const PAD = { none: "", sm: "p-3", md: "p-4", lg: "p-5" } as const;

/**
 * 🔴 Two steps, not one. In light mode `surface` is #FDF7FF and
 * `surface-container-low` is #F8F2FA — a borderless card drawn on that pair is
 * invisible. `surface-container` (#F2ECF4) is the first step that reads.
 */
const SURFACE = {
    card: "bg-surface-container",
    high: "bg-surface-container-high",
    page: "bg-surface",
} as const;

/**
 * A contained surface: one thing, its details, and at most one action.
 *
 * Not everything is a Card. Border, fill and shadow each say "separate
 * object" - spending them on every block flattens the page. A list of rows is
 * a List; a page section is a Section.
 */
export function Card({ interactive, surface = "card", padding = "md", className, children }: CardProps) {
    return (
        <div
            className={cn(
                // min-w-0: a grid/flex child defaults to min-width:auto, so one long
                // word inside (a URL, a wallet id) makes the card wider than the screen.
                "min-w-0 rounded-medium",
                SURFACE[surface],
                PAD[padding],
                // Hover is `lift`: a colour step, a shape morph and a rise -
                // never a border appearing. See state-layer.ts.
                interactive && lift,
                className,
            )}
        >
            {children}
        </div>
    );
}

export type PanelProps = { className?: string; children: ReactNode };

/**
 * The raised working surface an app screen sits on: the counterpart to the
 * canvas behind the sidebar. One per screen.
 */
export function Panel({ className, children }: PanelProps) {
    return <div className={cn("min-w-0 rounded-large bg-surface-container-low shadow-level-1", className)}>{children}</div>;
}

export type SectionProps = {
    title?: ReactNode;
    description?: ReactNode;
    /** Buttons or filters that belong to this section. */
    actions?: ReactNode;
    className?: string;
    children: ReactNode;
};

/** A titled block within a page. Spacing comes from the system, not the page. */
export function Section({ title, description, actions, className, children }: SectionProps) {
    return (
        <section className={cn("flex min-w-0 flex-col gap-4", className)}>
            {title || actions ? (
                <div className="flex flex-wrap items-end justify-between gap-3">
                    <div className="min-w-0">
                        {title ? <h2 className="text-headline-sm text-on-surface">{title}</h2> : null}
                        {description ? <p className="mt-1 max-w-measure text-body-md text-on-surface-variant">{description}</p> : null}
                    </div>
                    {actions ? <div className="flex shrink-0 flex-wrap gap-2">{actions}</div> : null}
                </div>
            ) : null}
            {children}
        </section>
    );
}

export type PageHeaderProps = {
    title: ReactNode;
    /** One line: what this page is for, or what state it is in. */
    description?: ReactNode;
    /** Where the user is. Keep it to two or three levels. */
    breadcrumb?: ReactNode;
    meta?: ReactNode;
    actions?: ReactNode;
    className?: string;
};

/** The top of a page: where am I, what is this, what can I do. */
export function PageHeader({ title, description, breadcrumb, meta, actions, className }: PageHeaderProps) {
    return (
        <header className={cn("flex min-w-0 flex-col gap-3", className)}>
            {breadcrumb}
            <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0">
                    <h1 className="text-headline-lg text-on-surface">{title}</h1>
                    {description ? <p className="mt-1.5 max-w-measure text-body-md text-on-surface-variant">{description}</p> : null}
                    {meta ? <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-label-md text-on-surface-variant">{meta}</div> : null}
                </div>
                {actions ? <div className="flex shrink-0 flex-wrap gap-2">{actions}</div> : null}
            </div>
        </header>
    );
}

export type BreadcrumbProps = { items: Array<{ label: ReactNode; href?: string }>; className?: string };

/** Where you are, and the way back. Never more than three levels deep. */
export function Breadcrumb({ items, className }: BreadcrumbProps) {
    return (
        <nav aria-label="Breadcrumb" className={cn("flex min-w-0 items-center gap-1 text-label-md text-on-surface-variant", className)}>
            {items.map((item, i) => (
                <span key={i} className="flex min-w-0 items-center gap-1">
                    {i > 0 ? (
                        <span aria-hidden className="opacity-50">
                            /
                        </span>
                    ) : null}
                    {item.href ? (
                        <a
                            href={item.href}
                            className="truncate rounded-extra-small px-1 py-0.5 transition-colors duration-short2 ease-standard hover:bg-on-surface/[0.08] hover:text-on-surface focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-primary"
                        >
                            {item.label}
                        </a>
                    ) : (
                        <span aria-current="page" className="truncate px-1 py-0.5 text-on-surface">
                            {item.label}
                        </span>
                    )}
                </span>
            ))}
        </nav>
    );
}

"use client";

import { useId, useMemo, useState, type PointerEvent } from "react";
import { cn } from "../cn";

/**
 * Charts in plain SVG: no chart library (they start at 100 KB). Every chart
 * draws in the look's own colours, follows light/dark, and carries a hidden
 * table of its numbers, so a screen reader gets the data, not "image".
 *
 * Series colours walk the colour roles, so a look with a pink `soft` and a
 * lime `pop` gets pink and lime lines, and Ink gets black and greys.
 */
const SERIES = [
    "var(--md-sys-color-primary)",
    "var(--md-sys-color-tertiary)",
    "var(--md-sys-color-secondary)",
    "var(--md-sys-color-outline)",
    "var(--md-sys-color-on-surface-variant)",
];
export const seriesColour = (i: number) => SERIES[i % SERIES.length];

export type Series = { name: string; values: number[] };
type Fmt = (n: number) => string;
const plain: Fmt = (n) => n.toLocaleString();

/** A round top for the axis: 0-87 → 0-100, so gridlines land on whole numbers. */
function niceMax(n: number): number {
    if (n <= 0) return 1;
    const p = 10 ** Math.floor(Math.log10(n));
    return ([1, 2, 2.5, 5, 10].find((m) => m * p >= n) ?? 10) * p;
}

function DataTable({ label, labels, series, format }: { label: string; labels: string[]; series: Series[]; format: Fmt }) {
    return (
        <table className="sr-only">
            <caption>{label}</caption>
            <thead><tr><th scope="col">Label</th>{series.map((s) => <th key={s.name} scope="col">{s.name}</th>)}</tr></thead>
            <tbody>{labels.map((l, i) => <tr key={l + i}><th scope="row">{l}</th>{series.map((s) => <td key={s.name}>{format(s.values[i] ?? 0)}</td>)}</tr>)}</tbody>
        </table>
    );
}

export function ChartLegend({ series, className }: { series: { name: string }[]; className?: string }) {
    if (series.length < 2) return null;
    return (
        <ul className={cn("flex flex-wrap gap-x-4 gap-y-1", className)}>
            {series.map((s, i) => (
                <li key={s.name} className="flex items-center gap-2 text-label-md text-on-surface-variant">
                    <span aria-hidden className="h-2.5 w-2.5" style={{ background: seriesColour(i) }} />
                    {s.name}
                </li>
            ))}
        </ul>
    );
}

/* ── Sparkline ────────────────────────────────────────────────────────── */

/** A trend in a line, no axes: inside a metric, a table cell. */
export function Sparkline({ values, label, className }: { values: number[]; label: string; className?: string }) {
    const max = Math.max(...values, 1);
    const min = Math.min(...values, 0);
    const pts = values.map((v, i) => `${(i / Math.max(values.length - 1, 1)) * 100},${30 - ((v - min) / (max - min || 1)) * 28 - 1}`).join(" ");
    return (
        <svg viewBox="0 0 100 30" preserveAspectRatio="none" role="img" aria-label={label} className={cn("h-8 w-24 overflow-visible", className)}>
            <polyline points={pts} fill="none" stroke="currentColor" strokeWidth={1.5} vectorEffect="non-scaling-stroke" strokeLinejoin="round" />
        </svg>
    );
}

/* ── Line / area ──────────────────────────────────────────────────────── */

export type LineChartProps = {
    /** What the chart shows, said once: "Money spent per day". */
    label: string;
    /** One per point on the x axis. */
    labels: string[];
    series: Series[];
    /** Fill under the first line. */
    area?: boolean;
    format?: Fmt;
    height?: number;
    className?: string;
};

/**
 * Lines over time. Hover or drag a finger across it: a rule follows and the
 * numbers for that point show above the chart, never covering the line.
 */
export function LineChart({ label, labels, series, area = true, format = plain, height = 220, className }: LineChartProps) {
    const id = useId().replace(/:/g, "");
    const [at, setAt] = useState<number | null>(null);
    const max = useMemo(() => niceMax(Math.max(0, ...series.flatMap((s) => s.values))), [series]);
    const n = Math.max(labels.length - 1, 1);
    const x = (i: number) => (i / n) * 100;
    const y = (v: number) => 100 - (v / max) * 100;
    const line = (vals: number[]) => vals.map((v, i) => `${i ? "L" : "M"}${x(i)},${y(v)}`).join("");

    const onMove = (e: PointerEvent<HTMLDivElement>) => {
        const r = e.currentTarget.getBoundingClientRect();
        setAt(Math.round(((e.clientX - r.left) / r.width) * n));
    };
    const shown = at ?? labels.length - 1;

    return (
        <figure className={cn("flex min-w-0 flex-col gap-3", className)}>
            <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
                <figcaption className="text-label-lg text-on-surface-variant">
                    {labels[shown]}
                </figcaption>
                <p className="flex flex-wrap gap-x-4 text-title-md tnum text-on-surface" aria-live="polite">
                    {series.map((s, i) => (
                        <span key={s.name} className="flex items-center gap-1.5">
                            {series.length > 1 && <span aria-hidden className="h-2.5 w-2.5" style={{ background: seriesColour(i) }} />}
                            {format(s.values[shown] ?? 0)}
                        </span>
                    ))}
                </p>
            </div>
            <div className="flex gap-2">
                <div className="flex flex-col justify-between py-0 text-right text-label-sm tnum text-on-surface-variant" style={{ height }} aria-hidden>
                    <span>{format(max)}</span>
                    <span>{format(max / 2)}</span>
                    <span>0</span>
                </div>
                <div className="relative min-w-0 flex-1 touch-pan-y" style={{ height }} onPointerMove={onMove} onPointerLeave={() => setAt(null)} onPointerDown={onMove}>
                    <svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label={label} className="absolute inset-0 h-full w-full overflow-visible">
                        <defs>
                            <linearGradient id={`fill-${id}`} x1="0" x2="0" y1="0" y2="1">
                                <stop offset="0" stopColor={seriesColour(0)} stopOpacity={0.18} />
                                <stop offset="1" stopColor={seriesColour(0)} stopOpacity={0} />
                            </linearGradient>
                        </defs>
                        {[0, 50, 100].map((g) => (
                            <line key={g} x1={0} x2={100} y1={g} y2={g} stroke="var(--md-sys-color-outline-variant)" strokeWidth={1} vectorEffect="non-scaling-stroke" />
                        ))}
                        {area && series[0] ? <path d={`${line(series[0].values)}L100,100L0,100Z`} fill={`url(#fill-${id})`} /> : null}
                        {series.map((s, i) => (
                            <path key={s.name} d={line(s.values)} fill="none" stroke={seriesColour(i)} strokeWidth={2} strokeDasharray={i ? "5 4" : undefined} vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" />
                        ))}
                        {at !== null ? <line x1={x(at)} x2={x(at)} y1={0} y2={100} stroke="var(--md-sys-color-on-surface)" strokeWidth={1} vectorEffect="non-scaling-stroke" /> : null}
                    </svg>
                    {at !== null && series.map((s, i) => (
                        <span key={s.name} aria-hidden className="pointer-events-none absolute h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 ring-2 ring-surface" style={{ left: `${x(at)}%`, top: `${y(s.values[at] ?? 0)}%`, background: seriesColour(i) }} />
                    ))}
                </div>
            </div>
            <div className="flex justify-between pl-8 text-label-sm text-on-surface-variant" aria-hidden>
                <span>{labels[0]}</span>
                {labels.length > 2 && <span>{labels[Math.floor(labels.length / 2)]}</span>}
                <span>{labels[labels.length - 1]}</span>
            </div>
            <ChartLegend series={series} />
            <DataTable label={label} labels={labels} series={series} format={format} />
        </figure>
    );
}

/* ── Bars ─────────────────────────────────────────────────────────────── */

export type BarChartProps = {
    label: string;
    labels: string[];
    series: Series[];
    /** Stack the series in one bar instead of side by side. */
    stacked?: boolean;
    format?: Fmt;
    height?: number;
    className?: string;
};

/** Amounts side by side. Bars are HTML, so each one has a real tooltip and hover. */
export function BarChart({ label, labels, series, stacked, format = plain, height = 220, className }: BarChartProps) {
    const totals = labels.map((_, i) => series.reduce((t, s) => t + (s.values[i] ?? 0), 0));
    const max = niceMax(stacked ? Math.max(0, ...totals) : Math.max(0, ...series.flatMap((s) => s.values)));
    return (
        <figure className={cn("flex min-w-0 flex-col gap-3", className)}>
            <figcaption className="sr-only">{label}</figcaption>
            <div className="flex gap-2">
                <div className="flex flex-col justify-between text-right text-label-sm tnum text-on-surface-variant" style={{ height }} aria-hidden>
                    <span>{format(max)}</span>
                    <span>{format(max / 2)}</span>
                    <span>0</span>
                </div>
                <div aria-hidden className="relative flex min-w-0 flex-1 items-end gap-[4%] border-b border-outline-variant" style={{ height }}>
                    {labels.map((l, i) => (
                        <div key={l + i} title={`${l}: ${series.map((s) => `${series.length > 1 ? s.name + " " : ""}${format(s.values[i] ?? 0)}`).join(", ")}`} className={cn("group flex h-full min-w-0 flex-1 items-end", stacked ? "flex-col-reverse justify-start" : "gap-[6%]")}>
                            {series.map((s, k) => (
                                <span
                                    key={s.name}
                                    className="block w-full min-w-[3px] transition-opacity group-hover:opacity-80"
                                    style={{ height: `${((s.values[i] ?? 0) / max) * 100}%`, background: seriesColour(k) }}
                                />
                            ))}
                        </div>
                    ))}
                </div>
            </div>
            <div aria-hidden className="flex gap-[4%] pl-8 text-label-sm text-on-surface-variant">
                {labels.map((l, i) => (
                    <span key={l + i} className={cn("min-w-0 flex-1 truncate text-center", labels.length > 8 && i % Math.ceil(labels.length / 6) !== 0 && "invisible")}>{l}</span>
                ))}
            </div>
            <ChartLegend series={series} />
            <DataTable label={label} labels={labels} series={series} format={format} />
        </figure>
    );
}

/* ── Donut ────────────────────────────────────────────────────────────── */

export type DonutChartProps = {
    label: string;
    parts: { label: string; value: number }[];
    /** The big word in the middle. Defaults to the total. */
    center?: string;
    format?: Fmt;
    className?: string;
};

/** Parts of a whole, at most five. More than five reads better as bars. */
export function DonutChart({ label, parts, center, format = plain, className }: DonutChartProps) {
    const total = parts.reduce((t, p) => t + p.value, 0) || 1;
    let run = 0;
    const C = 2 * Math.PI * 40;
    return (
        <figure className={cn("flex min-w-0 flex-wrap items-center gap-6", className)}>
            <div className="relative h-40 w-40 shrink-0">
                <svg viewBox="0 0 100 100" role="img" aria-label={label} className="h-full w-full -rotate-90">
                    <circle cx={50} cy={50} r={40} fill="none" stroke="var(--md-sys-color-surface-container-highest)" strokeWidth={14} />
                    {parts.map((p, i) => {
                        const len = (p.value / total) * C;
                        const el = <circle key={p.label} cx={50} cy={50} r={40} fill="none" stroke={seriesColour(i)} strokeWidth={14} strokeDasharray={`${Math.max(len - 1, 0)} ${C}`} strokeDashoffset={-run} />;
                        run += len;
                        return el;
                    })}
                </svg>
                <span className="absolute inset-0 flex items-center justify-center text-title-lg tnum text-on-surface">{center ?? format(total)}</span>
            </div>
            <figcaption className="flex min-w-0 flex-col gap-2">
                <span className="sr-only">{label}</span>
                {parts.map((p, i) => (
                    <span key={p.label} className="flex items-center gap-2 text-body-md text-on-surface">
                        <span aria-hidden className="h-2.5 w-2.5 shrink-0" style={{ background: seriesColour(i) }} />
                        <span className="min-w-0 flex-1 truncate">{p.label}</span>
                        <span className="tnum text-on-surface-variant">{format(p.value)} · {Math.round((p.value / total) * 100)}%</span>
                    </span>
                ))}
            </figcaption>
        </figure>
    );
}

"use client";

import { forwardRef, useId, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { Check, Minus } from "@/ui/symbols";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { useFieldState } from "./Field";
import { focusRing, interactive } from "../state-layer";

/**
 * M3 selection controls —
 * https://m3.material.io/components/checkbox · /radio-button · /switch
 *
 * All three are a real `<input>` underneath, visually hidden and driven with
 * `peer-*`. That is what keeps the browser's own behaviour: form submission,
 * `:checked`, the label click target, keyboard, autofill and — for radios —
 * arrow-key roving within a name group, which a `role="radio"` div has to
 * re-implement and usually gets wrong.
 *
 * Every one carries a 48dp touch target without a 48dp visual box.
 */

/** The real control, off-screen but still focusable and still the form's value. */
const HIDDEN = "peer sr-only";

/* ── Checkbox ─────────────────────────────────────────────────────────── */

export type CheckboxProps = Omit<ComponentPropsWithoutRef<"input">, "type" | "size"> & {
    label: ReactNode;
    /** Under the label: what choosing this means. */
    hint?: ReactNode;
    /** Some-but-not-all of a group. Renders the M3 dash. */
    indeterminate?: boolean;
    className?: string;
};

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(function Checkbox(
    { label, hint, indeterminate, className, ...rest },
    ref,
) {
    const field = useFieldState();
    const uid = useId();
    const id = rest.id ?? `cb-${uid}`;
    return (
        <div className={cn("flex min-w-0 items-start gap-1", className)}>
            <input
                ref={node => {
                    if (node) node.indeterminate = Boolean(indeterminate);
                    if (typeof ref === "function") ref(node);
                    else if (ref) ref.current = node;
                }}
                type="checkbox"
                id={id}
                disabled={rest.disabled ?? field?.disabled}
                aria-describedby={rest["aria-describedby"] ?? (hint ? `${id}-hint` : field?.describedBy)}
                className={HIDDEN}
                {...rest}
            />
            <label
                htmlFor={id}
                className={cn(
                    "-ml-3.5 flex h-12 w-12 shrink-0 cursor-pointer items-center justify-center rounded-full",
                    "text-on-surface-variant peer-checked:text-primary peer-indeterminate:text-primary",
                    "peer-disabled:cursor-not-allowed peer-disabled:opacity-[0.38]",
                    "peer-focus-visible:outline peer-focus-visible:outline-[3px] peer-focus-visible:outline-offset-[-6px] peer-focus-visible:outline-primary",
                    /* Checked/indeterminate reach the box and the glyph through
                       the label — the only element the input can select. */
                    "peer-checked:[&>span]:bg-current peer-indeterminate:[&>span]:bg-current",
                    "peer-checked:[&_[data-check]]:block peer-indeterminate:[&_[data-dash]]:block",
                    "m3-state",
                )}
            >
                {/* The 18dp box M3 draws. The 48dp label around it is the target. */}
                <span aria-hidden className="flex h-[18px] w-[18px] items-center justify-center rounded-extra-small border-2 border-current transition-[background-color] duration-short4 ease-standard">
                    <Icon icon={Check} width={14} height={14} strokeWidth={3} aria-hidden data-check className="hidden text-on-primary" />
                    <Icon icon={Minus} width={14} height={14} strokeWidth={3} aria-hidden data-dash className="hidden text-on-primary" />
                </span>
            </label>
            <label htmlFor={id} className="min-w-0 cursor-pointer py-3 peer-disabled:cursor-not-allowed peer-disabled:opacity-[0.38]">
                <span className="block text-body-lg text-on-surface">{label}</span>
                {hint ? (
                    <span id={`${id}-hint`} className="block text-body-sm text-on-surface-variant">
                        {hint}
                    </span>
                ) : null}
            </label>
        </div>
    );
});

/* ── Radio ────────────────────────────────────────────────────────────── */

