/**
 * The one colour picker (owner, 2026-10-04: "ours, native, super easy, like
 * the big apps - unified everywhere").
 *
 *   ┌────────────────────┐
 *   │  saturation/light  │  drag anywhere, arrow keys too
 *   ├────────────────────┤
 *   │  hue ▬▬▬▬▬▬▬▬▬▬▬▬  │
 *   │  💧  HEX  R  G  B  │  eyedropper (where the browser has one), type a value
 *   │ Colours·Palettes·… │  in use · recent · every hue · 19 palettes · gradients
 *   └────────────────────┘
 *
 * 🔴 Why not the browser's `<input type="color">`: its popup is a separate OS
 * window. A sheet or popover around it saw a tap on the picker's slider as a
 * tap OUTSIDE and closed, and an editor that re-rendered on every drag step
 * unmounted the input and killed the picker mid-drag. This picker is plain DOM
 * inside ours: a drag is captured by the square (`setPointerCapture`), so
 * leaving the panel while dragging never closes it.
 *
 * The colours are the person's artwork, not UI colours, so they are data here
 * (inline style), like Swatches.tsx. This folder is the one place hex lives.
 */

/* ── colour maths ─────────────────────────────────────────────────────── */

type Hsv = { h: number; s: number; v: number };
const clamp = (n: number, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, n));

/** `#abc`, `abc`, `#aabbcc` → `#aabbcc`, or null. */
export function parseHex(raw: string): string | null {
    const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
    if (!m) return null;
    const h = m[1].toLowerCase();
    return `#${h.length === 3 ? [...h].map((c) => c + c).join("") : h}`;
}

const toHex = (r: number, g: number, b: number) => `#${[r, g, b].map((x) => Math.round(clamp(x, 0, 255)).toString(16).padStart(2, "0")).join("")}`;

function hexToRgb(hex: string): [number, number, number] {
    const h = parseHex(hex) ?? "#000000";
    return [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)) as [number, number, number];
}

function hsvToRgb({ h, s, v }: Hsv): [number, number, number] {
    const f = (n: number) => {
        const k = (n + h / 60) % 6;
        return (v - v * s * Math.max(0, Math.min(k, 4 - k, 1))) * 255;
    };
    return [f(5), f(3), f(1)];
}

const hsvToHex = (c: Hsv) => toHex(...hsvToRgb(c));

function hexToHsv(hex: string): Hsv {
    const [r, g, b] = hexToRgb(hex).map((x) => x / 255);
    const max = Math.max(r, g, b), d = max - Math.min(r, g, b);
    let h = 0;
    if (d) h = max === r ? ((g - b) / d + 6) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
    return { h: h * 60, s: max ? d / max : 0, v: max };
}

function hslToHex(h: number, s: number, l: number) {
    const a = s * Math.min(l, 1 - l);
    const f = (n: number) => {
        const k = (n + h / 30) % 12;
        return (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))) * 255;
    };
    return toHex(f(0), f(8), f(4));
}

/** The colour is light enough that a dark tick reads on it. */
export function isLight(hex: string) {
    const [r, g, b] = hexToRgb(hex);
    return r * 0.299 + g * 0.587 + b * 0.114 > 150;
}

/* ── the data the panel offers ────────────────────────────────────────── */

/** Every hue in six steps, light to dark; then a grey ramp. Rows are steps, so a column is one colour. */
const HUES = [0, 20, 40, 55, 90, 140, 170, 200, 225, 255, 285, 320];
const STEPS = [0.88, 0.76, 0.64, 0.52, 0.4, 0.28];
const GREYS = ["#ffffff", "#f0f0f0", "#dcdcdc", "#c4c4c4", "#aaaaaa", "#909090", "#767676", "#5c5c5c", "#444444", "#2e2e2e", "#171717", "#000000"];
const GRID = [...STEPS.map((l) => HUES.map((h) => hslToHex(h, 0.78, l))), GREYS];

/** White and black: the two a background most often wants. */
export const BASIC_COLOURS = ["#ffffff", "#000000"];

export type Gradient = { from: string; to: string; /** CSS degrees: 180 = top to bottom. */ angle: number };

const GRADIENTS: [string, string][] = [
    ["#ff9a9e", "#fad0c4"], ["#f6d365", "#fda085"], ["#84fab0", "#8fd3f4"], ["#a18cd1", "#fbc2eb"], ["#fdcbf1", "#e6dee9"], ["#4facfe", "#00f2fe"],
    ["#43e97b", "#38f9d7"], ["#fa709a", "#fee140"], ["#667eea", "#764ba2"], ["#0f2027", "#2c5364"], ["#232526", "#414345"], ["#c33764", "#1d2671"],
    ["#f83600", "#f9d423"], ["#00c6fb", "#005bea"], ["#b721ff", "#21d4fd"], ["#ff0844", "#ffb199"], ["#ffffff", "#c9d6ff"], ["#134e5e", "#71b280"],
];

/** A gradient as CSS, for a swatch. */
export const gradientCss = (g: Gradient) => `linear-gradient(${g.angle}deg, ${g.from}, ${g.to})`;

const RECENT_KEY = "ship-recent-colours";
const readRecent = (): string[] => {
    try { const v = JSON.parse(localStorage.getItem(RECENT_KEY) || "[]"); return Array.isArray(v) ? v.filter((x) => typeof x === "string").slice(0, 12) : []; } catch { return []; }
};
const writeRecent = (hex: string) => {
    try { localStorage.setItem(RECENT_KEY, JSON.stringify([hex, ...readRecent().filter((x) => x !== hex)].slice(0, 12))); } catch { /* private window: no recents */ }
};

/* ── drag surface ─────────────────────────────────────────────────────── */

/**
 * One pointer drag over a box, reported as 0..1 in x and y. The box captures
 * the pointer, so the drag goes on outside the panel and a popover's light
 * dismiss never sees it.
 */
function dragProps(onMove: (x: number, y: number) => void, onEnd: () => void) {
    const at = (e: PointerEvent<HTMLElement>) => {
        const r = e.currentTarget.getBoundingClientRect();
        onMove(clamp((e.clientX - r.left) / r.width), clamp((e.clientY - r.top) / r.height));
    };
    return {
        onPointerDown: (e: PointerEvent<HTMLElement>) => {
            e.preventDefault();
            e.currentTarget.focus();
            e.currentTarget.setPointerCapture(e.pointerId);
            at(e);
        },
        onPointerMove: (e: PointerEvent<HTMLElement>) => { if (e.currentTarget.hasPointerCapture(e.pointerId)) at(e); },
        onPointerUp: (e: PointerEvent<HTMLElement>) => { if (e.currentTarget.hasPointerCapture(e.pointerId)) { e.currentTarget.releasePointerCapture(e.pointerId); onEnd(); } },
        onPointerCancel: onEnd,
    };
}

const SURFACE = "relative touch-none select-none rounded-medium";
const THUMB = "pointer-events-none absolute h-5 w-5 -translate-x-1/2 -translate-y-1/2 rounded-full";
const THUMB_RING: CSSProperties = { boxShadow: "0 0 0 2px #fff, 0 1px 5px 1px rgba(0,0,0,.55)" };

/* ── small controls ───────────────────────────────────────────────────── */

/** A text box for one value. Keeps what is being typed until it is a real value. */
function ValueBox({ label, value, onValid, parse, width, mono = true }: { label: string; value: string; onValid: (v: string) => void; parse: (raw: string) => string | null; width: string; mono?: boolean }) {
    const [typed, setTyped] = useState<string | null>(null);
    return (
        <label className={cn("flex min-w-0 flex-col gap-0.5", width)}>
            <input
                aria-label={label}
                value={typed ?? value}
                spellCheck={false}
                autoComplete="off"
                inputMode={label === "Hex" ? "text" : "numeric"}
                onFocus={(e) => e.currentTarget.select()}
                onChange={(e) => {
                    setTyped(e.target.value);
                    const ok = parse(e.target.value);
                    if (ok) onValid(ok);
                }}
                onBlur={() => setTyped(null)}
                onKeyDown={(e) => { if (e.key === "Enter") e.currentTarget.blur(); }}
                className={cn("h-10 w-full min-w-0 rounded-small bg-surface-container-highest px-2 text-center text-body-md text-on-surface outline-none transition-shadow duration-short4 ease-standard focus:shadow-[inset_0_0_0_2px_var(--md-sys-color-primary)]", mono && "font-mono uppercase")}
            />
            <span className="text-center text-label-sm text-on-surface-variant">{label}</span>
        </label>
    );
}

/** One colour as a circle. The ring says it is the picked one. */
function Dot({ hex, on, onPick, size = "h-6 w-6", label }: { hex: string; on: boolean; onPick: () => void; size?: string; label?: string }) {
    return (
        <button
            type="button"
            aria-label={label ?? hex.toUpperCase()}
            title={label ?? hex.toUpperCase()}
            aria-pressed={on}
            onClick={onPick}
            style={{ backgroundColor: hex, color: isLight(hex) ? "#000" : "#fff" }}
            className={cn("grid shrink-0 place-items-center rounded-full ring-1 ring-outline-variant transition-transform duration-short4 ease-standard motion-safe:hover:scale-110", size, focusRing, on && "ring-2 ring-primary ring-offset-2 ring-offset-surface-container")}
        >
            {on ? <Icon icon={Check} size="sm" className="h-3.5 w-3.5" /> : null}
        </button>
    );
}

function Row({ title, children }: { title: string; children: ReactNode }) {
    return (
        <div className="flex flex-col gap-1.5">
            <p className="text-label-md text-on-surface-variant">{title}</p>
            <div className="flex flex-wrap gap-2">{children}</div>
        </div>
    );
}

/* ── the picker ───────────────────────────────────────────────────────── */

export type ColorPickerProps = {
    /** `#rrggbb`. */
    value: string;
    /** Fires on every step of a drag, lower-case `#rrggbb`. */
    onChange: (hex: string) => void;
    /** The colours already in use, shown first. */
    swatches?: string[];
    /** Adds a Gradients tab. Called with a ready gradient on every change. */
    onGradient?: (g: Gradient) => void;
    /** The gradient in use now, if the thing being coloured has one. */
    gradient?: Gradient | null;
    className?: string;
};

type Tab = "colours" | "palettes" | "gradients";

export function ColorPicker({ value, onChange, swatches, onGradient, gradient, className }: ColorPickerProps) {
    const hex = parseHex(value) ?? "#000000";
    const [hsv, setHsv] = useState<Hsv>(() => hexToHsv(hex));
    /** The last colour this panel produced or was given: tells a parent's change from our own. */
    const last = useRef(hex);
    useEffect(() => {
        if (hex !== last.current) { last.current = hex; setHsv(hexToHsv(hex)); }
    }, [hex]);

    const [tab, setTab] = useState<Tab>("colours");
    const [recent, setRecent] = useState<string[]>([]);
    useEffect(() => setRecent(readRecent()), []);
    const [dropper, setDropper] = useState(false);
    useEffect(() => setDropper(typeof window !== "undefined" && "EyeDropper" in window), []);

    const push = (next: Hsv) => {
        const out = hsvToHex(next);
        setHsv(next);
        last.current = out;
        onChange(out);
    };
    /** A whole colour picked from a list (not a drag): it becomes a recent one. */
    const pick = (raw: string) => {
        const h = parseHex(raw);
        if (!h) return;
        last.current = h;
        setHsv(hexToHsv(h));
        onChange(h);
        remember(h);
    };
    const remember = (h: string) => { writeRecent(h); setRecent(readRecent()); };
    const done = () => remember(last.current);

    const eyedrop = async () => {
        try {
            const r = await new (window as unknown as { EyeDropper: new () => { open: () => Promise<{ sRGBHex: string }> } }).EyeDropper().open();
            pick(r.sRGBHex);
        } catch { /* cancelled with Esc */ }
    };

    const [r, g, b] = hexToRgb(hex);
    const setChannel = (i: 0 | 1 | 2) => (raw: string) => {
        const n = clamp(Number(raw), 0, 255);
        const rgb: [number, number, number] = [r, g, b];
        rgb[i] = n;
        const h = toHex(...rgb);
        last.current = h;
        setHsv(hexToHsv(h));
        onChange(h);
    };
    const parseChannel = (raw: string) => (/^\d{1,3}$/.test(raw.trim()) && Number(raw) <= 255 ? raw.trim() : null);

    const key = (apply: (dx: number, dy: number) => void) => (e: KeyboardEvent) => {
        const step = e.shiftKey ? 0.1 : 0.01;
        const d: Record<string, [number, number]> = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
        const m = d[e.key];
        if (!m) return;
        e.preventDefault();
        apply(...m);
    };

    const own = useMemo(() => [...new Set((swatches ?? []).map((c) => parseHex(c)).filter((c): c is string => !!c))].slice(0, 12), [swatches]);
    const tabs = [{ value: "colours" as const, label: "Colours" }, { value: "palettes" as const, label: "Palettes" }, ...(onGradient ? [{ value: "gradients" as const, label: "Gradients" }] : [])];
    const angle = gradient?.angle ?? 180;
    const from = gradient?.from ?? hex;

    return (
        <div className={cn("flex w-full flex-col gap-3", className)}>
            {/* saturation (across) and brightness (down) */}
            <div
                role="slider"
                tabIndex={0}
                aria-label="Saturation and brightness"
                aria-valuetext={`Saturation ${Math.round(hsv.s * 100)} percent, brightness ${Math.round(hsv.v * 100)} percent`}
                aria-valuenow={Math.round(hsv.s * 100)}
                className={cn(SURFACE, "h-40 w-full", focusRing)}
                style={{ backgroundColor: hsvToHex({ h: hsv.h, s: 1, v: 1 }), backgroundImage: "linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent)" }}
                {...dragProps((x, y) => push({ ...hsv, s: x, v: 1 - y }), done)}
                onKeyDown={key((dx, dy) => push({ ...hsv, s: clamp(hsv.s + dx), v: clamp(hsv.v - dy) }))}
                onKeyUp={done}
            >
                <span className={THUMB} style={{ ...THUMB_RING, left: `${hsv.s * 100}%`, top: `${(1 - hsv.v) * 100}%`, backgroundColor: hex }} />
            </div>

            {/* hue */}
            <div
                role="slider"
                tabIndex={0}
                aria-label="Hue"
                aria-valuemin={0}
                aria-valuemax={360}
                aria-valuenow={Math.round(hsv.h)}
                className={cn(SURFACE, "h-6 w-full rounded-full", focusRing)}
                style={{ backgroundImage: "linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)" }}
                {...dragProps((x) => push({ ...hsv, h: x * 360 }), done)}
                onKeyDown={key((dx) => push({ ...hsv, h: (hsv.h + dx * 360 + 360) % 360 }))}
                onKeyUp={done}
            >
                <span className={cn(THUMB, "top-1/2")} style={{ ...THUMB_RING, left: `${(hsv.h / 360) * 100}%`, backgroundColor: hsvToHex({ h: hsv.h, s: 1, v: 1 }) }} />
            </div>

            {/* the value, typed or dropped */}
            <div className="flex items-start gap-2">
                <span className="mt-0.5 grid h-10 w-10 shrink-0 place-items-center">
                    {dropper ? (
                        <IconButton icon={Pipette} label="Pick a colour from the screen" size="sm" onClick={() => void eyedrop()} />
                    ) : (
                        <span aria-hidden className="h-8 w-8 rounded-full ring-1 ring-outline-variant" style={{ backgroundColor: hex }} />
                    )}
                </span>
                <ValueBox label="Hex" value={hex.slice(1)} width="flex-[2.2]" parse={(raw) => parseHex(raw)} onValid={(h) => pick(h)} />
                <ValueBox label="R" value={String(r)} width="flex-1" parse={parseChannel} onValid={setChannel(0)} />
                <ValueBox label="G" value={String(g)} width="flex-1" parse={parseChannel} onValid={setChannel(1)} />
                <ValueBox label="B" value={String(b)} width="flex-1" parse={parseChannel} onValid={setChannel(2)} />
            </div>

            {tabs.length > 1 ? (
                <SegmentedButton label="Colour source" value={tab} onChange={setTab} options={tabs} fullWidth />
            ) : null}

            {/* one fixed height, so the panel never grows under the finger */}
            <div className="h-44 overflow-y-auto overflow-x-hidden pr-1">
                {tab === "colours" ? (
                    <div className="flex flex-col gap-3">
                        {own.length ? <Row title="In use">{own.map((c) => <Dot key={c} hex={c} on={c === hex} onPick={() => pick(c)} />)}</Row> : null}
                        {recent.length ? <Row title="Recent">{recent.map((c) => <Dot key={c} hex={c} on={c === hex} onPick={() => pick(c)} />)}</Row> : null}
                        <div className="flex flex-col gap-1.5">
                            <p className="text-label-md text-on-surface-variant">Every colour</p>
                            <div className="flex flex-col gap-1">
                                {GRID.map((row, i) => (
                                    <div key={i} className="grid gap-1" style={{ gridTemplateColumns: `repeat(${HUES.length}, minmax(0, 1fr))` }}>
                                        {row.map((c) => <Dot key={c} hex={c} on={c === hex} onPick={() => pick(c)} size="aspect-square w-full" />)}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : tab === "palettes" ? (
                    <div className="flex flex-col gap-3">
                        {palettes.map((p) => (
                            <Row key={p.id} title={p.name}>{p.colors.map((c) => { const h = parseHex(c) ?? c; return <Dot key={c} hex={h} on={h === hex} onPick={() => pick(h)} size="h-8 w-8" />; })}</Row>
                        ))}
                    </div>
                ) : (
                    <div className="flex flex-col gap-3">
                        <Slider
                            label="Direction"
                            valueLabel={`${angle}°`}
                            min={0}
                            max={345}
                            step={15}
                            disabled={!gradient}
                            value={angle}
                            onChange={(e) => onGradient?.({ from: gradient?.from ?? from, to: gradient?.to ?? hex, angle: Number(e.target.value) })}
                        />
                        <div className="grid grid-cols-3 gap-2">
                            {GRADIENTS.map(([a, z]) => {
                                const on = gradient?.from === a && gradient?.to === z;
                                return (
                                    <button
                                        key={a + z}
                                        type="button"
                                        aria-label={`Gradient ${a} to ${z}`}
                                        aria-pressed={on}
                                        onClick={() => onGradient?.({ from: a, to: z, angle })}
                                        className={cn("h-12 rounded-medium ring-1 ring-outline-variant", focusRing, on && "ring-2 ring-primary ring-offset-2 ring-offset-surface-container")}
                                        style={{ backgroundImage: gradientCss({ from: a, to: z, angle }) }}
                                    />
                                );
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

/* ── the picker in a popover ──────────────────────────────────────────── */

/** The panel's box: a fixed width so a phone gets all of it and a desktop gets a tidy card. */
const PANEL = "w-[19rem] max-h-[min(34rem,calc(100dvh-1rem))] max-w-[calc(100vw-1rem)] p-3";

export type ColorPopoverProps = Omit<ColorPickerProps, "className"> & {
    /** What the colour is for, e.g. "Background colour". Names the panel and the default button. */
    label: string;
    /** The control that opens it. Default: the colour as a circle. */
    trigger?: (props: PopoverTriggerProps & { value: string }) => ReactNode;
    placement?: Placement;
    /** Once, when the panel closes on a different colour than it opened with. */
    onCommit?: (hex: string) => void;
    /** Told when the panel opens and closes (to open and close an undo step). */
    onOpenChange?: (open: boolean) => void;
    triggerClassName?: string;
};

/**
 * Click the colour, get the picker. Drawn only while open (a screen with
 * twenty of these does not hold twenty panels).
 */
export function ColorPopover({ label, value, trigger, placement = "bottom-start", onCommit, onOpenChange, triggerClassName, ...picker }: ColorPopoverProps) {
    const [open, setOpen] = useState(false);
    const start = useRef(value);
    const now = useRef(value);
    now.current = value;
    return (
        <Popover
            label={label}
            placement={placement}
            className={PANEL}
            onOpenChange={(o) => {
                setOpen(o);
                if (o) start.current = now.current;
                else if (parseHex(now.current) !== parseHex(start.current)) onCommit?.(now.current);
                onOpenChange?.(o);
            }}
            trigger={(p) =>
                trigger ? trigger({ ...p, value }) : (
                    <button
                        type="button"
                        {...p}
                        aria-label={`${label}: ${value.toUpperCase()}`}
                        title={label}
                        style={{ backgroundColor: value }}
                        className={cn("h-10 w-10 shrink-0 rounded-full ring-1 ring-outline-variant", touchTarget, focusRing, triggerClassName)}
                    />
                )
            }
        >
            {open ? <ColorPicker value={value} {...picker} /> : null}
        </Popover>
    );
}

"use client";

import { useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { cn } from "../cn";
import { Icon, type IconGlyph } from "../primitives/Icon";
import { Check, ChevronDown, Plus, X } from "../symbols";
import { fuzzy } from "./CommandMenu";

export type Option = { value: string; label: string; description?: string; icon?: IconGlyph };

type ListProps = {
    id: string;
    options: Option[];
    active: number;
    selected: (v: string) => boolean;
    onPick: (o: Option) => void;
    onHover: (i: number) => void;
    empty: string;
    create?: string | null;
    multi?: boolean;
};

/** The dropdown both pickers share. Clicks never steal focus from the field. */
function List({ id, options, active, selected, onPick, onHover, empty, create, multi }: ListProps) {
    return (
        <ul
            id={id}
            role="listbox"
            aria-multiselectable={multi || undefined}
            onMouseDown={(e) => e.preventDefault()}
            className="absolute inset-x-0 top-full z-30 mt-1 max-h-64 overflow-y-auto rounded-medium bg-surface-container-lowest p-1.5 shadow-level-3 dark:bg-surface-container-high"
        >
            {options.map((o, i) => (
                <li
                    key={o.value}
                    id={`${id}-${i}`}
                    role="option"
                    aria-selected={selected(o.value)}
                    onMouseMove={() => onHover(i)}
                    onClick={() => onPick(o)}
                    className={cn("flex min-h-12 cursor-pointer items-center gap-3 rounded-small px-3 text-body-md text-on-surface", i === active && "bg-on-surface/[0.08]")}
                >
                    {o.icon ? <Icon icon={o.icon} className="text-on-surface-variant" /> : null}
                    <span className="min-w-0 flex-1">
                        <span className="block truncate">{o.label}</span>
                        {o.description ? <span className="block truncate text-label-md text-on-surface-variant">{o.description}</span> : null}
                    </span>
                    {selected(o.value) ? <Icon icon={Check} className="text-on-surface" /> : null}
                </li>
            ))}
            {create ? (
                <li
                    id={`${id}-${options.length}`}
                    role="option"
                    aria-selected={false}
                    onMouseMove={() => onHover(options.length)}
                    onClick={() => onPick({ value: create, label: create })}
                    className={cn("flex min-h-12 cursor-pointer items-center gap-3 rounded-small px-3 text-body-md text-on-surface", active === options.length && "bg-on-surface/[0.08]")}
                >
                    <Icon icon={Plus} className="text-on-surface-variant" />
                    Add “{create}”
                </li>
            ) : null}
            {!options.length && !create ? <li className="px-3 py-3 text-body-md text-on-surface-variant">{empty}</li> : null}
        </ul>
    );
}

/** Typing, open state, the highlighted row and the keys, for both pickers. */
function usePicker(options: Option[], creatable: boolean, has: (v: string) => boolean) {
    const [q, setQ] = useState("");
    const [open, setOpen] = useState(false);
    const [active, setActive] = useState(0);
    const shown = useMemo(
        () => (q ? options.map((o) => ({ o, s: Math.max(fuzzy(q, o.label), fuzzy(q, o.value)) })).filter((x) => x.s > 0).sort((a, b) => b.s - a.s).map((x) => x.o) : options),
        [options, q],
    );
    const create = creatable && q.trim() && !options.some((o) => o.label.toLowerCase() === q.trim().toLowerCase()) && !has(q.trim()) ? q.trim() : null;
    const count = shown.length + (create ? 1 : 0);
    return { q, setQ, open, setOpen, active, setActive, shown, create, count };
}

const FIELD = "relative flex min-h-14 w-full min-w-0 flex-wrap items-center gap-1.5 rounded-small bg-surface-container px-3 py-2 hover:bg-surface-container-high focus-within:bg-surface-container-lowest focus-within:shadow-[inset_0_0_0_1px_var(--md-sys-color-primary),0_0_0_3px_rgb(var(--md-sys-color-primary-rgb)/0.18)] dark:focus-within:bg-surface-container-low";

export type MultiSelectProps = {
    label: string;
    options: Option[];
    value: string[];
    onChange: (value: string[]) => void;
    /** Let people add a value that isn't in the list (tags). */
    creatable?: boolean;
    max?: number;
    hint?: ReactNode;
    empty?: string;
    /** Sends each value as a hidden field with this name. */
    name?: string;
    className?: string;
};

/**
 * Pick several: chips in the field, a filtered list under it. Backspace in an
 * empty field removes the last chip; Enter picks the highlighted row.
 */
export function MultiSelect({ label, options, value, onChange, creatable, max, hint, empty = "No matches.", name, className }: MultiSelectProps) {
    const uid = useId();
    const input = useRef<HTMLInputElement>(null);
    const has = (v: string) => value.includes(v);
    const p = usePicker(options, Boolean(creatable), has);
    const full = max !== undefined && value.length >= max;
    const labelOf = (v: string) => options.find((o) => o.value === v)?.label ?? v;

    const toggle = (o: Option) => {
        if (has(o.value)) onChange(value.filter((v) => v !== o.value));
        else if (!full) onChange([...value, o.value]);
        p.setQ("");
        input.current?.focus();
    };
    const onKey = (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") { e.preventDefault(); p.setOpen(true); p.setActive((a) => Math.min(a + 1, p.count - 1)); }
        else if (e.key === "ArrowUp") { e.preventDefault(); p.setActive((a) => Math.max(a - 1, 0)); }
        else if (e.key === "Enter" && p.open && p.count) {
            e.preventDefault();
            toggle(p.active < p.shown.length ? p.shown[p.active] : { value: p.create!, label: p.create! });
        } else if (e.key === "Backspace" && !p.q && value.length) onChange(value.slice(0, -1));
        else if (e.key === "Escape") p.setOpen(false);
    };

    return (
        <div className={cn("flex min-w-0 flex-col gap-1", className)}>
            <label htmlFor={uid} className="px-1 text-label-md text-on-surface-variant">{label}</label>
            <div className={FIELD} onClick={() => input.current?.focus()}>
                {value.map((v) => (
                    <span key={v} className="inline-flex h-8 max-w-full items-center gap-1 rounded-small bg-on-surface/[0.07] pl-2.5 pr-1 text-label-lg text-on-surface">
                        <span className="truncate">{labelOf(v)}</span>
                        <button type="button" aria-label={`Remove ${labelOf(v)}`} onClick={(e) => { e.stopPropagation(); onChange(value.filter((x) => x !== v)); }} className="inline-flex h-6 w-6 items-center justify-center rounded-extra-small hover:bg-on-surface/[0.08]">
                            <Icon icon={X} size="sm" />
                        </button>
                    </span>
                ))}
                <input
                    ref={input}
                    id={uid}
                    value={p.q}
                    disabled={full}
                    placeholder={full ? `Up to ${max}` : value.length ? "" : "Type to search"}
                    onChange={(e) => { p.setQ(e.target.value); p.setOpen(true); p.setActive(0); }}
                    onFocus={() => p.setOpen(true)}
                    onBlur={() => p.setOpen(false)}
                    onKeyDown={onKey}
                    role="combobox"
                    aria-expanded={p.open}
                    aria-controls={`${uid}-list`}
                    aria-activedescendant={p.open && p.count ? `${uid}-list-${p.active}` : undefined}
                    className="h-8 min-w-[6rem] flex-1 bg-transparent text-body-lg text-on-surface outline-none placeholder:text-on-surface-variant"
                />
                {p.open && !full ? (
                    <List id={`${uid}-list`} options={p.shown} active={p.active} selected={has} onPick={toggle} onHover={p.setActive} empty={empty} create={p.create} multi />
                ) : null}
            </div>
            {hint ? <p className="px-1 text-body-sm text-on-surface-variant">{hint}</p> : null}
            {name ? value.map((v) => <input key={v} type="hidden" name={name} value={v} />) : null}
        </div>
    );
}

export type ComboboxProps = Omit<MultiSelectProps, "value" | "onChange" | "max"> & {
    value: string | null;
    onChange: (value: string | null) => void;
};

/** Pick one from a long list by typing: a country, a timezone, a member. */
export function Combobox({ label, options, value, onChange, creatable, hint, empty = "No matches.", name, className }: ComboboxProps) {
    const uid = useId();
    const has = (v: string) => v === value;
    const p = usePicker(options, Boolean(creatable), has);
    const current = options.find((o) => o.value === value)?.label ?? value ?? "";

    const pick = (o: Option) => { onChange(o.value); p.setQ(""); p.setOpen(false); };
    const onKey = (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "ArrowDown") { e.preventDefault(); p.setOpen(true); p.setActive((a) => Math.min(a + 1, p.count - 1)); }
        else if (e.key === "ArrowUp") { e.preventDefault(); p.setActive((a) => Math.max(a - 1, 0)); }
        else if (e.key === "Enter" && p.open && p.count) { e.preventDefault(); pick(p.active < p.shown.length ? p.shown[p.active] : { value: p.create!, label: p.create! }); }
        else if (e.key === "Escape") { p.setOpen(false); p.setQ(""); }
    };

    return (
        <div className={cn("flex min-w-0 flex-col gap-1", className)}>
            <label htmlFor={uid} className="px-1 text-label-md text-on-surface-variant">{label}</label>
            <div className={FIELD}>
                <input
                    id={uid}
                    value={p.open ? p.q : current}
                    placeholder={current || "Type to search"}
                    onChange={(e) => { p.setQ(e.target.value); p.setOpen(true); p.setActive(0); }}
                    onFocus={() => p.setOpen(true)}
                    onBlur={() => { p.setOpen(false); p.setQ(""); }}
                    onKeyDown={onKey}
                    role="combobox"
                    aria-expanded={p.open}
                    aria-controls={`${uid}-list`}
                    aria-activedescendant={p.open && p.count ? `${uid}-list-${p.active}` : undefined}
                    className="h-10 min-w-0 flex-1 bg-transparent text-body-lg text-on-surface outline-none placeholder:text-on-surface-variant"
                />
                <Icon icon={ChevronDown} className="pointer-events-none text-on-surface-variant" />
                {p.open ? <List id={`${uid}-list`} options={p.shown} active={p.active} selected={has} onPick={pick} onHover={p.setActive} empty={empty} create={p.create} /> : null}
            </div>
            {hint ? <p className="px-1 text-body-sm text-on-surface-variant">{hint}</p> : null}
            {name ? <input type="hidden" name={name} value={value ?? ""} /> : null}
        </div>
    );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { useRouter } from "next/navigation";
import { cn } from "../cn";
import { Icon, type IconGlyph } from "../primitives/Icon";
import { Kbd } from "../primitives/Skeleton";
import { Search as SearchIcon } from "../symbols";

export type CommandItem = {
    id: string;
    label: string;
    /** The heading it sits under: "Pages", "Actions", "Account". */
    group?: string;
    icon?: IconGlyph;
    /** Other words that should find it: "billing" finds "Top up". */
    keywords?: string[];
    /** Shown on the right, e.g. ["G", "D"]. Display only. */
    shortcut?: string[];
    href?: string;
    onSelect?: () => void;
};

/** How well `q` matches `text`: letters in order, earlier and closer is better. 0 = no match. */
export function fuzzy(q: string, text: string): number {
    q = q.toLowerCase(); text = text.toLowerCase();
    if (!q) return 1;
    const at = text.indexOf(q);
    if (at >= 0) return 100 - at;
    let score = 0, last = -1;
    for (const ch of q) {
        const i = text.indexOf(ch, last + 1);
        if (i < 0) return 0;
        score += i === last + 1 ? 3 : 1;
        last = i;
    }
    return score;
}

/** ⌘K on a Mac, Ctrl+K elsewhere. Typing in a field doesn't trigger it. */
export function useCommandHotkey(open: () => void, key = "k") {
    useEffect(() => {
        const on = (e: globalThis.KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === key) { e.preventDefault(); open(); }
        };
        window.addEventListener("keydown", on);
        return () => window.removeEventListener("keydown", on);
    }, [open, key]);
}

export type CommandMenuProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    items: CommandItem[];
    placeholder?: string;
    /** What the list says when nothing matches. */
    empty?: string;
};

/**
 * The command menu: one box that finds any page or action. A native modal
 * <dialog>, so Esc, the focus trap and the dimmed page come from the browser.
 * The list is a real listbox; the field keeps focus and arrows move the pick.
 */
export function CommandMenu({ open, onOpenChange, items, placeholder = "Search pages and actions", empty = "Nothing found. Try another word." }: CommandMenuProps) {
    const router = useRouter();
    const dialog = useRef<HTMLDialogElement>(null);
    const field = useRef<HTMLInputElement>(null);
    const list = useRef<HTMLUListElement>(null);
    const uid = useId();
    const [q, setQ] = useState("");
    const [active, setActive] = useState(0);

    useEffect(() => {
        const d = dialog.current;
        if (!d) return;
        if (open && !d.open) { d.showModal(); setQ(""); setActive(0); requestAnimationFrame(() => field.current?.focus()); }
        if (!open && d.open) d.close();
    }, [open]);

    const shown = useMemo(() => {
        const scored = items
            .map((it) => ({ it, s: Math.max(fuzzy(q, it.label), ...(it.keywords ?? []).map((k) => fuzzy(q, k) * 0.8)) }))
            .filter((x) => x.s > 0);
        if (q) scored.sort((a, b) => b.s - a.s);
        return scored.map((x) => x.it);
    }, [items, q]);

    /* Group in the order groups first appear, so the best match's group leads. */
    const groups = useMemo(() => {
        const m = new Map<string, CommandItem[]>();
        for (const it of shown) m.set(it.group ?? "", [...(m.get(it.group ?? "") ?? []), it]);
        return [...m.entries()];
    }, [shown]);
    const flat = groups.flatMap(([, g]) => g);

    useEffect(() => { setActive(0); }, [q]);
    useEffect(() => {
        list.current?.querySelector(`[data-i="${active}"]`)?.scrollIntoView({ block: "nearest" });
    }, [active]);

    const run = (it: CommandItem | undefined) => {
        if (!it) return;
        onOpenChange(false);
        if (it.href) router.push(it.href);
        it.onSelect?.();
    };

    const onKey = (e: KeyboardEvent) => {
        if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => Math.min(a + 1, flat.length - 1)); }
        if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(a - 1, 0)); }
        if (e.key === "Home") { e.preventDefault(); setActive(0); }
        if (e.key === "End") { e.preventDefault(); setActive(flat.length - 1); }
        if (e.key === "Enter") { e.preventDefault(); run(flat[active]); }
    };

    let i = -1;
    return (
        <dialog
            ref={dialog}
            aria-label="Command menu"
            onClose={() => onOpenChange(false)}
            onClick={(e) => { if (e.target === dialog.current) onOpenChange(false); }}
            className="mx-auto mt-[12vh] animate-in fade-in zoom-in-95 duration-150 w-[min(36rem,calc(100vw-1.5rem))] max-w-none overflow-hidden rounded-large bg-surface-container-lowest p-0 text-on-surface shadow-level-3 backdrop:bg-[rgb(var(--md-sys-color-scrim-rgb)/0.25)]dark:bg-surface-container-high"
        >
            <div className="flex items-center gap-3 px-4">
                <Icon icon={SearchIcon} className="text-on-surface-variant" />
                <input
                    ref={field}
                    value={q}
                    onChange={(e) => setQ(e.target.value)}
                    onKeyDown={onKey}
                    placeholder={placeholder}
                    role="combobox"
                    aria-expanded
                    aria-controls={`${uid}-list`}
                    aria-activedescendant={flat.length ? `${uid}-${active}` : undefined}
                    aria-autocomplete="list"
                    className="h-14 min-w-0 flex-1 bg-transparent text-body-lg text-on-surface outline-none placeholder:text-on-surface-variant"
                />
                <Kbd>Esc</Kbd>
            </div>
            <ul ref={list} id={`${uid}-list`} role="listbox" aria-label="Results" className="max-h-[min(24rem,60dvh)] overflow-y-auto border-t border-outline-variant p-2">
                {!flat.length ? <li className="px-3 py-8 text-center text-body-md text-on-surface-variant">{empty}</li> : null}
                {groups.map(([g, its]) => (
                    <li key={g} role="presentation">
                        {g ? <p className="px-3 pb-1 pt-3 text-label-md uppercase tracking-[0.12em] text-on-surface-variant">{g}</p> : null}
                        <ul role="group" aria-label={g || undefined}>
                            {its.map((it) => {
                                i += 1;
                                const n = i;
                                return (
                                    <li
                                        key={it.id}
                                        id={`${uid}-${n}`}
                                        data-i={n}
                                        role="option"
                                        aria-selected={n === active}
                                        onMouseMove={() => setActive(n)}
                                        onClick={() => run(it)}
                                        className={cn("flex min-h-12 cursor-pointer items-center gap-3 rounded-small px-3 text-body-md", n === active ? "bg-on-surface/[0.08]" : "")}
                                    >
                                        {it.icon ? <Icon icon={it.icon} className="text-on-surface-variant" /> : null}
                                        <span className="min-w-0 flex-1 truncate">{it.label}</span>
                                        {it.shortcut ? <span className="flex gap-1">{it.shortcut.map((k) => <Kbd key={k}>{k}</Kbd>)}</span> : null}
                                    </li>
                                );
                            })}
                        </ul>
                    </li>
                ))}
            </ul>
            <p className="flex gap-4 border-t border-outline-variant px-4 py-2 text-label-sm text-on-surface-variant">
                <span><Kbd>↑</Kbd> <Kbd>↓</Kbd> move</span>
                <span><Kbd>Enter</Kbd> open</span>
            </p>
        </dialog>
    );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { Skeleton } from "../primitives/Skeleton";
import { ArrowDown, ArrowUp, ArrowUpDown, ChevronLeft, ChevronRight } from "../symbols";
import { interactive } from "../state-layer";
import { Search } from "./Input";

/* ── Pagination ───────────────────────────────────────────────────────── */

/** The table's own words, for a site in another language. "{n}" is a number. */
export const TABLE_LABELS = { of: "of", picked: "{n} picked", clear: "Clear", pickAll: "Pick every row on this page", pickRow: "Pick this row", prev: "Previous page", next: "Next page", pages: "Pages" };

export type PaginationProps = {
    /** 1-based. */
    page: number;
    pages: number;
    onChange: (page: number) => void;
    /** "41–60 of 213", shown on the left. */
    summary?: ReactNode;
    labels?: Partial<typeof TABLE_LABELS>;
    className?: string;
};

/** 1 … 4 5 6 … 20: the first, the last, and two either side of here. */
function pageList(page: number, pages: number): (number | "…")[] {
    const want = new Set([1, pages, page - 1, page, page + 1].filter((p) => p >= 1 && p <= pages));
    const out: (number | "…")[] = [];
    [...want].sort((a, b) => a - b).forEach((p, i, a) => {
        if (i && p - a[i - 1] > 1) out.push("…");
        out.push(p);
    });
    return out;
}

export function Pagination({ page, pages, onChange, summary, labels, className }: PaginationProps) {
    const L = { ...TABLE_LABELS, ...labels };
    if (pages <= 1 && !summary) return null;
    const btn = cn("inline-flex h-10 min-w-10 items-center justify-center rounded-small px-2 text-label-lg tnum", interactive(), "disabled:pointer-events-none disabled:opacity-[0.38]");
    return (
        <nav aria-label={L.pages} className={cn("flex flex-wrap items-center justify-between gap-3", className)}>
            <p className="text-body-sm text-on-surface-variant tnum">{summary}</p>
            {pages > 1 ? (
                <ul className="flex items-center gap-1">
                    <li><button type="button" className={btn} aria-label={L.prev} disabled={page <= 1} onClick={() => onChange(page - 1)}><Icon icon={ChevronLeft} className="rtl:rotate-180" /></button></li>
                    {pageList(page, pages).map((p, i) => (
                        <li key={i} className="hidden medium:block">
                            {p === "…" ? <span className="px-2 text-on-surface-variant">…</span> : (
                                <button type="button" className={cn(btn, p === page && "bg-primary text-on-primary")} aria-current={p === page ? "page" : undefined} onClick={() => onChange(p)}>{p}</button>
                            )}
                        </li>
                    ))}
                    <li className="px-2 text-label-lg tnum text-on-surface medium:hidden">{page} / {pages}</li>
                    <li><button type="button" className={btn} aria-label={L.next} disabled={page >= pages} onClick={() => onChange(page + 1)}><Icon icon={ChevronRight} className="rtl:rotate-180" /></button></li>
                </ul>
            ) : null}
        </nav>
    );
}

/* ── Data table ───────────────────────────────────────────────────────── */

export type DataColumn<Row> = {
    key: string;
    header: string;
    cell: (row: Row) => ReactNode;
    /** Makes the header a sort button. Return what to sort by. */
    sort?: (row: Row) => string | number;
    numeric?: boolean;
    hideOnPhone?: boolean;
    width?: string;
};

export type Sort = { key: string; dir: "asc" | "desc" } | null;

export type DataTableProps<Row> = {
    label: string;
    columns: DataColumn<Row>[];
    rows: Row[];
    rowKey: (row: Row) => string;
    /** The words a row is found by. Leave out to hide the search box. */
    searchText?: (row: Row) => string;
    searchLabel?: string;
    pageSize?: number;
    /** Checkboxes on each row; `bulk` gets the picked rows. */
    selectable?: boolean;
    bulk?: (picked: Row[], clear: () => void) => ReactNode;
    /** Filters or a button, beside the search box. */
    toolbar?: ReactNode;
    onRowClick?: (row: Row) => void;
    empty?: ReactNode;
    loading?: boolean;
    /**
     * Server mode: the server searched, sorted and paged already. Pass the
     * page's rows in `rows`, the full count in `total`, and handle the three
     * callbacks. Without it, all of that happens here.
     */
    labels?: Partial<typeof TABLE_LABELS>;
    server?: {
        total: number;
        page: number;
        onPage: (page: number) => void;
        sort: Sort;
        onSort: (sort: Sort) => void;
        query: string;
        onQuery: (q: string) => void;
    };
    className?: string;
};

/**
 * A table you can work in: search, sort by any column, page through, tick
 * rows and act on them together. Still a real <table>; on a phone it scrolls
 * inside its own box and `hideOnPhone` columns drop out first.
 */
export function DataTable<Row>({ label, columns, rows, rowKey, searchText, searchLabel = "Search", pageSize = 20, selectable, bulk, toolbar, onRowClick, empty, loading, server, labels, className }: DataTableProps<Row>) {
    const L = { ...TABLE_LABELS, ...labels };
    const [q, setQ] = useState("");
    const [sort, setSort] = useState<Sort>(null);
    const [page, setPage] = useState(1);
    const [picked, setPicked] = useState<Set<string>>(new Set());

    const query = server?.query ?? q;
    const activeSort = server ? server.sort : sort;

    const view = useMemo(() => {
        if (server) return rows;
        let out = rows;
        if (q && searchText) {
            const needle = q.toLowerCase();
            out = out.filter((r) => searchText(r).toLowerCase().includes(needle));
        }
        const col = sort && columns.find((c) => c.key === sort.key);
        if (col?.sort) {
            const by = col.sort;
            out = [...out].sort((a, b) => {
                const x = by(a), y = by(b);
                const c = typeof x === "number" && typeof y === "number" ? x - y : String(x).localeCompare(String(y), undefined, { numeric: true });
                return sort!.dir === "asc" ? c : -c;
            });
        }
        return out;
    }, [rows, q, sort, columns, searchText, server]);

    const total = server?.total ?? view.length;
    const pages = Math.max(1, Math.ceil(total / pageSize));
    const current = Math.min(server?.page ?? page, pages);
    const shown = server ? view : view.slice((current - 1) * pageSize, current * pageSize);

    const goto = (p: number) => (server ? server.onPage(p) : setPage(p));
    const onQuery = (v: string) => { if (server) server.onQuery(v); else { setQ(v); setPage(1); } };
    const toggleSort = (key: string) => {
        const next: Sort = activeSort?.key !== key ? { key, dir: "asc" } : activeSort.dir === "asc" ? { key, dir: "desc" } : null;
        if (server) server.onSort(next); else setSort(next);
    };

    const ids = shown.map(rowKey);
    const allOn = ids.length > 0 && ids.every((id) => picked.has(id));
    const someOn = ids.some((id) => picked.has(id));
    const flip = (id: string) => setPicked((s) => { const n = new Set(s); if (n.has(id)) n.delete(id); else n.add(id); return n; });
    const flipAll = () => setPicked((s) => { const n = new Set(s); ids.forEach((id) => (allOn ? n.delete(id) : n.add(id))); return n; });
    const pickedRows = rows.filter((r) => picked.has(rowKey(r)));

    const from = total ? (current - 1) * pageSize + 1 : 0;
    const to = Math.min(current * pageSize, total);

    return (
        <div className={cn("flex min-w-0 flex-col gap-3", className)}>
            {searchText || server || toolbar ? (
                <div className="flex flex-wrap items-center gap-2">
                    {searchText || server ? <Search label={searchLabel} value={query} onChange={(e) => onQuery(e.target.value)} onClear={() => onQuery("")} className="min-w-[12rem] flex-1 medium:max-w-sm" /> : null}
                    {toolbar}
                </div>
            ) : null}

            {selectable && pickedRows.length ? (
                <div className="flex min-h-12 flex-wrap items-center gap-2 rounded-medium bg-inverse-surface px-4 py-2 text-inverse-on-surface">
                    <span className="text-label-lg tnum">{L.picked.replace("{n}", String(pickedRows.length))}</span>
                    <span className="kit-inverse ms-auto flex flex-wrap gap-2 bg-transparent">{bulk?.(pickedRows, () => setPicked(new Set()))}</span>
                    <button type="button" onClick={() => setPicked(new Set())} className="min-h-10 rounded-small px-3 text-label-lg underline underline-offset-4">{L.clear}</button>
                </div>
            ) : null}

            {!loading && !shown.length && empty ? (
                empty
            ) : (
                <div className="min-w-0 overflow-x-auto rounded-medium bg-surface-container">
                    <table className="w-full border-collapse text-body-sm">
                        <caption className="sr-only">{label}</caption>
                        <thead>
                            <tr>
                                {selectable ? (
                                    <th scope="col" className="w-12 bg-surface-container-high px-3">
                                        <input type="checkbox" aria-label={L.pickAll} checked={allOn} ref={(el) => { if (el) el.indeterminate = someOn && !allOn; }} onChange={flipAll} className="h-[18px] w-[18px] accent-[var(--md-sys-color-primary)]" />
                                    </th>
                                ) : null}
                                {columns.map((c) => {
                                    const on = activeSort?.key === c.key ? activeSort.dir : null;
                                    return (
                                        <th
                                            key={c.key}
                                            scope="col"
                                            aria-sort={on === "asc" ? "ascending" : on === "desc" ? "descending" : undefined}
                                            style={c.width ? { width: c.width } : undefined}
                                            className={cn("whitespace-nowrap bg-surface-container-high px-3 py-2.5 text-label-md text-on-surface-variant", c.numeric ? "text-right" : "text-left", c.hideOnPhone && "hidden medium:table-cell")}
                                        >
                                            {c.sort ? (
                                                <button type="button" onClick={() => toggleSort(c.key)} className={cn("-mx-2 inline-flex min-h-8 items-center gap-1 rounded-small px-2", c.numeric && "flex-row-reverse", interactive())}>
                                                    {c.header}
                                                    <Icon icon={on === "asc" ? ArrowUp : on === "desc" ? ArrowDown : ArrowUpDown} size="sm" className={on ? "text-on-surface" : "opacity-50"} />
                                                </button>
                                            ) : c.header}
                                        </th>
                                    );
                                })}
                            </tr>
                        </thead>
                        <tbody>
                            {loading
                                ? Array.from({ length: Math.min(pageSize, 5) }, (_, i) => (
                                    <tr key={i}>
                                        {selectable ? <td className="px-3 py-3.5" /> : null}
                                        {columns.map((c) => <td key={c.key} className={cn("px-3 py-3.5", c.hideOnPhone && "hidden medium:table-cell")}><Skeleton className="h-4 w-3/4" /></td>)}
                                    </tr>
                                ))
                                : shown.map((row) => {
                                    const id = rowKey(row);
                                    return (
                                        <tr
                                            key={id}
                                            onClick={onRowClick ? () => onRowClick(row) : undefined}
                                            className={cn(picked.has(id) && "bg-secondary-container", onRowClick && "cursor-pointer transition-colors duration-short2 ease-standard hover:bg-on-surface/[0.08]")}
                                        >
                                            {selectable ? (
                                                <td className="px-3" onClick={(e) => e.stopPropagation()}>
                                                    <input type="checkbox" aria-label={L.pickRow} checked={picked.has(id)} onChange={() => flip(id)} className="h-[18px] w-[18px] accent-[var(--md-sys-color-primary)]" />
                                                </td>
                                            ) : null}
                                            {columns.map((c) => (
                                                <td key={c.key} className={cn("px-3 py-3.5 text-on-surface", c.numeric ? "text-right tnum" : "text-left", c.hideOnPhone && "hidden medium:table-cell")}>{c.cell(row)}</td>
                                            ))}
                                        </tr>
                                    );
                                })}
                        </tbody>
                    </table>
                </div>
            )}

            <Pagination page={current} pages={pages} onChange={goto} summary={total ? `${from}–${to} ${L.of} ${total}` : undefined} labels={labels} />
        </div>
    );
}

"use client";

import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { CalendarClock, ChevronLeft, ChevronRight } from "../symbols";
import { Popover } from "./Popover";
import { interactive } from "../state-layer";

/**
 * Dates are plain "YYYY-MM-DD" strings everywhere here. A `Date` carries a
 * time zone, and "the 3rd" picked in London turned into "the 2nd" on a server
 * in New York - the bug every date picker ships once. A string can't drift.
 */
export type Day = string;
export type DayRange = { from: Day | null; to: Day | null };

const pad = (n: number) => String(n).padStart(2, "0");
export const toDay = (d: Date): Day => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const parse = (s: Day) => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
const addDays = (s: Day, n: number) => { const d = parse(s); d.setDate(d.getDate() + n); return toDay(d); };
const addMonths = (s: Day, n: number) => { const d = parse(s); const day = d.getDate(); d.setDate(1); d.setMonth(d.getMonth() + n); d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate())); return toDay(d); };
export const today = () => toDay(new Date());

/** "3 Oct 2026" in the visitor's own language. */
export function formatDay(s: Day | null | undefined, locale?: string): string {
    return s ? parse(s).toLocaleDateString(locale, { day: "numeric", month: "short", year: "numeric" }) : "";
}

/**
 * The language dates are written in. The server can't know the visitor's, so
 * the first render uses "en-US" on both sides (no hydration mismatch), then
 * switches to the browser's own. A `locale` prop skips that.
 */
function useDateLocale(locale?: string): string {
    const [browser, setBrowser] = useState<string | null>(null);
    useEffect(() => setBrowser(navigator.language), []);
    return locale ?? browser ?? "en-US";
}

/** Monday first, except where the visitor's locale says Sunday (US, Canada, Japan…). */
function firstWeekday(locale?: string): number {
    try {
        const info = (new Intl.Locale(locale ?? "en-GB") as Intl.Locale & { weekInfo?: { firstDay: number }; getWeekInfo?: () => { firstDay: number } });
        const f = info.getWeekInfo?.().firstDay ?? info.weekInfo?.firstDay;
        return f === 7 ? 0 : f ?? 1;
    } catch {
        return 1;
    }
}

export type CalendarProps = {
    /** One day, or the two ends of a range. */
    mode?: "single" | "range";
    value?: Day | null;
    range?: DayRange;
    onChange?: (day: Day) => void;
    onRangeChange?: (range: DayRange) => void;
    min?: Day;
    max?: Day;
    /** Days that can't be picked: booked, closed. */
    disabled?: (day: Day) => boolean;
    locale?: string;
    className?: string;
};

/**
 * A month you can pick from. A real grid for screen readers; arrows move a
 * day, up/down a week, Page Up/Down a month, Home/End the week, Enter picks.
 */
export function Calendar({ mode = "single", value, range, onChange, onRangeChange, min, max, disabled, locale: wanted, className }: CalendarProps) {
    const locale = useDateLocale(wanted);
    const start = (mode === "range" ? range?.from : value) ?? today();
    const [focus, setFocus] = useState<Day>(start);
    const [hover, setHover] = useState<Day | null>(null);
    const grid = useRef<HTMLTableElement>(null);
    const moved = useRef(false);

    useEffect(() => {
        if (moved.current) grid.current?.querySelector<HTMLButtonElement>(`[data-day="${focus}"]`)?.focus();
    }, [focus]);

    const first = firstWeekday(locale);
    const month = focus.slice(0, 7);
    const weeks = useMemo(() => {
        const d1 = parse(`${month}-01`);
        const lead = (d1.getDay() - first + 7) % 7;
        let cursor = addDays(`${month}-01`, -lead);
        const rows: Day[][] = [];
        for (let w = 0; w < 6; w++) {
            const row: Day[] = [];
            for (let i = 0; i < 7; i++) { row.push(cursor); cursor = addDays(cursor, 1); }
            rows.push(row);
            if (!cursor.startsWith(month)) break;
        }
        return rows;
    }, [month, first]);

    const names = useMemo(() => weeks[0].map((d) => parse(d).toLocaleDateString(locale, { weekday: "narrow" })), [weeks, locale]);
    const longNames = useMemo(() => weeks[0].map((d) => parse(d).toLocaleDateString(locale, { weekday: "long" })), [weeks, locale]);
    const title = parse(`${month}-01`).toLocaleDateString(locale, { month: "long", year: "numeric" });

    const off = (d: Day) => (min && d < min) || (max && d > max) || Boolean(disabled?.(d));
    const move = (d: Day) => { moved.current = true; setFocus(d); };

    const pick = (d: Day) => {
        if (off(d)) return;
        if (mode === "single") return onChange?.(d);
        const r = range ?? { from: null, to: null };
        if (!r.from || r.to || d < r.from) onRangeChange?.({ from: d, to: null });
        else onRangeChange?.({ from: r.from, to: d });
    };

    const onKey = (e: KeyboardEvent) => {
        const step: Record<string, () => Day> = {
            ArrowLeft: () => addDays(focus, -1), ArrowRight: () => addDays(focus, 1),
            ArrowUp: () => addDays(focus, -7), ArrowDown: () => addDays(focus, 7),
            PageUp: () => addMonths(focus, -1), PageDown: () => addMonths(focus, 1),
            Home: () => addDays(focus, -((parse(focus).getDay() - first + 7) % 7)),
            End: () => addDays(focus, 6 - ((parse(focus).getDay() - first + 7) % 7)),
        };
        if (step[e.key]) { e.preventDefault(); move(step[e.key]()); }
    };

    const end = mode === "range" ? (range?.to ?? (range?.from && hover && hover > range.from ? hover : null)) : null;
    const inRange = (d: Day) => mode === "range" && range?.from && end && d > range.from && d < end;
    const isPicked = (d: Day) => (mode === "single" ? d === value : d === range?.from || d === end);
    const now = today();

    return (
        <div className={cn("flex w-[18.5rem] max-w-full flex-col gap-2 p-1", className)}>
            <div className="flex items-center justify-between">
                <NavButton label="Previous month" icon={ChevronLeft} onClick={() => setFocus(addMonths(focus, -1))} />
                <p className="text-title-sm text-on-surface" aria-live="polite">{title}</p>
                <NavButton label="Next month" icon={ChevronRight} onClick={() => setFocus(addMonths(focus, 1))} />
            </div>
            <table ref={grid} role="grid" aria-label={title} className="w-full border-collapse" onKeyDown={onKey}>
                <thead>
                    <tr>
                        {names.map((n, i) => (
                            <th key={i} scope="col" abbr={longNames[i]} className="h-8 text-center text-label-sm font-normal text-on-surface-variant">{n}</th>
                        ))}
                    </tr>
                </thead>
                <tbody onMouseLeave={() => setHover(null)}>
                    {weeks.map((w) => (
                        <tr key={w[0]}>
                            {w.map((d) => {
                                const out = !d.startsWith(month);
                                const picked = isPicked(d);
                                return (
                                    <td key={d} className={cn("p-0 text-center", inRange(d) && "bg-secondary-container")}>
                                        <button
                                            type="button"
                                            data-day={d}
                                            tabIndex={d === focus ? 0 : -1}
                                            disabled={off(d)}
                                            aria-pressed={picked}
                                            aria-current={d === now ? "date" : undefined}
                                            aria-label={parse(d).toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" })}
                                            onClick={() => { setFocus(d); pick(d); }}
                                            onMouseEnter={() => setHover(d)}
                                            className={cn(
                                                "relative mx-auto flex h-10 w-10 items-center justify-center rounded-small text-body-md tnum outline-none",
                                                "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-primary",
                                                picked ? "bg-primary text-on-primary" : cn(interactive(), out ? "text-on-surface-variant/60" : "text-on-surface"),
                                                d === now && !picked && "font-bold underline underline-offset-4",
                                                "disabled:pointer-events-none disabled:text-on-surface/[0.3] disabled:line-through",
                                            )}
                                        >
                                            {parse(d).getDate()}
                                        </button>
                                    </td>
                                );
                            })}
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

function NavButton({ label, icon, onClick }: { label: string; icon: typeof ChevronLeft; onClick: () => void }) {
    return (
        <button type="button" aria-label={label} onClick={onClick} className={cn("inline-flex h-10 w-10 items-center justify-center rounded-small text-on-surface-variant", interactive())}>
            <Icon icon={icon} />
        </button>
    );
}

/** The field look shared by both pickers: a label on top, the value, a calendar icon. */
function FieldButton({ label, text, empty, ...rest }: { label: string; text: string; empty: string } & Record<string, unknown>) {
    return (
        <button
            type="button"
            {...rest}
            className={cn(
                "flex h-14 w-full min-w-0 items-center gap-3 rounded-small bg-surface-container px-4 text-left",
                "hover:bg-surface-container-high focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary",
            )}
        >
            <span className="min-w-0 flex-1">
                <span className="block text-label-md text-on-surface-variant">{label}</span>
                <span className={cn("block truncate text-body-lg", text ? "text-on-surface" : "text-on-surface-variant")}>{text || empty}</span>
            </span>
            <Icon icon={CalendarClock} className="text-on-surface-variant" />
        </button>
    );
}

export type DatePickerProps = Omit<CalendarProps, "mode" | "range" | "onRangeChange" | "className"> & {
    label: string;
    /** What the field says when nothing is picked. */
    empty?: string;
    /** A form field name: the value is sent as YYYY-MM-DD. */
    name?: string;
    className?: string;
};

/** One date, picked from a calendar that drops under the field. */
export function DatePicker({ label, empty = "Pick a date", name, value, onChange, locale: wanted, className, ...cal }: DatePickerProps) {
    const locale = useDateLocale(wanted);
    const [open, setOpen] = useState(false);
    return (
        <div className={cn("min-w-0", className)}>
            <Popover
                open={open}
                onOpenChange={setOpen}
                label={label}
                className="max-w-none"
                clientOnly
                trigger={(p) => <FieldButton {...p} label={label} text={formatDay(value, locale)} empty={empty} />}
            >
                <Calendar {...cal} locale={locale} value={value} onChange={(d) => { onChange?.(d); setOpen(false); }} />
            </Popover>
            {name ? <input type="hidden" name={name} value={value ?? ""} /> : null}
        </div>
    );
}

export type DateRangePickerProps = Omit<CalendarProps, "mode" | "value" | "onChange" | "className"> & {
    label: string;
    empty?: string;
    /** Quick picks above the calendar. Leave out for the usual four. */
    presets?: { label: string; range: () => DayRange }[];
    className?: string;
};

export const RANGE_PRESETS: { label: string; range: () => DayRange }[] = [
    { label: "Last 7 days", range: () => ({ from: addDays(today(), -6), to: today() }) },
    { label: "Last 30 days", range: () => ({ from: addDays(today(), -29), to: today() }) },
    { label: "This month", range: () => ({ from: `${today().slice(0, 7)}-01`, to: today() }) },
    { label: "Last 12 months", range: () => ({ from: addMonths(today(), -12), to: today() }) },
];

/** A from-to pair: a report's dates, a booking. Quick picks first, then any two days. */
export function DateRangePicker({ label, empty = "Pick dates", range, onRangeChange, presets = RANGE_PRESETS, locale: wanted, className, ...cal }: DateRangePickerProps) {
    const locale = useDateLocale(wanted);
    const [open, setOpen] = useState(false);
    const text = range?.from ? `${formatDay(range.from, locale)} – ${range.to ? formatDay(range.to, locale) : "…"}` : "";
    return (
        <div className={cn("min-w-0", className)}>
            <Popover open={open} onOpenChange={setOpen} label={label} className="max-w-none" clientOnly trigger={(p) => <FieldButton {...p} label={label} text={text} empty={empty} />}>
                <div className="flex flex-col gap-2 medium:flex-row">
                    <ul className="flex flex-wrap gap-1 medium:w-36 medium:flex-col">
                        {presets.map((p) => (
                            <li key={p.label}>
                                <button type="button" onClick={() => { onRangeChange?.(p.range()); setOpen(false); }} className={cn("flex min-h-10 w-full items-center rounded-small px-3 text-left text-label-lg text-on-surface", interactive())}>
                                    {p.label}
                                </button>
                            </li>
                        ))}
                    </ul>
                    <Calendar
                        {...cal}
                        mode="range"
                        locale={locale}
                        range={range}
                        onRangeChange={(r) => { onRangeChange?.(r); if (r.to) setOpen(false); }}
                    />
                </div>
            </Popover>
        </div>
    );
}

"use client";

import { useEffect, useRef, useState, type MouseEvent, type ReactNode } from "react";
import { AlertTriangle, Check, Download as DownloadGlyph, X } from "@/ui/symbols";
import { cn } from "../cn";
import { CHECKER_STYLE } from "../checker";
import { Icon } from "../primitives/Icon";
import { Progress } from "../primitives/Progress";
import { Button, IconButton } from "../primitives/Button";

/**
 * Every download on the site goes through here.
 *
 *   download({ name, preview, make })   the usual door: make the file, save it
 *   startDownload({ title })            a long job that reports its own steps (a collection ZIP)
 *   saveFile(blob, name)                a file already in hand
 *   <DownloadLink href download>        a plain link that downloads (works without JS too)
 *
 * A card drops in at the top right (full width at the top on a phone) with a
 * preview, a progress bar, then "Downloaded · 1.2 MB". It stays while it works,
 * leaves by itself once done, and keeps "Save again" until it goes.
 *
 * 🔴 Why not a plain <a download>: the page loading bar (nextjs-toploader)
 * starts on every link click and only stops when a page loads. A download
 * loads no page, so the bar crawled across the top and the save dialog
 * appeared with nothing else said. Files here are fetched first, then saved by
 * an anchor whose click never reaches the loader.
 *
 * Callers gate first (`guardDownload()`), then call these. `@/ui` knows
 * nothing about plans or the paywall.
 */

type Status = "working" | "done" | "failed" | "cancelled";

type Job = {
    id: number;
    title: string;
    preview?: string | null;
    count?: number;
    status: Status;
    /** 0–100, or undefined while the length is unknown. */
    value?: number;
    note?: string;
    file?: { url: string; name: string; size: number };
    retry?: () => void;
    cancel?: () => void;
};

export type DownloadJob = {
    /** Aborts with the card's Cancel. Pass it to every fetch the job makes. */
    signal: AbortSignal;
    /** `value` 0–100 (undefined = unknown length). `note` replaces the status line: "24 of 120". */
    progress: (value?: number, note?: string) => void;
    /** Saves the file now. A job may save several (a ZIP in parts). */
    save: (blob: Blob, name: string) => void;
    done: (note?: string) => void;
    fail: (message: string, retry?: () => void) => void;
    /** Stops it: aborts `signal` and the card says "Cancelled". The card's own X does this. */
    cancel: () => void;
    /** Takes the card away without a word (the caller opened a popup instead). */
    close: () => void;
};

/* A tiny store, like toast(): callable from any handler, no provider. */
let jobs: Job[] = [];
let nextId = 1;
const listeners = new Set<(jobs: Job[]) => void>();
const emit = () => listeners.forEach((l) => l(jobs));
const patch = (id: number, p: Partial<Job>) => {
    jobs = jobs.map((j) => (j.id === id ? { ...j, ...p } : j));
    emit();
};
function remove(id: number) {
    const j = jobs.find((x) => x.id === id);
    if (j?.file) setTimeout(() => URL.revokeObjectURL(j.file!.url), 1000);
    if (j?.preview?.startsWith("blob:")) URL.revokeObjectURL(j.preview);
    jobs = jobs.filter((x) => x.id !== id);
    emit();
}

/** The root layout is off limits (PERFORMANCE_RULES.md rule 2): the first download mounts its own host. */
let mounted = false;
function ensureMounted() {
    if (mounted || listeners.size > 0 || typeof document === "undefined") return;
    mounted = true;
    void import("react-dom/client").then(({ createRoot }) => {
        const host = document.createElement("div");
        host.setAttribute("data-download-host", "");
        document.body.appendChild(host);
        createRoot(host).render(<Downloads />);
    });
}

/** Hands a file to the browser's save flow. The click stops here, so the page loading bar never starts. */
function handOver(url: string, name: string) {
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    a.rel = "noopener";
    a.addEventListener("click", (e) => e.stopPropagation());
    document.body.appendChild(a);
    a.click();
    a.remove();
}

export function startDownload(o: { title: string; preview?: string | null; count?: number; note?: string }): DownloadJob {
    ensureMounted();
    const id = nextId++;
    const abort = new AbortController();
    /** Still on screen and still running: a cancelled job ignores late reports. */
    const alive = () => jobs.some((j) => j.id === id && j.status === "working");
    const cancel = () => {
        abort.abort();
        if (jobs.some((j) => j.id === id && j.status === "working")) patch(id, { status: "cancelled", cancel: undefined });
    };
    jobs = [{ id, title: o.title, preview: o.preview, count: o.count, note: o.note, status: "working" as Status, cancel }, ...jobs].slice(0, 4);
    emit();
    return {
        signal: abort.signal,
        cancel,
        progress: (value, note) => alive() && patch(id, { value, note }),
        save: (blob, name) => {
            const url = URL.createObjectURL(blob);
            handOver(url, name);
            const j = jobs.find((x) => x.id === id);
            if (!j) return void setTimeout(() => URL.revokeObjectURL(url), 5000);
            if (j.file) setTimeout(() => URL.revokeObjectURL(j.file!.url), 5000);
            // No preview given: a picture is its own preview.
            const preview = j.preview ?? (/^image\//.test(blob.type) ? URL.createObjectURL(blob) : null);
            patch(id, { file: { url, name, size: blob.size }, preview, title: j.count ? j.title : name });
        },
        done: (note) => alive() && patch(id, { status: "done", value: 100, note, cancel: undefined }),
        fail: (message, retry) => alive() && patch(id, { status: "failed", note: message, retry, cancel: undefined }),
        close: () => remove(id),
    };
}

/**
 * The usual door. `make` returns the file, or a URL to fetch it from (progress
 * comes from the download itself), or null to stop quietly. Resolves true once saved.
 */
export async function download(o: {
    name: string;
    title?: string;
    preview?: string | null;
    count?: number;
    /** The line shown once saved, instead of "Downloaded · 1.2 MB". */
    done?: string;
    make: (job: DownloadJob) => Promise<Blob | string | null> | Blob | string | null;
}): Promise<boolean> {
    const job = startDownload({ title: o.title ?? o.name, preview: o.preview, count: o.count });
    try {
        let out = await o.make(job);
        if (out === null) return job.close(), false;
        if (typeof out === "string") out = await fetchFile(out, job.progress, job.signal);
        if (job.signal.aborted) return false;
        job.save(out, o.name);
        job.done(o.done);
        return true;
    } catch (err) {
        if (!job.signal.aborted) job.fail(messageOf(err), () => void download(o));
        return false;
    }
}

/** A file already in hand: saved at once, with the same card. */
export function saveFile(blob: Blob, name: string, o: { title?: string; preview?: string | null } = {}) {
    const job = startDownload({ title: o.title ?? name, preview: o.preview });
    job.save(blob, name);
    job.done();
}

/** Fetches a file with real progress when the server says how big it is. */
export async function fetchFile(url: string, onProgress?: (value?: number, note?: string) => void, signal?: AbortSignal): Promise<Blob> {
    const res = await fetch(url, { signal, cache: "no-store" });
    if (!res.ok) {
        if (res.status === 402 || res.status === 401) throw new Error("Sign in to download this.");
        if (res.status === 404) throw new Error("This file is gone.");
        throw new Error("The file could not be made. Try again.");
    }
    const total = Number(res.headers.get("content-length")) || 0;
    if (!res.body || !total) return res.blob();
    const reader = res.body.getReader();
    const parts: Uint8Array[] = [];
    let got = 0;
    for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        parts.push(value);
        got += value.length;
        onProgress?.(Math.min(99, (got / total) * 100), `${mb(got)} of ${mb(total)}`);
    }
    return new Blob(parts as BlobPart[], { type: res.headers.get("content-type") || "" });
}

const messageOf = (err: unknown) => {
    const m = err instanceof Error ? err.message : "";
    return m && m.length < 120 && !/^(failed to fetch|load failed|networkerror)/i.test(m) ? m : "The download did not finish. Try again.";
};
const mb = (n: number) => (n < 1_048_576 ? `${Math.max(1, Math.round(n / 1024))} KB` : `${(n / 1_048_576).toFixed(1)} MB`);
const nameFromUrl = (href: string) => decodeURIComponent(href.split(/[?#]/)[0].split("/").pop() || "file");

/** Downloads a link through the card. Menu rows and <DownloadLink> share it. */
export function downloadHrefClick(e: MouseEvent, href: string, name?: string | boolean, preview?: string | null) {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    e.preventDefault();
    // The native event only: React handlers above (a menu closing) still run,
    // but the page loading bar, listening on document, never hears the click.
    e.nativeEvent.stopPropagation();
    const file = typeof name === "string" && name ? name : nameFromUrl(href);
    void download({ name: file, preview, make: () => href });
}

/**
 * A link that downloads. Without JS it is a plain <a download>; with it, the
 * file comes through the card. For server pages (the brand kit).
 */
export function DownloadLink({ href, download: name, preview, className, children }: { href: string; download?: string; preview?: string | null; className?: string; children: ReactNode }) {
    return (
        <a href={href} download={name ?? true} className={className} onClick={(e) => downloadHrefClick(e, href, name, preview)}>
            {children}
        </a>
    );
}

/* ── The cards ───────────────────────────────────────────────────────── */

/*
 * 🔴 The cards live in the browser's top layer (a manual popover), because a
 * download is often started from inside something that is already there - a
 * Sheet (<dialog showModal>) - or from a legacy full-screen viewer at
 * z-[9999]. A z-index cannot climb above either. Each new job re-shows the
 * popover, which moves it to the top of the top layer; Sheet.tsx does the same
 * when a Sheet opens over it. Browsers without popovers get the z-index.
 */
const canPopover = typeof HTMLElement !== "undefined" && "showPopover" in HTMLElement.prototype;

export function Downloads() {
    const [list, setList] = useState<Job[]>(jobs);
    const layer = useRef<HTMLDivElement>(null);
    useEffect(() => {
        listeners.add(setList);
        setList(jobs);
        return () => void listeners.delete(setList);
    }, []);
    const newest = list[0]?.id;
    useEffect(() => {
        const el = layer.current;
        if (!el || !canPopover) return;
        if (el.matches(":popover-open")) el.hidePopover();
        if (newest !== undefined) el.showPopover();
    }, [newest]);
    return (
        <div
            ref={layer}
            data-download-layer=""
            popover={canPopover ? "manual" : undefined}
            aria-live="polite"
            className={cn(
                "m3-download-layer pointer-events-none fixed z-snackbar flex flex-col gap-2",
                "inset-x-2 top-[calc(env(safe-area-inset-top,0px)+0.5rem)]",
                "w-auto medium:inset-x-auto medium:right-4 medium:top-20 medium:w-[22rem]",
            )}
        >
            {list.map((j) => <Card key={j.id} job={j} />)}
        </div>
    );
}

function Card({ job }: { job: Job }) {
    const [leaving, setLeaving] = useState(false);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const close = () => {
        setLeaving(true);
        setTimeout(() => remove(job.id), 200);
    };
    const start = () => {
        if (job.status !== "done" && job.status !== "cancelled") return;
        if (timer.current) clearTimeout(timer.current);
        timer.current = setTimeout(close, job.status === "done" ? 6000 : 2000);
    };
    const stop = () => { if (timer.current) clearTimeout(timer.current); };
    useEffect(() => {
        start();
        return stop;
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [job.status]);

    const size = job.file ? mb(job.file.size) : null;
    const line =
        job.status === "done" ? job.note ?? `Downloaded${size ? ` · ${size}` : ""}`
        : job.status === "failed" ? job.note
        : job.status === "cancelled" ? "Cancelled"
        : job.note ?? (typeof job.value === "number" && job.value > 0 ? `${Math.round(job.value)}%` : "Preparing your file…");

    return (
        <div
            role={job.status === "failed" ? "alert" : "status"}
            data-leaving={leaving || undefined}
            onPointerEnter={stop}
            onPointerLeave={start}
            className={cn(
                "m3-download pointer-events-auto overflow-hidden rounded-large",
                "bg-surface-container-lowest text-on-surface shadow-level-3 dark:bg-surface-container-high dark:shadow-none",
            )}
        >
            <div className="flex items-center gap-2 p-3 pr-2">
                <Thumb job={job} />
                <div className="min-w-0 flex-1">
                    <p className="truncate text-title-sm">{job.title}</p>
                    <p className={cn("mt-0.5 text-body-sm", job.status === "failed" ? "line-clamp-2 text-error" : "truncate text-on-surface-variant")}>{line}</p>
                </div>
                {job.status === "done" && job.file ? (
                    <Button variant="text" size="xs" onClick={() => handOver(job.file!.url, job.file!.name)}>Save again</Button>
                ) : job.status === "failed" && job.retry ? (
                    <Button variant="text" size="xs" onClick={() => { remove(job.id); job.retry!(); }}>Try again</Button>
                ) : null}
                <IconButton
                    icon={X}
                    size="sm"
                    label={job.status === "working" && job.cancel ? "Cancel download" : "Close"}
                    onClick={job.status === "working" && job.cancel ? job.cancel : close}
                    className="text-on-surface-variant"
                />
            </div>
            {job.status === "working" ? <Progress value={job.value} label={`Downloading ${job.title}`} className="rounded-none" /> : null}
        </div>
    );
}

function Thumb({ job }: { job: Job }) {
    const [broken, setBroken] = useState(false);
    const glyph = job.status === "failed" ? AlertTriangle : DownloadGlyph;
    return (
        <div className="relative h-14 w-14 shrink-0">
            <div className="flex h-full w-full items-center justify-center overflow-hidden rounded-medium" style={CHECKER_STYLE}>
                {job.preview && !broken ? (
                    // eslint-disable-next-line @next/next/no-img-element -- a blob: or any-host preview, shown once
                    <img src={job.preview} alt="" className="h-full w-full object-contain" onError={() => setBroken(true)} />
                ) : (
                    <Icon icon={glyph} className={job.status === "failed" ? "text-error" : "text-on-surface-variant"} />
                )}
            </div>
            {job.count && job.count > 1 ? (
                <span className="absolute -left-1.5 -top-1.5 rounded-full bg-secondary-container px-2 text-center text-label-sm leading-6 text-on-secondary-container">
                    {job.count > 999 ? "999+" : job.count}
                </span>
            ) : null}
            {job.status === "done" ? (
                <span className="m3-download-check absolute -bottom-1 -right-1 inline-flex h-6 w-6 items-center justify-center rounded-full bg-primary text-on-primary ring-2 ring-surface-container-lowest dark:ring-surface-container-high">
                    <Icon icon={Check} size="sm" />
                </span>
            ) : null}
        </div>
    );
}

"use client";

import { useId, useRef, useState, type ClipboardEvent, type KeyboardEvent, type ReactNode } from "react";
import { cn } from "../cn";
import { Icon, type IconGlyph } from "../primitives/Icon";
import { CountBadge } from "../primitives/Badge";
import { Bell, Check, ChevronDown, X } from "../symbols";
import { Popover } from "./Popover";
import { interactive } from "../state-layer";

/* ── Accordion ────────────────────────────────────────────────────────── */

export type AccordionItem = { id?: string; title: ReactNode; body: ReactNode };

/**
 * Questions that open in place: FAQs, "details". Built on <details>, so it
 * works before the page wakes up, finds-in-page opens the right one, and a
 * `name` makes them close each other (one open at a time).
 */
export function Accordion({ items, single, className }: { items: AccordionItem[]; single?: boolean; className?: string }) {
    const group = useId();
    return (
        <div className={cn("flex min-w-0 flex-col divide-y divide-outline-variant rounded-medium bg-surface-container", className)}>
            {items.map((it, i) => (
                <details key={it.id ?? i} id={it.id} name={single ? group : undefined} className="group">
                    <summary className="flex min-h-14 cursor-pointer list-none items-center justify-between gap-4 px-4 py-3 text-title-sm text-on-surface marker:hidden [&::-webkit-details-marker]:hidden">
                        {it.title}
                        <Icon icon={ChevronDown} className="shrink-0 text-on-surface-variant transition-transform duration-short4 group-open:rotate-180" />
                    </summary>
                    <div className="px-4 pb-4 text-body-md text-on-surface-variant">{it.body}</div>
                </details>
            ))}
        </div>
    );
}

/* ── Steps ────────────────────────────────────────────────────────────── */

/** Where someone is in a few steps: sign-up, onboarding, checkout. Done steps get a tick. */
export function Steps({ steps, current, className }: { steps: string[]; current: number; className?: string }) {
    return (
        <ol className={cn("flex min-w-0 flex-wrap items-center gap-x-3 gap-y-2", className)}>
            {steps.map((s, i) => {
                const done = i < current, now = i === current;
                return (
                    <li key={s} aria-current={now ? "step" : undefined} className="flex items-center gap-2">
                        <span className={cn("flex h-7 w-7 items-center justify-center text-label-lg tnum", done || now ? "bg-primary text-on-primary" : "bg-surface-container-highest text-on-surface-variant")}>
                            {done ? <Icon icon={Check} size="sm" /> : i + 1}
                        </span>
                        <span className={cn("text-label-lg", now ? "text-on-surface" : "text-on-surface-variant")}>{s}</span>
                        {i < steps.length - 1 ? <span aria-hidden className="hidden h-px w-8 bg-outline-variant medium:block" /> : null}
                    </li>
                );
            })}
        </ol>
    );
}

/* ── Code input ───────────────────────────────────────────────────────── */

export type CodeInputProps = {
    label: string;
    length?: number;
    value: string;
    onChange: (code: string) => void;
    /** Called once every box is filled. */
    onComplete?: (code: string) => void;
    error?: ReactNode;
    autoFocus?: boolean;
    className?: string;
};

/**
 * One box per digit: sign-in codes, two-step codes. Typing moves on,
 * Backspace moves back, pasting "123456" fills them all, and the phone's
 * "fill code from messages" works (autocomplete="one-time-code").
 */
export function CodeInput({ label, length = 6, value, onChange, onComplete, error, autoFocus, className }: CodeInputProps) {
    const boxes = useRef<(HTMLInputElement | null)[]>([]);
    const set = (next: string) => {
        const clean = next.replace(/\D/g, "").slice(0, length);
        onChange(clean);
        if (clean.length === length) onComplete?.(clean);
        boxes.current[Math.min(clean.length, length - 1)]?.focus();
    };
    const onKey = (i: number, e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "Backspace" && !value[i] && i > 0) { e.preventDefault(); onChange(value.slice(0, i - 1)); boxes.current[i - 1]?.focus(); }
        if (e.key === "ArrowLeft" && i > 0) boxes.current[i - 1]?.focus();
        if (e.key === "ArrowRight" && i < length - 1) boxes.current[i + 1]?.focus();
    };
    const onPaste = (e: ClipboardEvent) => { e.preventDefault(); set(e.clipboardData.getData("text")); };
    return (
        <fieldset className={cn("flex min-w-0 flex-col gap-2", className)}>
            <legend className="mb-2 text-label-md text-on-surface-variant">{label}</legend>
            <div className="flex gap-2" onPaste={onPaste}>
                {Array.from({ length }, (_, i) => (
                    <input
                        key={i}
                        ref={(el) => { boxes.current[i] = el; }}
                        aria-label={`Digit ${i + 1} of ${length}`}
                        inputMode="numeric"
                        autoComplete={i === 0 ? "one-time-code" : "off"}
                        autoFocus={autoFocus && i === 0}
                        maxLength={i === 0 ? length : 1}
                        value={value[i] ?? ""}
                        aria-invalid={error ? true : undefined}
                        onFocus={(e) => e.currentTarget.select()}
                        onChange={(e) => {
                            const d = e.target.value.replace(/\D/g, "");
                            if (d.length > 1) return set(value.slice(0, i) + d);
                            set((value.slice(0, i) + d + value.slice(i + 1)).slice(0, length));
                            if (d && i < length - 1) boxes.current[i + 1]?.focus();
                        }}
                        onKeyDown={(e) => onKey(i, e)}
                        className={cn(
                            "h-14 w-11 min-w-0 rounded-small bg-surface-container text-center text-title-lg tnum text-on-surface outline-none medium:w-12",
                            "focus:bg-surface-container-lowest focus:shadow-[inset_0_0_0_2px_var(--md-sys-color-primary)] dark:focus:bg-surface-container-low",
                            error && "shadow-[inset_0_0_0_2px_var(--md-sys-color-error)]",
                        )}
                    />
                ))}
            </div>
            {error ? <p role="alert" className="text-body-sm text-error">{error}</p> : null}
        </fieldset>
    );
}

/* ── Banner ───────────────────────────────────────────────────────────── */

/** A line across the top of the page: a launch, an outage, a sale. Dismissable. */
export function Banner({ children, action, onClose, tone = "ink", className }: { children: ReactNode; action?: ReactNode; onClose?: () => void; tone?: "ink" | "soft"; className?: string }) {
    const [gone, setGone] = useState(false);
    if (gone) return null;
    return (
        <div role="region" aria-label="Announcement" className={cn("flex min-h-12 items-center gap-3 px-4 py-2 text-body-md", tone === "ink" ? "kit-inverse" : "bg-secondary-container text-on-secondary-container", className)}>
            <p className="min-w-0 flex-1 text-center">{children}</p>
            {action}
            {onClose ? (
                <button type="button" aria-label="Close" onClick={() => { setGone(true); onClose(); }} className={cn("inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-small", interactive())}>
                    <Icon icon={X} />
                </button>
            ) : null}
        </div>
    );
}

/* ── Notifications ────────────────────────────────────────────────────── */

export type NotificationItem = { id: string; title: ReactNode; body?: ReactNode; at: string; read?: boolean; icon?: IconGlyph; href?: string };

/** The bell in an app bar: a count, and a list that opens under it. */
export function NotificationBell({ items, onReadAll, empty = "Nothing new." }: { items: NotificationItem[]; onReadAll?: () => void; empty?: string }) {
    const unread = items.filter((n) => !n.read).length;
    return (
        <Popover
            label="Notifications"
            placement="bottom-end"
            className="w-[min(22rem,calc(100vw-1rem))] max-w-none p-0"
            trigger={(p) => (
                <button {...p} type="button" aria-label={unread ? `Notifications, ${unread} new` : "Notifications"} className={cn("relative inline-flex h-10 w-10 items-center justify-center rounded-small text-on-surface", interactive())}>
                    <Icon icon={Bell} />
                    {unread ? <CountBadge count={unread} label={`${unread} new`} className="absolute -right-0.5 -top-0.5" /> : null}
                </button>
            )}
        >
            <div className="flex items-center justify-between px-4 pb-2 pt-3">
                <p className="text-title-sm text-on-surface">Notifications</p>
                {unread && onReadAll ? <button type="button" onClick={onReadAll} className={cn("rounded-small px-2 py-1 text-label-lg text-on-surface", interactive())}>Mark all read</button> : null}
            </div>
            {!items.length ? <p className="px-4 pb-6 pt-2 text-body-md text-on-surface-variant">{empty}</p> : (
                <ul className="max-h-96 overflow-y-auto pb-2">
                    {items.map((n) => {
                        const inner = (
                            <>
                                <span aria-hidden className={cn("mt-2 h-2 w-2 shrink-0", n.read ? "bg-transparent" : "bg-primary")} />
                                <span className="min-w-0 flex-1">
                                    <span className="block text-body-md text-on-surface">{n.title}</span>
                                    {n.body ? <span className="block text-body-sm text-on-surface-variant">{n.body}</span> : null}
                                    <span className="block text-label-sm text-on-surface-variant">{n.at}</span>
                                </span>
                            </>
                        );
                        const cls = cn("flex gap-3 px-4 py-3 text-left", n.href && interactive());
                        return <li key={n.id}>{n.href ? <a href={n.href} className={cls}>{inner}</a> : <div className={cls}>{inner}</div>}</li>;
                    })}
                </ul>
            )}
        </Popover>
    );
}

import type { ReactNode } from "react";
import type { IconGlyph } from "../primitives/Icon";
import { AlertTriangle, Info, XCircle, CheckCircle2 } from "../symbols";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { highlight, type CodeLang } from "../highlight";

const ALERT_TONE = {
    /* Every container with its own `on-` pair (M3): `on-surface` text on a
       dark `error-container` was a colour picked by eye, and its hint text
       fell under 4.5:1. Title and body inherit the pair. */
    info: { icon: Info, wrap: "bg-secondary-container text-on-secondary-container", mark: "text-on-secondary-container" },
    success: { icon: CheckCircle2, wrap: "bg-primary-container text-on-primary-container", mark: "text-on-primary-container" },
    warning: { icon: AlertTriangle, wrap: "bg-tertiary-container text-on-tertiary-container", mark: "text-on-tertiary-container" },
    danger: { icon: XCircle, wrap: "bg-error-container text-on-error-container", mark: "text-on-error-container" },
} as const;

export type AlertProps = {
    tone?: keyof typeof ALERT_TONE;
    title?: ReactNode;
    /** What happened and what to do next. Never an apology. */
    children: ReactNode;
    action?: ReactNode;
    className?: string;
};

/**
 * A message that stays on the page, tied to what it is about. Use a Toast for
 * something that just happened, and an Alert for a condition that persists:
 * an expired key, a missing wallet, a paused agent.
 */
export function Alert({ tone = "info", title, children, action, className }: AlertProps) {
    const t = ALERT_TONE[tone];
    return (
        <div role={tone === "danger" ? "alert" : "status"} className={cn("flex min-w-0 gap-3 rounded-medium p-3.5", t.wrap, className)}>
            <Icon icon={t.icon} size="md" className={cn("mt-px shrink-0", t.mark)} />
            {/* The action goes UNDER the words on a phone. Beside them it took
                the width and squeezed the message into one word per line. */}
            <div className="flex min-w-0 flex-1 flex-col gap-2 medium:flex-row medium:items-start medium:gap-3">
                <div className="min-w-0 flex-1">
                    {title ? <p className="text-label-lg">{title}</p> : null}
                    <div className={cn("text-body-sm", title && "mt-0.5 opacity-[0.86]")}>{children}</div>
                </div>
                {action ? <div className="-ml-3 shrink-0 medium:ml-0">{action}</div> : null}
            </div>
        </div>
    );
}

export type EmptyStateProps = {
    icon?: IconGlyph;
    /**
     * Generated art, passed in by the caller — never imported here. `src/ui`
     * must not depend on `src/components/marketing`, so the caller supplies
     * `<ArtMark id="empty-collections" />` and this stays a pure slot.
     *
     * When `art` is given the icon box is replaced, not joined: a picture and
     * a glyph competing in the same empty state is noise.
     */
    art?: ReactNode;
    title: ReactNode;
    /** Say what goes here and how to make the first one. */
    description?: ReactNode;
    action?: ReactNode;
    /** `inline` sits inside a card or a table; `page` owns the screen. */
    size?: "inline" | "page";
    className?: string;
};

/**
 * Nothing here yet - and what to do about it.
 *
 * An empty state without a next step is a dead end, so `action` is what makes
 * this component worth having. Never use it for an error: that is an Alert.
 */
export function EmptyState({ icon, art, title, description, action, size = "inline", className }: EmptyStateProps) {
    return (
        <div
            className={cn(
                "flex min-w-0 flex-col items-center justify-center gap-3 rounded-medium bg-surface-container-low text-center",
                size === "page" ? "px-6 py-14" : "px-4 py-9",
                className,
            )}
        >
            {art
                ? art
                : icon
                  ? (
                        // check-design-allow: a decorative plate, not a control
                        <span className="flex h-11 w-11 items-center justify-center rounded-medium bg-surface-container text-on-surface-variant">
                            <Icon icon={icon} size="lg" />
                        </span>
                    )
                  : null}
            <div className="space-y-1">
                <p className={cn(size === "page" ? "text-title-lg" : "text-label-lg", "text-on-surface")}>{title}</p>
                {description ? <p className="mx-auto max-w-narrow text-body-sm text-on-surface-variant">{description}</p> : null}
            </div>
            {action}
        </div>
    );
}

export type MetricProps = {
    label: ReactNode;
    /** The number itself. Always tabular, so a row of them lines up. */
    value: ReactNode;
    /** Change since the period before: "+18%", "+$3.10". */
    delta?: ReactNode;
    /** Up is not always good - a rising failure count is `bad`. */
    deltaTone?: "good" | "bad" | "flat";
    hint?: ReactNode;
    className?: string;
};

/** One number that matters, with the context to read it. */
export function Metric({ label, value, delta, deltaTone = "good", hint, className }: MetricProps) {
    return (
        <div className={cn("flex min-w-0 flex-col gap-0.5 rounded-medium bg-surface-container p-4", className)}>
            <span className="text-label-md text-on-surface-variant">{label}</span>
            <span className="text-headline-lg tnum text-on-surface">{value}</span>
            <span className="flex items-center gap-2">
                {delta ? (
                    <span className={cn("text-label-md tnum", deltaTone === "good" ? "text-primary" : deltaTone === "bad" ? "text-error" : "text-on-surface-variant")}>
                        {delta}
                    </span>
                ) : null}
                {hint ? <span className="text-label-md text-on-surface-variant">{hint}</span> : null}
            </span>
        </div>
    );
}

export type CodeBlockProps = {
    children: string;
    /** Shown above the code: a filename, a shell name, an endpoint. */
    title?: ReactNode;
    action?: ReactNode;
    /** Wrap long lines instead of scrolling sideways - for a command in a narrow card. */
    wrap?: boolean;
    /** Colours, like an editor. Guessed from the code when left out; "text" for none (a key, an id). */
    lang?: CodeLang;
    className?: string;
};

/** Commands and payloads, in the mono face and in colour, never wrapped mid-token. */
export function CodeBlock({ children, title, action, wrap, lang, className }: CodeBlockProps) {
    return (
        <div className={cn("min-w-0 overflow-hidden rounded-medium bg-surface-container", className)}>
            {title || action ? (
                <div className="flex items-center gap-2 bg-surface-container-high px-3 py-2">
                    <span className="min-w-0 flex-1 truncate text-label-md text-on-surface-variant">{title}</span>
                    {action}
                </div>
            ) : null}
            <pre className={cn("p-4 text-body-sm font-mono text-on-surface", wrap ? "whitespace-pre-wrap [overflow-wrap:anywhere]" : "overflow-x-auto")}>
                <code className="font-mono">{highlight(children, lang)}</code>
            </pre>
        </div>
    );
}

export type ErrorStateProps = {
    /** What went wrong, in the user's words — never a stack trace. */
    title: ReactNode;
    /** What to do next. An error with no next step is a dead end. */
    description?: ReactNode;
    action?: ReactNode;
    size?: "inline" | "page";
    className?: string;
};

/**
 * Something failed. Distinct from `EmptyState` (nothing here yet) and from
 * `Alert` (a condition that persists next to other content): this one owns the
 * space where the content should have been.
 */
export function ErrorState({ title, description, action, size = "inline", className }: ErrorStateProps) {
    return (
        <div
            role="alert"
            className={cn(
                /* A calm surface with the error in the icon plate and the words -
                   a whole block of dark-theme `error-container` read as an alarm
                   louder than the thing that went wrong (2026-09-28). */
                "flex min-w-0 flex-col items-center justify-center gap-3 rounded-medium bg-surface-container-low text-center",
                size === "page" ? "px-6 py-14" : "px-4 py-9",
                className,
            )}
        >
            {/* check-design-allow: a decorative plate, not a control */}
            <span className="flex h-11 w-11 items-center justify-center rounded-medium bg-error-container text-on-error-container">
                <Icon icon={AlertTriangle} size="lg" />
            </span>
            <div className="space-y-1">
                <p className={cn(size === "page" ? "text-title-lg" : "text-label-lg", "text-on-surface")}>{title}</p>
                {description ? <p className="mx-auto max-w-narrow text-body-sm text-on-surface-variant">{description}</p> : null}
            </div>
            {action}
        </div>
    );
}

"use client";

import { createContext, useContext, useId, type ReactNode } from "react";
import { cn } from "../cn";

/**
 * The wiring every form control needs, in one place.
 *
 * A control inside a `FormField` inherits its `id`, `aria-describedby`,
 * `aria-invalid`, `required` and `disabled` from here, so a page cannot forget
 * the wiring and ship an input a screen reader cannot name. `TextField` has
 * its own label built in (M3 floats it); `FormField` is for everything else —
 * a group of radios, a slider, a file picker.
 */

type FieldState = {
    id: string;
    describedBy?: string;
    invalid: boolean;
    disabled: boolean;
    required: boolean;
};

const FieldContext = createContext<FieldState | null>(null);

/** Controls call this to inherit the field's id, error state and description. */
export function useFieldState(): FieldState | null {
    return useContext(FieldContext);
}

export type FormFieldProps = {
    label: ReactNode;
    /** What to type, or why it is asked for. Shown under the control. */
    hint?: ReactNode;
    /** Replaces the hint when set. Say what went wrong AND what to do next. */
    error?: ReactNode;
    required?: boolean;
    disabled?: boolean;
    /** Hides the label visually. It still names the control for screen readers. */
    hideLabel?: boolean;
    /** Renders as a `<fieldset>`/`<legend>` — for a group of radios or checkboxes. */
    as?: "label" | "group";
    className?: string;
    children: ReactNode;
};

export function FormField({ label, hint, error, required = false, disabled = false, hideLabel, as = "label", className, children }: FormFieldProps) {
    const uid = useId();
    const id = `f-${uid}`;
    const msgId = error ? `${id}-err` : hint ? `${id}-hint` : undefined;

    const caption = error ? (
        <p id={msgId} role="alert" className="px-4 text-body-sm text-error">
            {error}
        </p>
    ) : hint ? (
        <p id={msgId} className="px-4 text-body-sm text-on-surface-variant">
            {hint}
        </p>
    ) : null;

    const labelText = (
        <>
            {label}
            {required ? (
                <span aria-hidden className="text-on-surface-variant">
                    {" *"}
                </span>
            ) : null}
        </>
    );

    return (
        <FieldContext.Provider value={{ id, describedBy: msgId, invalid: Boolean(error), disabled, required }}>
            {as === "group" ? (
                <fieldset
                    aria-describedby={msgId}
                    className={cn("flex min-w-0 flex-col gap-2 border-0 p-0", className)}
                >
                    <legend className={cn("mb-1 text-title-sm text-on-surface", hideLabel && "sr-only", disabled && "opacity-[0.38]")}>
                        {labelText}
                    </legend>
                    {children}
                    {caption}
                </fieldset>
            ) : (
                <div className={cn("flex min-w-0 flex-col gap-1", className)}>
                    <label htmlFor={id} className={cn("text-title-sm text-on-surface", hideLabel && "sr-only", disabled && "opacity-[0.38]")}>
                        {labelText}
                    </label>
                    {children}
                    {caption}
                </div>
            )}
        </FieldContext.Provider>
    );
}

/**
 * Supporting text under a text field — M3 puts it at `body-sm`, 16dp in from
 * the edge, and it becomes the error message rather than sitting beside one.
 */
export function SupportingText({ id, error, children }: { id?: string; error?: boolean; children: ReactNode }) {
    return (
        <p id={id} role={error ? "alert" : undefined} className={cn("px-4 pt-1 text-body-sm", error ? "text-error" : "text-on-surface-variant")}>
            {children}
        </p>
    );
}

"use client";

import { useEffect, useId, useRef, useState, type DragEvent } from "react";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { Progress } from "../primitives/Progress";
import { AlertCircle, CheckCircle2, FileText, Upload, X } from "../symbols";
import { interactive } from "../state-layer";

export type UploadItem = {
    id: string;
    file: File;
    /** 0-1 while sending; null before it starts. */
    progress: number | null;
    state: "waiting" | "sending" | "done" | "failed";
    error?: string;
    /** A picture's preview, made in the browser (revoked on remove). */
    preview?: string;
};

export type FileUploadProps = {
    label: string;
    /** What the box says under the label: "PNG or JPG, up to 10 MB". */
    hint?: string;
    /** The browser's own filter, e.g. "image/*,.pdf". Checked again on drop. */
    accept?: string;
    multiple?: boolean;
    /** Bytes. Bigger files are refused with a reason, never sent. */
    maxSize?: number;
    maxFiles?: number;
    /**
     * Send one file. Call `progress(0..1)` as it goes; throw to fail it with
     * the error's message. Leave it out to only collect files (a form posts them).
     */
    upload?: (file: File, progress: (p: number) => void) => Promise<void>;
    /** Every change to the list: added, sent, removed. */
    onChange?: (items: UploadItem[]) => void;
    /** Paste a picture anywhere on the page to add it. */
    paste?: boolean;
    className?: string;
};

const mb = (n: number) => (n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)} MB` : `${Math.max(1, Math.round(n / 1000))} KB`);

/** Does `file` match an accept string like "image/*,.pdf"? */
function accepts(file: File, accept?: string): boolean {
    if (!accept) return true;
    return accept.split(",").map((s) => s.trim().toLowerCase()).some((a) =>
        a.startsWith(".") ? file.name.toLowerCase().endsWith(a) : a.endsWith("/*") ? file.type.startsWith(a.slice(0, -1)) : file.type === a,
    );
}

/**
 * Drop files here, or click to choose, or paste. Each file gets a row with its
 * own progress and its own reason when it is refused ("too big", "not a
 * picture"), so one bad file never sinks the rest.
 *
 * The real <input type="file"> stays in the page: it is what a keyboard and a
 * screen reader use, and it opens the phone's camera and photo library.
 */
export function FileUpload({ label, hint, accept, multiple = true, maxSize, maxFiles = 20, upload, onChange, paste, className }: FileUploadProps) {
    const id = useId();
    const input = useRef<HTMLInputElement>(null);
    const [items, setItems] = useState<UploadItem[]>([]);
    const [over, setOver] = useState(false);
    const latest = useRef(items);
    latest.current = items;

    const commit = (next: UploadItem[]) => { latest.current = next; setItems(next); onChange?.(next); };
    const patch = (itemId: string, p: Partial<UploadItem>) => commit(latest.current.map((i) => (i.id === itemId ? { ...i, ...p } : i)));

    const add = (files: File[]) => {
        const room = Math.max(0, (multiple ? maxFiles : 1) - (multiple ? latest.current.length : 0));
        const fresh: UploadItem[] = files.slice(0, room).map((file) => {
            const why = !accepts(file, accept) ? "This kind of file isn't allowed here." : maxSize && file.size > maxSize ? `Too big: ${mb(file.size)}. The limit is ${mb(maxSize)}.` : undefined;
            return {
                id: `${file.name}-${file.size}-${Math.random().toString(36).slice(2, 8)}`,
                file,
                progress: null,
                state: why ? "failed" : "waiting",
                error: why,
                preview: file.type.startsWith("image/") ? URL.createObjectURL(file) : undefined,
            };
        });
        commit(multiple ? [...latest.current, ...fresh] : fresh);
        if (upload) for (const it of fresh) if (it.state === "waiting") send(it);
    };

    const send = async (it: UploadItem) => {
        patch(it.id, { state: "sending", progress: 0, error: undefined });
        try {
            await upload!(it.file, (p) => patch(it.id, { progress: Math.min(1, Math.max(0, p)) }));
            patch(it.id, { state: "done", progress: 1 });
        } catch (e) {
            patch(it.id, { state: "failed", error: (e as Error).message || "Upload failed. Try again." });
        }
    };

    const remove = (itemId: string) => {
        const it = latest.current.find((i) => i.id === itemId);
        if (it?.preview) URL.revokeObjectURL(it.preview);
        commit(latest.current.filter((i) => i.id !== itemId));
    };

    useEffect(() => {
        if (!paste) return;
        const onPaste = (e: ClipboardEvent) => {
            const files = [...(e.clipboardData?.files ?? [])];
            if (files.length) { e.preventDefault(); add(files); }
        };
        window.addEventListener("paste", onPaste);
        return () => window.removeEventListener("paste", onPaste);
    });

    const onDrop = (e: DragEvent) => {
        e.preventDefault();
        setOver(false);
        add([...e.dataTransfer.files]);
    };

    return (
        <div className={cn("flex min-w-0 flex-col gap-3", className)}>
            <label
                htmlFor={id}
                onDragOver={(e) => { e.preventDefault(); setOver(true); }}
                onDragLeave={() => setOver(false)}
                onDrop={onDrop}
                className={cn(
                    "flex min-h-40 cursor-pointer flex-col items-center justify-center gap-2 rounded-medium bg-surface-container-low px-6 py-8 text-center",
                    /* Dashed on purpose: the one place a line says "drop here". */
                    "border-2 border-dashed border-outline-variant",
                    "transition-colors duration-short4 ease-standard hover:bg-surface-container focus-within:outline focus-within:outline-2 focus-within:outline-primary",
                    over && "bg-secondary-container text-on-secondary-container",
                )}
            >
                <span className="flex h-12 w-12 items-center justify-center bg-inverse-surface text-inverse-on-surface">
                    <Icon icon={Upload} />
                </span>
                <span className="text-title-sm text-on-surface">{label}</span>
                <span className="text-body-sm text-on-surface-variant">
                    <span className="underline underline-offset-4">Choose {multiple ? "files" : "a file"}</span> or drop {multiple ? "them" : "it"} here{paste ? ". You can paste too." : "."}
                </span>
                {hint ? <span className="text-label-md text-on-surface-variant">{hint}</span> : null}
                <input
                    ref={input}
                    id={id}
                    type="file"
                    accept={accept}
                    multiple={multiple}
                    className="sr-only"
                    onChange={(e) => { add([...(e.currentTarget.files ?? [])]); e.currentTarget.value = ""; }}
                />
            </label>

            {items.length ? (
                <ul className="flex flex-col gap-2" aria-label="Files">
                    {items.map((it) => (
                        <li key={it.id} className="flex min-w-0 items-center gap-3 rounded-medium bg-surface-container p-3">
                            {it.preview ? (
                                // eslint-disable-next-line @next/next/no-img-element -- a local blob preview
                                <img src={it.preview} alt="" className="h-10 w-10 shrink-0 object-cover" />
                            ) : (
                                <span className="flex h-10 w-10 shrink-0 items-center justify-center bg-surface-container-highest text-on-surface-variant"><Icon icon={FileText} /></span>
                            )}
                            <span className="flex min-w-0 flex-1 flex-col gap-1">
                                <span className="flex min-w-0 items-center gap-2">
                                    <span className="truncate text-body-md text-on-surface">{it.file.name}</span>
                                    <span className="shrink-0 text-label-md text-on-surface-variant tnum">{mb(it.file.size)}</span>
                                </span>
                                {it.state === "sending" ? <Progress value={(it.progress ?? 0) * 100} label={`Sending ${it.file.name}`} /> : null}
                                {it.state === "failed" ? <span className="text-body-sm text-error">{it.error}</span> : null}
                            </span>
                            {it.state === "done" ? <Icon icon={CheckCircle2} label="Sent" className="text-on-surface" /> : null}
                            {it.state === "failed" && upload && !it.error?.startsWith("Too big") && !it.error?.startsWith("This kind") ? (
                                <button type="button" onClick={() => send(it)} className={cn("rounded-small px-2 py-1 text-label-lg text-on-surface", interactive())}>Retry</button>
                            ) : it.state === "failed" ? <Icon icon={AlertCircle} className="text-error" /> : null}
                            <button type="button" aria-label={`Remove ${it.file.name}`} onClick={() => remove(it.id)} className={cn("inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-small text-on-surface-variant", interactive())}>
                                <Icon icon={X} />
                            </button>
                        </li>
                    ))}
                </ul>
            ) : null}
        </div>
    );
}

/** Send a file with real progress (fetch can't report upload progress; XHR can). */
export function sendFile(url: string, file: File, progress: (p: number) => void, field = "file"): Promise<void> {
    return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open("POST", url);
        xhr.upload.onprogress = (e) => e.lengthComputable && progress(e.loaded / e.total);
        xhr.onload = () => {
            if (xhr.status < 300) return resolve();
            let msg = "Upload failed. Try again.";
            try { msg = JSON.parse(xhr.responseText).error || msg; } catch { /* not JSON */ }
            reject(new Error(msg));
        };
        xhr.onerror = () => reject(new Error("No connection. Check your internet and try again."));
        const body = new FormData();
        body.append(field, file);
        xhr.send(body);
    });
}

"use client";

import { useMemo, useState } from "react";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import * as all from "../primitives/symbols.generated";
import type { Glyph } from "../primitives/symbols.generated";
import { Popover } from "./Popover";
import { Search } from "./Input";
import { interactive } from "../state-layer";

/**
 * Every icon in the set, by its export name ("Calendar", "Rocket").
 * ⚠️ Importing this pulls in the whole set (~60 KB gzipped). Fine on a
 * settings page or the design-system page; never on the home page.
 */
let cache: Record<string, Glyph> | null = null;
/* A function, not a module-level constant: a constant built at import time
   would put all 339 icons in every page that imports anything from @/ui. */
export function allIcons(): Record<string, Glyph> {
    return (cache ??= Object.fromEntries(
        Object.entries(all).filter((e): e is [string, Glyph] => typeof e[1] === "object" && e[1] !== null && "d" in e[1]),
    ));
}

export type IconGridProps = {
    value?: string | null;
    onChange: (name: string) => void;
    /** Limit the choice; leave out for every icon. */
    icons?: Record<string, Glyph>;
    className?: string;
};

/** Search box + grid of icons. Finds by the export name and the Material name ("bar_chart"). */
export function IconGrid({ value, onChange, icons, className }: IconGridProps) {
    const [q, setQ] = useState("");
    const list = useMemo(() => {
        const needle = q.toLowerCase().replace(/[\s_-]/g, "");
        return Object.entries(icons ?? allIcons()).filter(([name, g]) => !needle || name.toLowerCase().includes(needle) || g.n.replace(/_/g, "").includes(needle));
    }, [icons, q]);
    return (
        <div className={cn("flex min-w-0 flex-col gap-3", className)}>
            <Search label="Search icons" value={q} onChange={(e) => setQ(e.target.value)} onClear={() => setQ("")} />
            <p className="text-label-md text-on-surface-variant tnum" aria-live="polite">{list.length} icons</p>
            <div role="listbox" aria-label="Icons" className="grid max-h-80 grid-cols-[repeat(auto-fill,minmax(3rem,1fr))] gap-1 overflow-y-auto">
                {list.map(([name, g]) => (
                    <button
                        key={name}
                        type="button"
                        role="option"
                        aria-selected={value === name}
                        title={name}
                        aria-label={name}
                        onClick={() => onChange(name)}
                        className={cn("flex h-12 items-center justify-center rounded-small", value === name ? "bg-primary text-on-primary" : cn("text-on-surface", interactive()))}
                    >
                        <Icon icon={g} />
                    </button>
                ))}
            </div>
        </div>
    );
}

/** A field that shows the picked icon and opens the grid. Stores the icon's name. */
export function IconPicker({ label, value, onChange, icons, className }: IconGridProps & { label: string }) {
    const [open, setOpen] = useState(false);
    const g = value ? (icons ?? allIcons())[value] : null;
    return (
        <Popover
            open={open}
            onOpenChange={setOpen}
            label={label}
            className="w-[min(22rem,calc(100vw-1rem))] max-w-none p-3"
            trigger={(p) => (
                <button {...p} type="button" className={cn("flex h-14 min-w-0 items-center gap-3 rounded-small bg-surface-container px-4 text-left hover:bg-surface-container-high focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary", className)}>
                    <span className="flex h-8 w-8 items-center justify-center bg-inverse-surface text-inverse-on-surface">{g ? <Icon icon={g} size="sm" /> : null}</span>
                    <span className="min-w-0">
                        <span className="block text-label-md text-on-surface-variant">{label}</span>
                        <span className="block truncate text-body-lg text-on-surface">{value ?? "None"}</span>
                    </span>
                </button>
            )}
        >
            <IconGrid value={value} icons={icons} onChange={(n) => { onChange(n); setOpen(false); }} />
        </Popover>
    );
}

"use client";

import { Children, forwardRef, isValidElement, useEffect, useId, useRef, useState, type ChangeEvent, type ComponentPropsWithoutRef, type ReactElement, type ReactNode } from "react";
import { ChevronDown, Search as SearchIcon, X } from "@/ui/symbols";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { SupportingText, useFieldState } from "./Field";
import { ColorPopover } from "./ColorPicker";
import { Menu, MenuItem } from "./Menu";
import { focusRing, interactive } from "../state-layer";

/**
 * M3 text fields — https://m3.material.io/components/text-fields
 *
 * Two variants, and the choice is about the surface the field sits on, not
 * taste:
 *
 *   filled    the default. A `surface-container-highest` fill. Reads as a
 *             field on a plain page without adding a box.
 *   outlined  the quieter one, `surface-container-high` — for a field on a
 *             card, where the loudest fill would shout.
 *
 * 🔴 Neither draws a line (law 11). M3's bottom active indicator and 1dp
 * outline are both gone; the fill is the field and the focus ring is focus.
 *
 * Shape (recorded per law §2.3): `small` all round on both — the top-corners-
 * only shape existed to give the bottom indicator a square foot, and there is
 * no indicator now.
 *
 * The label floats. It is driven by `:placeholder-shown`, not by React state,
 * so a field that is filled by the browser's autofill or by a password manager
 * floats its label too — a `useState` version does not, and that is the bug
 * every hand-rolled floating label ships with.
 */

/** The `peer` selectors that float the label. One string, used by both variants. */
const FLOAT =
    "pointer-events-none absolute left-4 z-[1] origin-left text-on-surface-variant " +
    "transition-[transform,color] duration-short4 ease-standard " +
    /* resting: centred in the field, at body-lg */
    "top-1/2 -translate-y-1/2 text-body-lg " +
    /* floated: small, at the top. Both when focused and when it has a value. */
    "peer-focus:top-2 peer-focus:translate-y-0 peer-focus:text-body-sm peer-focus:text-primary " +
    "peer-[:not(:placeholder-shown)]:top-2 peer-[:not(:placeholder-shown)]:translate-y-0 peer-[:not(:placeholder-shown)]:text-body-sm " +
    "peer-disabled:opacity-[0.38] " +
    "peer-aria-[invalid=true]:text-error";

/**
 * Filled (2026-10-09): a soft grey box with an 8px corner, no underline. On
 * focus it turns white, takes a 1px blue edge and a faint blue halo - the
 * focus every pro tool uses. Invalid = the same in `error`.
 */
const FILLED =
    "peer w-full min-w-0 rounded-small bg-surface-container text-body-lg text-on-surface caret-primary " +
    "shadow-[inset_0_0_0_1px_transparent] " +
    "transition-[box-shadow,background-color] duration-short4 ease-standard " +
    "[@media(hover:hover)]:hover:bg-surface-container-high " +
    "outline-none focus:bg-surface-container-lowest focus:hover:bg-surface-container-lowest dark:focus:bg-surface-container-low dark:focus:hover:bg-surface-container-low focus:shadow-[inset_0_0_0_1px_var(--md-sys-color-primary),0_0_0_3px_rgb(var(--md-sys-color-primary-rgb)/0.18)] " +
    "aria-[invalid=true]:shadow-[inset_0_0_0_1px_var(--md-sys-color-error),0_0_0_3px_rgb(var(--md-sys-color-error-rgb)/0.14)] " +
    "disabled:bg-on-surface/[0.04] disabled:text-on-surface/[0.38] disabled:cursor-not-allowed";

/**
 * Outlined: the same box with a hairline edge instead of a fill. For a field
 * on a card or a sheet, where a second fill would stack on the first.
 */
const OUTLINED =
    "peer w-full min-w-0 rounded-small bg-surface-container-lowest text-body-lg text-on-surface caret-primary dark:bg-surface-container-low " +
    "shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.16)] " +
    "transition-[box-shadow] duration-short4 ease-standard " +
    "[@media(hover:hover)]:hover:shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.32)] " +
    "outline-none focus:shadow-[inset_0_0_0_1px_var(--md-sys-color-primary),0_0_0_3px_rgb(var(--md-sys-color-primary-rgb)/0.18)] focus:hover:shadow-[inset_0_0_0_1px_var(--md-sys-color-primary),0_0_0_3px_rgb(var(--md-sys-color-primary-rgb)/0.18)] " +
    "aria-[invalid=true]:shadow-[inset_0_0_0_1px_var(--md-sys-color-error),0_0_0_3px_rgb(var(--md-sys-color-error-rgb)/0.14)] " +
    "disabled:text-on-surface/[0.38] disabled:shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.08)] disabled:cursor-not-allowed";

/**
 * The two M3 field boxes as classes, for a bare `<input>` that has no label
 * to float (the legacy `@/components/ui/input` wrapper, a search box inside
 * a toolbar). Anything with a label uses `TextField`.
 */
export const fieldStyles = { filled: FILLED, outlined: OUTLINED } as const;

export type TextFieldVariant = "filled" | "outlined";

export type TextFieldProps = Omit<ComponentPropsWithoutRef<"input">, "size" | "placeholder"> & {
    /** The floating label. Required — M3 fields are never unlabelled. */
    label: string;
    variant?: TextFieldVariant;
    /** Shown under the field. Becomes the error message when `error` is set. */
    hint?: ReactNode;
    /** Say what went wrong AND what to do next. */
    error?: ReactNode;
    /** Leading icon inside the field. */
    icon?: IconGlyph;
    /** Trailing icon or small control (a clear button, a unit, a reveal toggle). */
    trailing?: ReactNode;
    /** A fixed prefix or suffix, e.g. "$" or "/month". Never a placeholder. */
    prefix?: string;
    suffix?: string;
    /** Shows "12 / 80" under the field and sets `maxLength`. */
    counter?: number;
    /** 48dp instead of 56dp — for toolbars and dense tables, not for forms. */
    dense?: boolean;
    className?: string;
};

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(function TextField(
    { label, variant = "filled", hint, error, icon, trailing, prefix, suffix, counter, dense, className, value, defaultValue, onChange, ...rest },
    ref,
) {
    const field = useFieldState();
    const uid = useId();
    const id = rest.id ?? field?.id ?? `tf-${uid}`;
    const msgId = error || hint || counter ? `${id}-msg` : undefined;
    const invalid = rest["aria-invalid"] ?? (error ? true : field?.invalid) ?? undefined;

    /* The counter is the only thing here that needs to know the length, and an
       uncontrolled field has to be measured from the DOM to show it. */
    const [len, setLen] = useState(String(value ?? defaultValue ?? "").length);

    return (
        <div className={cn("flex min-w-0 flex-col", className)}>
            <div className="relative flex min-w-0 items-center">
                {icon ? (
                    <Icon icon={icon} size="md" className="pointer-events-none absolute left-3 z-[1] text-on-surface-variant" />
                ) : null}
                <input
                    ref={ref}
                    /* A single space, never a real placeholder: it is what makes
                       `:placeholder-shown` mean "empty" and float the label. */
                    placeholder=" "
                    id={id}
                    value={value}
                    defaultValue={defaultValue}
                    maxLength={counter ?? rest.maxLength}
                    aria-describedby={rest["aria-describedby"] ?? msgId ?? field?.describedBy}
                    aria-invalid={invalid}
                    required={rest.required ?? field?.required}
                    disabled={rest.disabled ?? field?.disabled}
                    onChange={e => {
                        if (counter) setLen(e.currentTarget.value.length);
                        onChange?.(e);
                    }}
                    className={cn(
                        variant === "filled" ? FILLED : OUTLINED,
                        dense ? "h-12" : "h-14",
                        /* Room for the floated label above the text. */
                        variant === "filled" ? "px-4 pb-2 pt-6" : "px-4 pt-2",
                        icon && "pl-12",
                        (trailing || suffix) && "pr-12",
                        prefix && "pl-8",
                    )}
                    {...rest}
                />
                <label
                    htmlFor={id}
                    className={cn(
                        FLOAT,
                        icon && "left-12",
                    )}
                >
                    {label}
                </label>
                {prefix ? (
                    <span aria-hidden className="pointer-events-none absolute left-4 z-[1] text-body-lg text-on-surface-variant opacity-0 peer-focus:opacity-100 peer-[:not(:placeholder-shown)]:opacity-100">
                        {prefix}
                    </span>
                ) : null}
                {trailing ? <span className="absolute right-2 z-[1] flex items-center">{trailing}</span> : null}
                {suffix && !trailing ? (
                    <span aria-hidden className="pointer-events-none absolute right-4 z-[1] text-body-lg text-on-surface-variant">
                        {suffix}
                    </span>
                ) : null}
            </div>

            {error || hint || counter ? (
                <div className="flex items-start justify-between gap-4">
                    {error ? (
                        <SupportingText id={msgId} error>
                            {error}
                        </SupportingText>
                    ) : hint ? (
                        <SupportingText id={msgId}>{hint}</SupportingText>
                    ) : (
                        <span />
                    )}
                    {counter ? (
                        <span className="shrink-0 px-4 pt-1 text-body-sm text-on-surface-variant tnum">
                            {len} / {counter}
                        </span>
                    ) : null}
                </div>
            ) : null}
        </div>
    );
});

/* ── Textarea ─────────────────────────────────────────────────────────── */

export type TextareaProps = Omit<ComponentPropsWithoutRef<"textarea">, "placeholder"> & {
    label: string;
    variant?: TextFieldVariant;
    hint?: ReactNode;
    error?: ReactNode;
    /** Grows with the text up to `maxHeight` px, then scrolls. */
    autoResize?: boolean;
    maxHeight?: number;
    className?: string;
};

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
    { label, variant = "outlined", hint, error, autoResize, maxHeight = 240, className, onInput, rows = 3, ...rest },
    ref,
) {
    const field = useFieldState();
    const uid = useId();
    const id = rest.id ?? field?.id ?? `ta-${uid}`;
    const msgId = error || hint ? `${id}-msg` : undefined;
    const inner = useRef<HTMLTextAreaElement | null>(null);

    const fit = (el: HTMLTextAreaElement | null) => {
        if (!el || !autoResize) return;
        el.style.height = "auto";
        el.style.height = `${Math.min(el.scrollHeight, maxHeight)}px`;
    };
    /* Fit once for a value that arrived with the page, not just on typing. */
    useEffect(() => fit(inner.current), [autoResize, maxHeight, rest.value, rest.defaultValue]);

    return (
        <div className={cn("flex min-w-0 flex-col", className)}>
            <div className="relative flex min-w-0">
                <textarea
                    ref={node => {
                        inner.current = node;
                        if (typeof ref === "function") ref(node);
                        else if (ref) ref.current = node;
                    }}
                    placeholder=" "
                    rows={rows}
                    id={id}
                    aria-describedby={rest["aria-describedby"] ?? msgId ?? field?.describedBy}
                    aria-invalid={rest["aria-invalid"] ?? (error ? true : field?.invalid) ?? undefined}
                    required={rest.required ?? field?.required}
                    disabled={rest.disabled ?? field?.disabled}
                    onInput={e => {
                        fit(e.currentTarget);
                        onInput?.(e);
                    }}
                    className={cn(
                        variant === "filled" ? FILLED : OUTLINED,
                        "resize-y px-4 pb-3 pt-6 leading-6",
                        autoResize && "resize-none",
                    )}
                    {...rest}
                />
                <label
                    htmlFor={id}
                    className={cn(
                        "pointer-events-none absolute left-4 top-4 z-[1] origin-left text-body-lg text-on-surface-variant",
                        "transition-[transform,color] duration-short4 ease-standard",
                        "peer-focus:top-2 peer-focus:text-body-sm peer-focus:text-primary",
                        "peer-[:not(:placeholder-shown)]:top-2 peer-[:not(:placeholder-shown)]:text-body-sm",
                        "peer-disabled:opacity-[0.38] peer-aria-[invalid=true]:text-error",
                    )}
                >
                    {label}
                </label>
            </div>
            {error ? (
                <SupportingText id={msgId} error>
                    {error}
                </SupportingText>
            ) : hint ? (
                <SupportingText id={msgId}>{hint}</SupportingText>
            ) : null}
        </div>
    );
});

/* ── Select ───────────────────────────────────────────────────────────── */

export type SelectProps = Omit<ComponentPropsWithoutRef<"select">, "size"> & {
    label: string;
    variant?: TextFieldVariant;
    hint?: ReactNode;
    error?: ReactNode;
    dense?: boolean;
    className?: string;
};

/**
 * A value picked from `Menu` — the same floating list every other dropdown
 * in the app uses, so a select looks and opens the
 * same way on a laptop as on a phone. Was the browser's own `<select>`;
 * owner reversed that 2026-09-22 — every dropdown, every device, one look.
 *
 * Takes `<option>` children so no call site had to change: value defaults to
 * `value`/`children` text the same way a native option does, and `onChange`
 * still gets a `{ target: { value } }` event.
 *
 * The label does not float here: a select always has a value, so it would be
 * floated from the first paint anyway. It sits above, small, permanently.
 */
export const Select = function Select(
    { label, variant = "filled", hint, error, dense, className, children, value, onChange, disabled, id: idProp, "aria-describedby": describedBy, "aria-invalid": invalidProp }: SelectProps,
) {
    const field = useFieldState();
    const uid = useId();
    const id = idProp ?? field?.id ?? `sel-${uid}`;
    const msgId = error || hint ? `${id}-msg` : undefined;
    const isDisabled = disabled ?? field?.disabled;

    const options = Children.toArray(children)
        .filter((c): c is ReactElement<{ value?: string; disabled?: boolean; children?: ReactNode }> => isValidElement(c) && c.type === "option")
        .map((c) => ({
            value: c.props.value !== undefined ? String(c.props.value) : String(c.props.children ?? ""),
            label: c.props.children,
            disabled: c.props.disabled,
        }));
    const current = options.find((o) => o.value === value) ?? options[0];

    return (
        <div className={cn("flex min-w-0 flex-col", className)}>
            <Menu
                label={label}
                trigger={(p) => (
                    <div className="relative flex min-w-0 items-center">
                        <button
                            {...p}
                            type="button"
                            id={id}
                            disabled={isDisabled}
                            aria-describedby={describedBy ?? msgId ?? field?.describedBy}
                            aria-invalid={invalidProp ?? (error ? true : field?.invalid) ?? undefined}
                            className={cn(
                                variant === "filled" ? FILLED : OUTLINED,
                                dense ? "h-12 pt-5" : "h-14 pt-6",
                                "w-full text-left cursor-pointer pb-2 pl-4 pr-10",
                            )}
                        >
                            <span className="block truncate">{current?.label}</span>
                        </button>
                        <span aria-hidden className={cn("pointer-events-none absolute left-4 z-[1] text-body-sm text-on-surface-variant", dense ? "top-1" : "top-2")}>
                            {label}
                        </span>
                        <Icon icon={ChevronDown} size="md" className="pointer-events-none absolute right-3 text-on-surface-variant" />
                    </div>
                )}
            >
                {options.map((o) => (
                    <MenuItem
                        key={o.value}
                        checked={o.value === current?.value}
                        disabled={o.disabled}
                        onSelect={() => onChange?.({ target: { value: o.value } } as unknown as ChangeEvent<HTMLSelectElement>)}
                    >
                        {o.label}
                    </MenuItem>
                ))}
            </Menu>
            {error ? (
                <SupportingText id={msgId} error>
                    {error}
                </SupportingText>
            ) : hint ? (
                <SupportingText id={msgId}>{hint}</SupportingText>
            ) : null}
        </div>
    );
};

/* ── Search ───────────────────────────────────────────────────────────── */

export type SearchProps = Omit<ComponentPropsWithoutRef<"input">, "type" | "size"> & {
    /** What is being searched, e.g. "Search agents". It is the field's name. */
    label: string;
    /** Shows a clear button when there is text. */
    onClear?: () => void;
    className?: string;
};

/**
 * M3 search bar — https://m3.material.io/components/search
 *
 * A `full`-cornered `surface-container-high` bar, not a text field. It is
 * `type="search"`, so the browser gives Escape-to-clear and the right keyboard
 * on a phone for free.
 */
export const Search = forwardRef<HTMLInputElement, SearchProps>(function Search({ label, onClear, className, value, ...rest }, ref) {
    const uid = useId();
    const id = rest.id ?? `search-${uid}`;
    return (
        <div className={cn("relative flex min-w-0 items-center", className)}>
            <label htmlFor={id} className="sr-only">
                {label}
            </label>
            <Icon icon={SearchIcon} size="sm" className="pointer-events-none absolute left-3.5 text-on-surface-variant" />
            <input
                ref={ref}
                id={id}
                type="search"
                value={value}
                placeholder={label}
                className={cn(
                    "h-11 w-full min-w-0 rounded-small bg-surface-container pl-11 pr-11 text-body-lg text-on-surface",
                    "placeholder:text-on-surface-variant",
                    "transition-[background-color,box-shadow] duration-short4 ease-standard",
                    "hover:bg-surface-container-high",
                    /* Focus: the same white box, blue edge and halo as every field. */
                    "outline-none focus:bg-surface-container-lowest dark:focus:bg-surface-container-low focus:shadow-[inset_0_0_0_1px_var(--md-sys-color-primary),0_0_0_3px_rgb(var(--md-sys-color-primary-rgb)/0.18)]",
                    /* The browser's own clear X would be a second one. */
                    "[&::-webkit-search-cancel-button]:appearance-none",
                )}
                {...rest}
            />
            {onClear && value ? (
                <button
                    type="button"
                    onClick={onClear}
                    aria-label={`Clear ${label.toLowerCase()}`}
                    className={cn(
                        "absolute right-1.5 inline-flex h-8 w-8 items-center justify-center rounded-small text-on-surface-variant before:absolute before:left-1/2 before:top-1/2 before:h-touch before:w-touch before:-translate-x-1/2 before:-translate-y-1/2 before:content-['']",
                        interactive(),
                    )}
                >
                    <Icon icon={X} size="md" />
                </button>
            ) : null}
        </div>
    );
});

/* ── Colour field ─────────────────────────────────────────────────────── */

export type ColorFieldProps = {
    /** What the colour is for, e.g. "Background colour". Never unlabelled. */
    label: string;
    /** An upper-case `#RRGGBB`. */
    value: string;
    /** Every step of a drag. */
    onChange: (hex: string) => void;
    /** Once, when the picker closes on a new colour. */
    onCommit?: (hex: string) => void;
    /** The picture's own colours, shown first in the picker. */
    swatches?: string[];
    /** Shown under the swatch. Keep it to a few words. */
    hint?: ReactNode;
    className?: string;
};

/**
 * Pick any colour: the colour as a circle, and a tap opens our picker
 * (ColorPicker.tsx) - square, hue, hex, eyedropper, palettes.
 *
 * 🔴 Not the browser's `<input type="color">` any more (owner, 2026-10-04):
 * its popup is an OS window, so a sheet around it closed the moment a finger
 * touched its slider. The whole control is the button, so the tap target is the
 * control, not a 20px chip inside it.
 *
 * The value is a colour a person chose - content, not a design token - so it
 * is the one place a raw hex legitimately lives.
 */
export function ColorField({ label, value, onChange, onCommit, swatches, hint, className }: ColorFieldProps) {
    const uid = useId();
    return (
        <ColorPopover
            label={label}
            value={value}
            onChange={(hex) => onChange(hex.toUpperCase())}
            onCommit={onCommit ? (hex) => onCommit(hex.toUpperCase()) : undefined}
            swatches={swatches}
            trigger={(p) => (
                <button
                    type="button"
                    {...p}
                    aria-label={`${label}: ${value.toUpperCase()}`}
                    aria-describedby={hint ? `cf-${uid}-msg` : undefined}
                    className={cn("relative flex min-h-touch min-w-0 flex-col items-center justify-center gap-1", focusRing, className)}
                >
                    <span aria-hidden className="h-6 w-6 rounded-full shadow-level-1" style={{ backgroundColor: value }} />
                    <span className="text-label-sm font-medium text-on-surface-variant">{label}</span>
                    {hint ? <SupportingText id={`cf-${uid}-msg`}>{hint}</SupportingText> : null}
                </button>
            )}
        />
    );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type KeyboardEvent, type MouseEvent as ReactMouseEvent, type ReactNode, type RefObject } from "react";
import { Check, ChevronRight } from "@/ui/symbols";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { Kbd } from "../primitives/Skeleton";
import { place, useAnchoredPosition, type Placement } from "./position";
import { justClosed, useAwake, type PopoverTriggerProps } from "./Popover";
import { downloadHrefClick } from "./Download";

export type MenuProps = {
    trigger: (props: PopoverTriggerProps) => ReactNode;
    children: ReactNode;
    placement?: Placement;
    /** Names the menu for screen readers, e.g. "Account". */
    label: string;
    className?: string;
    /**
     * Right-click on this element opens the SAME menu at the pointer
     * (Shift+F10 / the Menu key too). One list of items, so the ⋮ menu and
     * the right-click menu can never differ. Text fields and links inside it
     * keep the browser's own menu. A touch long-press does not open it: on a
     * phone that gesture selects, and the ⋮ is always visible.
     */
    contextTarget?: RefObject<HTMLElement | null>;
    /** Leave the items out of the server HTML - see Popover's `clientOnly`. Never for navigation. */
    clientOnly?: boolean;
};

const ITEM_SELECTOR = '[role="menuitem"]:not([aria-disabled="true"]),[role="menuitemradio"]:not([aria-disabled="true"]),[role="menuitemcheckbox"]:not([aria-disabled="true"])';

/**
 * 🔴 A menu inside a draggable tile (the studio grid: drag a picture into the
 * prompt bar) is part of that tile, and a native drag starts from any child:
 * a click on a row that moved a pixel dragged the whole picture and the row
 * never got its click. Switch the drag off until the press ends.
 */
export function holdStill(el: HTMLElement) {
    const tile = el.parentElement?.closest<HTMLElement>('[draggable="true"]');
    if (!tile) return;
    tile.draggable = false;
    const back = () => {
        tile.draggable = true;
        window.removeEventListener("pointerup", back, true);
        window.removeEventListener("pointercancel", back, true);
    };
    window.addEventListener("pointerup", back, true);
    window.addEventListener("pointercancel", back, true);
}

const ownItems = (menu: HTMLElement | null) =>
    Array.from(menu?.querySelectorAll<HTMLElement>(ITEM_SELECTOR) ?? []).filter(el => el.closest("[popover]") === menu);

/**
 * A list of actions from a trigger.
 *
 * Keyboard, all from here because the browser does not do it for menus:
 * ↓/↑ move (wrapping), Home/End jump, letters jump to the next item starting
 * with them, Enter/Space run, Esc closes and returns focus to the trigger
 * (the popover API handles Esc and click-outside).
 */
export function Menu({ trigger, children, placement = "bottom-start", label, className, contextTarget, clientOnly }: MenuProps) {
    const awake = useAwake(clientOnly);
    const id = `menu-${useId()}`;
    const anchor = useRef<HTMLElement | null>(null);
    /** What the menu is placed against: the trigger, or the pointer after a right-click. */
    const at = useRef<HTMLElement | null>(null);
    const pop = useRef<HTMLDivElement | null>(null);
    const typed = useRef({ buffer: "", at: 0 });
    const [open, setOpen] = useState(false);
    /** When light dismiss last closed it - see justClosed(). */
    const closedAt = useRef(0);
    /** The close about to happen is a row being chosen, not a click outside. */
    const choosing = useRef(false);
    useAnchoredPosition(at as React.RefObject<HTMLElement>, pop as React.RefObject<HTMLElement>, open, placement);

    useEffect(() => {
        const target = contextTarget?.current;
        if (!target) return;
        const onContext = (e: MouseEvent) => {
            if ((e.target as HTMLElement).closest("input,textarea,select,a[href],[contenteditable]")) return;
            e.preventDefault();
            // A finger's long-press selects (ImageTile); the ⋮ is always
            // shown on touch, so the menu is one tap away there.
            if ((e as PointerEvent).pointerType === "touch") return;
            // A keyboard-opened context menu reports 0,0: use the element itself.
            const r = e.clientX || e.clientY ? new DOMRect(e.clientX, e.clientY, 0, 0) : target.getBoundingClientRect();
            const show = () => {
                at.current = { getBoundingClientRect: () => r } as HTMLElement;
                pop.current?.showPopover();
                if (pop.current) place(at.current, pop.current, "bottom-start", 0);
            };
            // 🔴 macOS fires `contextmenu` on mouse DOWN. Opened there, the
            // mouse-up that follows is a pointerup outside the menu whose
            // pointerdown saw no popover - and the popover API light-dismisses
            // on exactly that, so the menu flashed and vanished. Wait for the
            // button to come up, then open. Windows fires it on mouse up
            // (buttons 0), and a keyboard-opened menu has no button at all.
            if (!e.buttons) { show(); return; }
            const up = () => {
                window.removeEventListener("pointerup", up, true);
                window.removeEventListener("pointercancel", up, true);
                setTimeout(show, 0);
            };
            window.addEventListener("pointerup", up, true);
            window.addEventListener("pointercancel", up, true);
        };
        target.addEventListener("contextmenu", onContext);
        return () => target.removeEventListener("contextmenu", onContext);
    }, [contextTarget]);

    /** This menu's own items - never the ones inside a submenu it holds. */
    const items = useCallback(() => ownItems(pop.current), []);

    const focusAt = useCallback(
        (index: number) => {
            const list = items();
            if (!list.length) return;
            const i = (index + list.length) % list.length;
            list[i].focus();
        },
        [items],
    );

    useEffect(() => {
        const el = pop.current;
        if (!el) return;
        const onToggle = (e: Event) => {
            const next = (e as ToggleEvent).newState === "open";
            setOpen(next);
            if (next) {
                if (!at.current) at.current = anchor.current;
                if (at.current) requestAnimationFrame(() => at.current && place(at.current, el, at.current === anchor.current ? placement : "bottom-start", at.current === anchor.current ? 6 : 0));
                // Focus the current item if there is one, else the first.
                requestAnimationFrame(() => {
                    const list = items();
                    const current = list.findIndex(i => i.getAttribute("aria-checked") === "true");
                    (list[current >= 0 ? current : 0])?.focus();
                });
            } else {
                at.current = null;
                anchor.current?.focus();
            }
        };
        const onBeforeToggle = (e: Event) => {
            if ((e as ToggleEvent).newState !== "closed") return;
            closedAt.current = performance.now();
            // A row was chosen: that click is the menu's own, and the next
            // click anywhere is a new one - never eat it.
            if (choosing.current) { choosing.current = false; return; }
            // 🔴 A click outside closes the menu on pointerup, then the click
            // itself still landed on whatever was under it - a grid tile, which
            // opened the editor (owner, 2026-09-30). Like a desktop menu: that
            // click only closes it.
            const swallow = (ev: MouseEvent) => {
                window.removeEventListener("click", swallow, true);
                if (el.contains(ev.target as Node)) return;
                ev.preventDefault();
                ev.stopPropagation();
            };
            window.addEventListener("click", swallow, true);
            setTimeout(() => window.removeEventListener("click", swallow, true), 300);
        };
        el.addEventListener("toggle", onToggle);
        el.addEventListener("beforetoggle", onBeforeToggle);
        return () => {
            el.removeEventListener("toggle", onToggle);
            el.removeEventListener("beforetoggle", onBeforeToggle);
        };
    }, [items, placement]);

    const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
        // Keys in a menu are the menu's: Enter on a row must not also open the
        // tile or grid it sits in.
        e.stopPropagation();
        const list = items();
        const at = list.indexOf(document.activeElement as HTMLElement);
        if (e.key === "ArrowDown") { e.preventDefault(); focusAt(at + 1); return; }
        if (e.key === "ArrowUp") { e.preventDefault(); focusAt(at - 1); return; }
        if (e.key === "Home") { e.preventDefault(); focusAt(0); return; }
        if (e.key === "End") { e.preventDefault(); focusAt(list.length - 1); return; }
        if (e.key === "Tab") { pop.current?.hidePopover(); return; }
        if (e.key.length === 1 && /\S/.test(e.key)) {
            const now = Date.now();
            typed.current.buffer = now - typed.current.at > 800 ? e.key : typed.current.buffer + e.key;
            typed.current.at = now;
            const q = typed.current.buffer.toLowerCase();
            const from = at + (typed.current.buffer.length > 1 ? 0 : 1);
            const found = list.findIndex((el, i) => i >= from && el.textContent?.trim().toLowerCase().startsWith(q));
            const wrapped = found >= 0 ? found : list.findIndex(el => el.textContent?.trim().toLowerCase().startsWith(q));
            if (wrapped >= 0) { e.preventDefault(); focusAt(wrapped); }
        }
    };

    return (
        <>
            {trigger({
                ref: node => {
                    anchor.current = node;
                },
                onClick: () => {
                    if (justClosed(closedAt.current)) return;
                    at.current = anchor.current;
                    pop.current?.togglePopover();
                },
                "aria-expanded": open,
                "aria-haspopup": "menu",
                "aria-controls": id,
            })}
            <div
                ref={pop}
                id={id}
                popover="auto"
                role="menu"
                aria-label={label}
                onKeyDown={onKeyDown}
                onClick={e => {
                    // 🔴 The popover is drawn INSIDE whatever holds its trigger - a
                    // grid tile, a card. Without this, choosing "Share to X" also
                    // clicked the tile under the menu and opened the picture
                    // editor (2026-09-29). Nothing chosen in a menu is a click
                    // on its host.
                    e.stopPropagation();
                    // Any item that did not stop the event closes the menu.
                    if ((e.target as HTMLElement).closest('[role^="menuitem"]')) { choosing.current = true; pop.current?.hidePopover(); choosing.current = false; }
                }}
                // Same reason: a press held on a row must not start the host
                // tile's long-press (which selects it) or its double-click.
                onPointerDown={e => { e.stopPropagation(); holdStill(e.currentTarget); }}
                onDoubleClick={e => e.stopPropagation()}
                className={cn(
                    // `pointer-events-auto`: the menu sits inside its trigger's
                    // box, and a tile hides that box from taps until hovered -
                    // the menu must never inherit that.
                    "m3-pop pointer-events-auto max-h-[min(26rem,80dvh)] min-w-[13rem] max-w-[min(20rem,calc(100vw-1rem))] overflow-y-auto",
                    /* M3 menu (material-web md-comp-menu): `surface-container`, elevation 2. */
                    "rounded-medium border-0 bg-surface-container-lowest py-1.5 px-1.5 text-on-surface shadow-level-3 dark:bg-surface-container-high",
                    className,
                )}
            >
                {awake && children}
            </div>
        </>
    );
}

export type MenuItemProps = {
    children: ReactNode;
    icon?: IconGlyph;
    /** A small picture in the icon's place (24 px): a live motion preview, a swatch. */
    visual?: ReactNode;
    /** Shown right-aligned: a shortcut, a value, a count. */
    hint?: ReactNode;
    shortcut?: string[];
    onSelect?: () => void;
    /**
     * A real link instead of a click handler — a page to open, a file to
     * download. Renders an `<a>` so middle-click, "open in new tab" and (with
     * `download`) the browser's own save-file flow keep working, which a
     * `router.push` in `onSelect` cannot give you.
     */
    href?: string;
    /** Anchor-only: forces a download instead of navigating. */
    download?: string | boolean;
    target?: string;
    disabled?: boolean;
    /** Marks the current choice. Makes this a radio item for screen readers. */
    checked?: boolean;
    /** An on/off row (a checkbox item) instead of a choice. Shows a check when on. */
    toggle?: boolean;
    /** A second line under the label: what this option is for. Makes the row two lines tall. */
    description?: ReactNode;
    destructive?: boolean;
    className?: string;
};

export function MenuItem({ children, icon, visual, hint, shortcut, onSelect, href, download, target, disabled, checked, toggle, description, destructive, className }: MenuItemProps) {
    const Tag = href ? "a" : "button";
    const on = toggle ? !!checked : checked;
    return (
        <Tag
            {...(href ? { href, download, target, rel: target === "_blank" ? "noopener noreferrer" : undefined } : { type: "button" })}
            role={toggle ? "menuitemcheckbox" : checked === undefined ? "menuitem" : "menuitemradio"}
            aria-checked={toggle ? !!checked : checked}
            aria-disabled={disabled || undefined}
            tabIndex={-1}
            onClick={disabled ? (e: { preventDefault: () => void }) => e.preventDefault() : (e: ReactMouseEvent) => {
                // A file link comes through the download card, not the browser's bare save.
                if (href && download) downloadHrefClick(e, href, download);
                onSelect?.();
            }}
            className={cn(
                // 48dp rows under a finger (M3's touch floor), dense under a mouse.
                "flex w-full min-h-8 items-center gap-2.5 rounded-small px-2.5 text-left text-body-md touch:min-h-12",
                description && "min-h-14 py-2 touch:min-h-14",
                "transition-colors duration-short2 ease-standard",
                // `focus-visible`, not `focus`: the menu focuses its current
                // row when it opens, and after a TAP that left a grey block
                // on it that read as a second selection. Keys still show it.
                "focus:outline-none focus-visible:bg-on-surface/[0.12]",
                "[@media(hover:hover)]:hover:bg-on-surface/[0.08]",
                // The chosen row is M3's selected list item: the secondary
                // container, in both themes - never just a small check.
                on && !toggle && !destructive && "bg-secondary-container text-on-secondary-container [@media(hover:hover)]:hover:bg-secondary-container",
                destructive ? "text-error [@media(hover:hover)]:hover:bg-error-container focus-visible:bg-error-container" : !(on && !toggle) && "text-on-surface",
                disabled && "pointer-events-none text-on-surface/[0.38]",
                className,
            )}
        >
            {visual ? <span aria-hidden className="grid h-6 w-6 shrink-0 place-items-center">{visual}</span>
                : icon ? <Icon icon={icon} size="md" hoverFill={!destructive} className={destructive || (on && !toggle) ? undefined : "text-on-surface"} /> : null}
            {description ? (
                <span className="flex min-w-0 flex-1 flex-col">
                    <span className="truncate">{children}</span>
                    <span className={cn("text-label-md", on && !toggle ? "text-on-secondary-container/80" : "text-on-surface-variant")}>{description}</span>
                </span>
            ) : <span className="min-w-0 flex-1 truncate">{children}</span>}
            {shortcut ? (
                <span className="flex gap-1">
                    {shortcut.map(k => (
                        <Kbd key={k}>{k}</Kbd>
                    ))}
                </span>
            ) : null}
            {hint ? <span className={cn("text-label-md", on && !toggle ? "text-on-secondary-container/80" : "text-on-surface-variant")}>{hint}</span> : null}
            {on ? <Icon icon={Check} size="sm" className={toggle ? "text-primary" : undefined} /> : null}
        </Tag>
    );
}

export function MenuSeparator() {
    // Law 11: a group break is space, not a rule. The role stays so a screen
    // reader still announces the grouping a sighted user reads from the gap.
    return <div className="my-2" role="separator" />;
}

export function MenuLabel({ children }: { children: ReactNode }) {
    return <p className="px-2.5 pb-1 pt-1.5 text-label-md text-on-surface-variant">{children}</p>;
}

/**
 * A row that opens a second menu beside it - "Download ▸" → PNG, SVG…
 *
 * Opens on hover (a short delay, so passing over it does nothing), on tap,
 * and on → / Enter / Space. ← or Esc closes it and goes back to the row.
 * The flyout sits to the right and drops below the row where there is no
 * room (a phone). It is a popover INSIDE the parent's, so opening it never
 * light-dismisses the parent, and choosing an item closes both.
 */
export function MenuSub({ label, icon, children, disabled }: { label: ReactNode; icon?: IconGlyph; children: ReactNode; disabled?: boolean }) {
    const id = `submenu-${useId()}`;
    const row = useRef<HTMLButtonElement | null>(null);
    const pop = useRef<HTMLDivElement | null>(null);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [open, setOpen] = useState(false);

    const wait = (fn: () => void, ms: number) => {
        if (timer.current) clearTimeout(timer.current);
        timer.current = setTimeout(fn, ms);
    };
    const isOpen = () => !!pop.current?.matches(":popover-open");
    const show = (focusFirst = false) => {
        if (timer.current) clearTimeout(timer.current);
        const el = pop.current;
        if (!el || disabled) return;
        if (!isOpen()) el.showPopover();
        if (row.current) place(row.current, el, "right-start", 2);
        if (focusFirst) requestAnimationFrame(() => ownItems(el)[0]?.focus());
    };
    const hide = (backToRow = false) => {
        if (timer.current) clearTimeout(timer.current);
        if (isOpen()) pop.current?.hidePopover();
        if (backToRow) row.current?.focus();
    };

    useEffect(() => {
        const el = pop.current;
        if (!el) return;
        const onToggle = (e: Event) => setOpen((e as ToggleEvent).newState === "open");
        el.addEventListener("toggle", onToggle);
        return () => el.removeEventListener("toggle", onToggle);
    }, []);
    useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);

    const onSubKey = (e: KeyboardEvent<HTMLDivElement>) => {
        const list = ownItems(pop.current);
        const at = list.indexOf(document.activeElement as HTMLElement);
        const go = (i: number) => list[(i + list.length) % list.length]?.focus();
        if (e.key === "ArrowDown") go(at + 1);
        else if (e.key === "ArrowUp") go(at - 1);
        else if (e.key === "Home") go(0);
        else if (e.key === "End") go(list.length - 1);
        else if (e.key === "ArrowLeft" || e.key === "Escape") hide(true);
        else if (e.key === "Tab") { hide(); return; }
        else return;
        // The parent menu must not act on the same key.
        e.preventDefault();
        e.stopPropagation();
    };

    return (
        <>
            <button
                ref={row}
                type="button"
                role="menuitem"
                aria-haspopup="menu"
                aria-expanded={open}
                aria-controls={id}
                aria-disabled={disabled || undefined}
                tabIndex={-1}
                onPointerEnter={(e) => { if (e.pointerType === "mouse") wait(() => show(), 120); }}
                onPointerLeave={(e) => { if (e.pointerType === "mouse") wait(() => hide(), 250); }}
                // A tap or a click opens - never closes: hover has usually
                // opened it already, and closing it sent the next click onto the
                // picture under it (owner, 2026-09-30). It must not reach the
                // parent's "an item was chosen, close" handler.
                onClick={(e) => { e.stopPropagation(); show(e.detail === 0); }}
                onKeyDown={(e) => { if (e.key === "ArrowRight") { e.preventDefault(); e.stopPropagation(); show(true); } }}
                className={cn(
                    "flex w-full min-h-8 items-center gap-2.5 rounded-small px-2.5 text-left text-body-md text-on-surface touch:min-h-11",
                    "transition-colors duration-short2 ease-standard",
                    "focus:outline-none focus:bg-on-surface/[0.08] hover:bg-on-surface/[0.08]",
                    open && "bg-on-surface/[0.08]",
                    disabled && "pointer-events-none text-on-surface/[0.38]",
                )}
            >
                {icon ? <Icon icon={icon} size="md" hoverFill className="text-on-surface" /> : null}
                <span className="min-w-0 flex-1 truncate">{label}</span>
                <Icon icon={ChevronRight} size="sm" className="text-on-surface-variant" />
            </button>
            <div
                ref={pop}
                id={id}
                popover="auto"
                role="menu"
                onKeyDown={onSubKey}
                onPointerEnter={() => { if (timer.current) clearTimeout(timer.current); }}
                onPointerLeave={(e) => { if (e.pointerType === "mouse") wait(() => hide(), 250); }}
                className="m3-pop max-h-[min(26rem,80dvh)] min-w-[11rem] max-w-[min(20rem,calc(100vw-1rem))] overflow-y-auto rounded-medium border-0 bg-surface-container-lowest p-1.5 text-on-surface shadow-level-3 dark:bg-surface-container-high"
            >
                {children}
            </div>
        </>
    );
}

/**
 * One thing you can do to something, written once and handed to every way
 * of opening its menu
 */
export type MenuAction = {
    key: string;
    label: ReactNode;
    icon?: IconGlyph;
    onSelect?: () => void;
    href?: string;
    download?: string | boolean;
    disabled?: boolean;
    destructive?: boolean;
    checked?: boolean;
    shortcut?: string[];
    hint?: ReactNode;
    /** A second line under the label (MenuItem `description`). */
    description?: ReactNode;
    /** A small picture in the icon's place (MenuItem `visual`). */
    visual?: ReactNode;
    /** Starts a new group: a line above, and this label over it if given. */
    group?: string | true;
    /** A submenu: this row opens these actions beside it (MenuSub). */
    children?: MenuAction[];
};

/** Renders a list of `MenuAction`s as menu items. */
export function MenuActions({ actions }: { actions: MenuAction[] }) {
    return (
        <>
            {actions.map((a, i) => (
                <div key={a.key} role="none" className="contents">
                    {a.group && i > 0 ? <MenuSeparator /> : null}
                    {typeof a.group === "string" ? <MenuLabel>{a.group}</MenuLabel> : null}
                    {a.children ? (
                        <MenuSub label={a.label} icon={a.icon} disabled={a.disabled}>
                            <MenuActions actions={a.children} />
                        </MenuSub>
                    ) : <MenuItem
                        icon={a.icon}
                        visual={a.visual}
                        description={a.description}
                        onSelect={a.onSelect}
                        href={a.href}
                        download={a.download}
                        disabled={a.disabled}
                        destructive={a.destructive}
                        checked={a.checked}
                        shortcut={a.shortcut}
                        hint={a.hint}
                    >
                        {a.label}
                    </MenuItem>}
                </div>
            ))}
        </>
    );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from "react";
import { cn } from "../cn";
import { place, useAnchoredPosition, type Placement } from "./position";

/**
 * 🔴 Clicking the trigger of an OPEN popover used to leave it open. The
 * browser's light dismiss closes it on pointerup, then the click that follows
 * toggles it straight back open. `beforetoggle` fires synchronously on close,
 * so a click within a few ms of it is that same gesture — ignore it.
 */
export function justClosed(at: number) {
    return performance.now() - at < 300;
}

export type PopoverTriggerProps = {
    ref: (node: HTMLElement | null) => void;
    onClick: () => void;
    "aria-expanded": boolean;
    "aria-haspopup": "dialog" | "menu" | "listbox";
    "aria-controls": string;
};

export type PopoverProps = {
    /** Render the control that opens it, spreading the props onto it. */
    trigger: (props: PopoverTriggerProps) => ReactNode;
    children: ReactNode | ((close: () => void) => ReactNode);
    placement?: Placement;
    /** What the popover contains, for screen readers. */
    role?: "dialog" | "menu" | "listbox";
    label?: string;
    className?: string;
    onOpenChange?: (open: boolean) => void;
    /** Controlled open state. Leave it out and the popover manages itself. */
    open?: boolean;
    /**
     * Leave the contents out of the server HTML (drawn right after the page
     * wakes up, so the first open is instant). For pickers on public pages:
     * a crawler then reads the page's sentences, not every model and colour
     * in a closed menu. Never for navigation - its links must stay in the HTML.
     */
    clientOnly?: boolean;
};

/**
 * A floating panel anchored to a trigger.
 *
 * Built on the browser's popover API, which gives us the top layer (never
 * clipped by a scrolling parent), Esc to close, and click-outside to dismiss -
 * the three things hand-rolled dropdowns get wrong. We add the positioning.
 */
export function Popover({ trigger, children, placement = "bottom-start", role = "dialog", label, className, onOpenChange, open: controlled, clientOnly }: PopoverProps) {
    const awake = useAwake(clientOnly);
    const id = `pop-${useId()}`;
    const anchor = useRef<HTMLElement | null>(null);
    const pop = useRef<HTMLDivElement | null>(null);
    const [open, setOpen] = useState(false);
    /** When light dismiss last closed it - see justClosed(). */
    const closedAt = useRef(0);
    useAnchoredPosition(anchor as React.RefObject<HTMLElement>, pop as React.RefObject<HTMLElement>, open, placement);

    const close = useCallback(() => pop.current?.hidePopover(), []);

    /* A caller that owns the state (closes it after a pick) drives the
       native popover from here; the toggle listener reports back. */
    useEffect(() => {
        const el = pop.current;
        if (!el || controlled === undefined) return;
        const isOpen = el.matches(":popover-open");
        if (controlled && !isOpen) el.showPopover();
        if (!controlled && isOpen) el.hidePopover();
    }, [controlled]);

    useEffect(() => {
        const el = pop.current;
        if (!el) return;
        const onToggle = (e: Event) => {
            const next = (e as ToggleEvent).newState === "open";
            setOpen(next);
            onOpenChange?.(next);
            if (next && anchor.current && el) {
                // Position before the first paint of the open state.
                requestAnimationFrame(() => anchor.current && place(anchor.current, el, placement));
            }
        };
        const onBeforeToggle = (e: Event) => {
            if ((e as ToggleEvent).newState === "closed") closedAt.current = performance.now();
        };
        el.addEventListener("toggle", onToggle);
        el.addEventListener("beforetoggle", onBeforeToggle);
        return () => {
            el.removeEventListener("toggle", onToggle);
            el.removeEventListener("beforetoggle", onBeforeToggle);
        };
    }, [onOpenChange, placement]);

    return (
        <>
            {trigger({
                ref: node => {
                    anchor.current = node;
                },
                onClick: () => {
                    if (!justClosed(closedAt.current)) pop.current?.togglePopover();
                },
                "aria-expanded": open,
                "aria-haspopup": role === "menu" ? "menu" : role,
                "aria-controls": id,
            })}
            <div
                ref={pop}
                id={id}
                popover="auto"
                role={role === "dialog" ? "dialog" : undefined}
                aria-label={label}
                className={cn(
                    "m3-pop max-h-[min(24rem,80dvh)] min-w-[12rem] max-w-[min(20rem,calc(100vw-1rem))] overflow-y-auto overflow-x-hidden",
                    "rounded-medium border-0 bg-surface-container-lowest p-1.5 text-on-surface shadow-level-3 dark:bg-surface-container-high",
                    className,
                )}
            >
                {awake && (typeof children === "function" ? children(close) : children)}
            </div>
        </>
    );
}

/** False on the server and the first client render when `clientOnly`, true from then on. */
export function useAwake(clientOnly?: boolean): boolean {
    const [awake, setAwake] = useState(!clientOnly);
    useEffect(() => { if (clientOnly) setAwake(true); }, [clientOnly]);
    return awake;
}

import type { ReactNode } from "react";
import { cn } from "../cn";

/**
 * The shapes a form-like page is built from — Settings, My stuff → Profile,
