}

import type { ReactNode } from "react";
import { cn } from "../cn";

export type Column<Row> = {
    key: string;
    header: ReactNode;
    /** Cell content for one row. */
    cell: (row: Row) => ReactNode;
    /** Numbers right-align and use tabular digits so columns line up. */
    numeric?: boolean;
    /** Hidden below `sm`: keep the phone view to what matters. */
    hideOnPhone?: boolean;
    width?: string;
};

export type TableProps<Row> = {
    /** Names the table for screen readers, e.g. "Runs this week". */
    label: string;
    columns: Column<Row>[];
    rows: Row[];
    rowKey: (row: Row) => string;
    onRowClick?: (row: Row) => void;
    /** Shown instead of the table when there are no rows. */
    empty?: ReactNode;
    className?: string;
};

/**
 * Rows of data. Still a real `<table>`, so screen readers announce the column
 * with each cell and the browser can sort, select and copy naturally.
 *
 * On a phone it scrolls sideways inside its own box - the page itself must
 * never scroll sideways - and columns marked `hideOnPhone` drop out first.
 */
export function Table<Row>({ label, columns, rows, rowKey, onRowClick, empty, className }: TableProps<Row>) {
    if (!rows.length && empty) return <>{empty}</>;

    return (
        <div className={cn("min-w-0 overflow-x-auto rounded-medium bg-surface-container", className)}>
            <table className="w-full border-collapse text-body-sm">
                <caption className="sr-only">{label}</caption>
                <thead>
                    <tr>
                        {columns.map(c => (
                            <th
                                key={c.key}
                                scope="col"
                                style={c.width ? { width: c.width } : undefined}
                                className={cn(
                                    "whitespace-nowrap bg-surface-container-high px-3 py-2.5 text-label-md text-on-surface-variant",
                                    c.numeric ? "text-right" : "text-left",
                                    c.hideOnPhone && "hidden sm:table-cell",
                                )}
                            >
                                {c.header}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {rows.map(row => (
                        <tr
                            key={rowKey(row)}
                            onClick={onRowClick ? () => onRowClick(row) : undefined}
                            className={cn(
                                "",
                                onRowClick && "cursor-pointer transition-colors duration-short2 ease-standard hover:bg-on-surface/[0.08]",
                            )}
                        >
                            {columns.map(c => (
                                <td
                                    key={c.key}
                                    className={cn(
                                        "px-3 py-3.5 text-on-surface",
                                        c.numeric ? "text-right tnum" : "text-left",
                                        c.hideOnPhone && "hidden sm:table-cell",
                                    )}
                                >
                                    {c.cell(row)}
                                </td>
                            ))}
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}

export type ListProps = { className?: string; children: ReactNode };

/** A stack of rows that are objects, not data points: agents, runs, keys. */
export function List({ className, children }: ListProps) {
    return <ul className={cn("min-w-0 overflow-hidden rounded-medium bg-surface-container", className)}>{children}</ul>;
}

export type ListItemProps = {
    /** Avatar, icon or thumbnail. */
    leading?: ReactNode;
    title: ReactNode;
    description?: ReactNode;
    /** Status, price or a button. */
    trailing?: ReactNode;
    onClick?: () => void;
    href?: string;
    className?: string;
};

export function ListItem({ leading, title, description, trailing, onClick, href, className }: ListItemProps) {
    const inner = (
        <>
            {leading ? <span className="shrink-0">{leading}</span> : null}
            <span className="min-w-0 flex-1">
                <span className="block truncate text-body-md text-on-surface">{title}</span>
                {description ? <span className="block truncate text-label-md text-on-surface-variant">{description}</span> : null}
            </span>
            {trailing ? <span className="flex shrink-0 items-center gap-2">{trailing}</span> : null}
        </>
    );

    const shared = cn(
        "flex w-full min-h-14 items-center gap-3 px-3 py-2.5 text-left",
        (onClick || href) &&
            "transition-colors duration-short2 ease-standard hover:bg-on-surface/[0.08] focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-primary",
        className,
    );

    return (
        <li className="min-w-0">
            {href ? (
                <a href={href} className={shared}>
                    {inner}
                </a>
            ) : onClick ? (
                <button type="button" onClick={onClick} className={shared}>
                    {inner}
                </button>
            ) : (
                <div className={shared}>{inner}</div>
            )}
        </li>
    );
}

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { cn } from "../cn";

export type TabItem<T extends string> = {
    value: T;
    label: ReactNode;
    /** A count beside the label: 142 runs, 3 keys. */
    count?: number;
    disabled?: boolean;
};

export type TabsProps<T extends string> = {
    items: TabItem<T>[];
    value: T;
    onChange: (value: T) => void;
    /** Names the set for screen readers, e.g. "Agent sections". */
    label: string;
    className?: string;
};

/**
 * Page-level sections. Keyboard behaviour is the ARIA pattern: ← → move and
 * activate, Home/End jump to the ends, and only the selected tab is in the
 * tab order, so Tab moves out of the set rather than through it.
 *
 * For two or three exclusive options inside a page, use SegmentedControl.
 */
export function Tabs<T extends string>({ items, value, onChange, label, className }: TabsProps<T>) {
    const id = useId();
    const listRef = useRef<HTMLDivElement | null>(null);
    const [ink, setInk] = useState({ left: 0, width: 0 });

    const measure = useCallback(() => {
        const el = listRef.current?.querySelector<HTMLElement>('[aria-selected="true"]');
        if (!el) return;
        setInk({ left: el.offsetLeft, width: el.offsetWidth });
        // M3 scrollable tabs: the selected one is always visible. The row
        // scrolls sideways on a phone, so selecting with ← → or landing on a
        // page whose tab is the fifth of six would otherwise leave the
        // indicator somewhere off the edge of the screen. `nearest` means a
        // tab already in view is not moved.
        // 🔴 Only the row scrolls, never the page: `scrollIntoView` also scrolls
        // the window, so a page with tabs far down opened at the tabs, not the
        // hero (/svg-generator, 2026-10-03).
        const list = listRef.current!;
        if (el.offsetLeft < list.scrollLeft) list.scrollLeft = el.offsetLeft;
        else if (el.offsetLeft + el.offsetWidth > list.scrollLeft + list.clientWidth) list.scrollLeft = el.offsetLeft + el.offsetWidth - list.clientWidth;
    }, []);

    useLayoutEffect(measure, [value, items, measure]);
    useEffect(() => {
        // Fonts land after first paint and shift the tabs under the indicator.
        document.fonts?.ready.then(measure).catch(() => {});
        window.addEventListener("resize", measure);
        return () => window.removeEventListener("resize", measure);
    }, [measure]);

    const move = (dir: 1 | -1 | "home" | "end") => {
        const usable = items.filter(i => !i.disabled);
        if (!usable.length) return;
        if (dir === "home") return onChange(usable[0].value);
        if (dir === "end") return onChange(usable[usable.length - 1].value);
        const at = usable.findIndex(i => i.value === value);
        onChange(usable[(at + dir + usable.length) % usable.length].value);
    };

    const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
        const keys: Record<string, () => void> = {
            ArrowRight: () => move(1),
            ArrowLeft: () => move(-1),
            Home: () => move("home"),
            End: () => move("end"),
        };
        const run = keys[e.key];
        if (run) {
            e.preventDefault();
            run();
            requestAnimationFrame(() => listRef.current?.querySelector<HTMLElement>('[aria-selected="true"]')?.focus());
        }
    };

    return (
        <div
            ref={listRef}
            role="tablist"
            aria-label={label}
            onKeyDown={onKeyDown}
            className={cn("relative flex min-w-0 gap-1 overflow-x-auto", className)}
        >
            {items.map(item => {
                const selected = item.value === value;
                return (
                    <button
                        key={item.value}
                        type="button"
                        role="tab"
                        id={`${id}-${item.value}`}
                        aria-selected={selected}
                        aria-controls={`${id}-${item.value}-panel`}
                        tabIndex={selected ? 0 : -1}
                        disabled={item.disabled}
                        onClick={() => onChange(item.value)}
                        className={cn(
                            "flex h-11 shrink-0 items-center gap-2 whitespace-nowrap px-3 text-label-lg",
                            "m3-state transition-colors duration-short2 ease-standard",
                            "focus-visible:outline focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-primary",
                            selected ? "text-on-surface" : "text-on-surface-variant hover:text-on-surface",
                            item.disabled && "pointer-events-none text-on-surface/[0.38]",
                        )}
                    >
                        {item.label}
                        {item.count !== undefined ? (
                            <span className={cn("rounded-extra-small px-1.5 text-label-sm tnum", selected ? "bg-surface-container-highest text-on-surface" : "bg-surface-container text-on-surface-variant")}>
                                {item.count.toLocaleString()}
                            </span>
                        ) : null}
                    </button>
                );
            })}
            {/* The underline slides between tabs instead of blinking to the next one. */}
            <span
                aria-hidden
                className="absolute bottom-0 h-0.5 rounded-full bg-on-surface transition-[translate,width] duration-spring-spatial ease-spring-spatial"
                style={{ width: ink.width, translate: `${ink.left}px 0` }}
            />
        </div>
    );
}

export type TabPanelProps = {
    children: ReactNode;
    /**
     * Render every panel and hide the inactive ones instead of rendering only
     * the selected one. For a page whose tab content has to be indexable: a
     * crawler runs no clicks, so a panel that only exists after one does not
     * exist at all. Costs the weight of all panels on first paint, so it is
     * opt-in and not the default.
     */
    hidden?: boolean;
    className?: string;
};

/** The content for the selected tab. Render only the selected one, unless `hidden` says otherwise. */
export function TabPanel({ children, hidden, className }: TabPanelProps) {
    return (
        // The `hidden` class too: a caller's `flex`/`grid` class would otherwise beat the attribute and show every panel.
        <div role="tabpanel" tabIndex={0} hidden={hidden} className={cn("focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary", className, hidden && "hidden")}>
            {children}
        </div>
    );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AlertTriangle, Check, Info, X, XCircle } from "@/ui/symbols";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { Spinner } from "../primitives/Progress";
import { interactive } from "../state-layer";

/**
 * M3 snackbar — https://m3.material.io/components/snackbar
 *
 * One brief message about something that just happened, at the foot of the
 * screen, on the prompt bar's own surface (owner, 2026-09-30: the inverse
 * surface was a white slab in dark mode). No tone colours: the same
 * surface every time, and the WORDS say whether it went well (§2.1 — colour
 * alone never carries meaning). The icon is there for scanning, not for
 * meaning.
 *
 * Use an `Alert` instead for a condition that persists, and a `Dialog` for
 * anything that needs a decision. A snackbar can be missed, so it is never
 * the only way to learn something.
 *
 * 🔴 The ONE notification on the site (owner, 2026-09-29): every page and
 * studio calls `toast()` from `@/ui` — no Sonner, no top-bar status chips.
 * Something still running ("Drawing 14 traits") is a snackbar with
 * `progress`: it stays, updates in place through `updateToast()`, and the ✕
 * closes it. The only other notice is the download card, top right.
 *
 * Shape (recorded per law §2.3): `extra-small`.
 */

export type ToastTone = "success" | "danger" | "warning" | "info";

export type ToastInput = {
    /** What happened, in the past tense: "Published", "Payment failed". */
    title: ReactNode;
    /** Optional detail, or what to do next when something failed. */
    description?: ReactNode;
    tone?: ToastTone;
    /** One button. Undo, Retry, View — never the only way to do the thing. */
    action?: { label: string; onClick: () => void };
    /** Milliseconds on screen. 0 keeps it until dismissed; use it for errors. */
    duration?: number;
    /**
     * Something still running. Shows a spinner (and a bar when `total` is
     * known) and stays until it is updated, dismissed or closed with ✕.
     */
    progress?: { done?: number; total?: number };
};

type ToastItem = ToastInput & { id: number };

/*
 * A tiny store instead of a context provider: `toast()` can then be called
 * from an event handler, a server-action result or a hook, without every
 * caller being inside a provider tree.
 */
let items: ToastItem[] = [];
let nextId = 1;
const listeners = new Set<(items: ToastItem[]) => void>();
const emit = () => listeners.forEach(l => l(items));

/**
 * 🔴 Nothing mounted `<Snackbar>` outside /design-system, so every `toast()`
 * on the site went nowhere - saves, errors and Undo all silent (found
 * 2026-09-27). The root layout is off limits (PERFORMANCE_RULES.md rule 2), so
 * the first `toast()` mounts one itself, into its own node on <body>. A page
 * that never shows a snackbar pays nothing; `react-dom/client` is already in
 * every page's framework chunk.
 */
let selfMounted = false;
function ensureMounted() {
    if (selfMounted || listeners.size > 0 || typeof document === "undefined") return;
    selfMounted = true;
    void import("react-dom/client").then(({ createRoot }) => {
        const host = document.createElement("div");
        host.setAttribute("data-snackbar-host", "");
        document.body.appendChild(host);
        createRoot(host).render(<Snackbar />);
    });
}

/** Show a snackbar. Returns its id so it can be updated or dismissed early. */
export function toast(input: ToastInput) {
    ensureMounted();
    const item = { ...input, id: nextId++ };
    /* M3 shows one snackbar at a time. Three is already a log, and nobody
       reads a log that is covering the thing they are working on. Something
       still running is dropped last - it is the one that says "not done". */
    items = [...items, item];
    while (items.length > 3) {
        const old = items.findIndex(t => !t.progress);
        items = items.filter((_, i) => i !== (old === -1 ? 0 : old));
    }
    emit();
    return item.id;
}

/** Change a snackbar in place: new words, new count, or "done". False if it is gone. */
export function updateToast(id: number, patch: Partial<ToastInput>) {
    if (!items.some(t => t.id === id)) return false;
    items = items.map(t => (t.id === id ? { ...t, ...patch, id } : t));
    emit();
    return true;
}

export function dismissToast(id?: number) {
    items = id === undefined ? [] : items.filter(t => t.id !== id);
    emit();
}

type Short = Omit<ToastInput, "title" | "tone"> & {
    /** Replace this snackbar instead of adding one (a "Sending…" turning into "Sent"). */
    id?: number;
};
const short = (tone: ToastTone | undefined, extra?: Partial<ToastInput>) => (title: ReactNode, o: Short = {}) => {
    const { id, ...rest } = o;
    /* A settled message replaces a running one: drop the spinner and restart
       the clock (`duration` undefined = the tone's default). */
    const next: ToastInput = { progress: undefined, duration: undefined, ...extra, ...rest, title, tone };
    if (id !== undefined && updateToast(id, next)) return id;
    return toast(next);
};
/** `toast.success("Saved")` and friends — the short form most call sites need. */
toast.success = short("success");
toast.error = short("danger");
toast.warning = short("warning");
toast.info = short("info");
/** A spinner that stays until the same id gets `toast.success/error(…, { id })`. */
toast.loading = short("info", { progress: {} });
toast.dismiss = dismissToast;

const ICON: Record<ToastTone, IconGlyph> = {
    success: Check,
    danger: XCircle,
    warning: AlertTriangle,
    info: Info,
};

/**
 * Where snackbars appear. `toast()` mounts one on first use; mounting it
 * yourself (as /design-system does) is fine too - the first one wins.
 *
 * Bottom-centre on a phone (M3's position), bottom-left on wide windows so it
 * does not cover a FAB. Errors stay until dismissed; everything else leaves on
 * its own, and hovering pauses the clock.
 */
export function Snackbar() {
    const [list, setList] = useState<ToastItem[]>(items);
    useEffect(() => {
        listeners.add(setList);
        return () => {
            listeners.delete(setList);
        };
    }, []);

    return (
        <div
            aria-live="polite"
            aria-relevant="additions text"
            className={cn(
                "pointer-events-none fixed z-snackbar flex flex-col gap-2",
                /* Above a studio's prompt bar when there is one (ComposerDock
                   sets --ui-composer-h), so a running job never covers it. */
                "inset-x-2 bottom-[calc(max(env(safe-area-inset-bottom,0px),var(--ui-composer-h,0px))+0.5rem)]",
                "medium:inset-x-auto medium:bottom-[calc(var(--ui-composer-h,0px)+1.5rem)] medium:left-6 medium:w-[20rem]",
                /* With the side rail: just above the profile row, bottom left. `!` because
                   Tailwind emits the legacy `md` rules before `medium`. */
                "md:!bottom-[5.5rem] md:!left-3",
            )}
        >
            {list.map(t => (
                <SnackbarRow key={t.id} item={t} />
            ))}
        </div>
    );
}

/** The old name. Kept so a half-migrated layout still mounts it. */
export const Toaster = Snackbar;

function SnackbarRow({ item }: { item: ToastItem }) {
    const glyph = ICON[item.tone ?? "success"];
    const running = !!item.progress;
    const ms = running ? 0 : item.duration ?? (item.tone === "danger" ? 0 : 5000);
    const { done, total } = item.progress ?? {};
    const pct = total ? Math.max(0, Math.min(100, ((done ?? 0) / total) * 100)) : undefined;
    const [leaving, setLeaving] = useState(false);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

    const close = () => {
        setLeaving(true);
        setTimeout(() => dismissToast(item.id), 400);
    };

    const start = () => {
        if (!ms) return;
        timer.current = setTimeout(close, ms);
    };
    const stop = () => {
        if (timer.current) clearTimeout(timer.current);
    };

    /* Restarts when the snackbar changes: a running one that turns into
       "done" starts its clock then, not when it first appeared. */
    useEffect(() => {
        start();
        return stop;
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ms, item.title]);

    return (
        <div
            role={item.tone === "danger" ? "alert" : "status"}
            data-leaving={leaving || undefined}
            onPointerEnter={stop}
            onPointerLeave={start}
            className={cn(
                "m3-snackbar pointer-events-auto flex items-start gap-2.5 rounded-small px-3 py-2.5 text-on-surface",
                "bg-surface-container-lowest shadow-level-2 dark:bg-surface-container-high dark:shadow-none",
            )}
        >
            {running ? <Spinner size="sm" className="mt-0.5" /> : <Icon icon={glyph} size="sm" className="mt-0.5 shrink-0 text-on-surface-variant" />}
            <div className="min-w-0 flex-1">
                <p className="text-body-sm">
                    {item.title}
                    {total ? <span className="tabular-nums opacity-80"> · {(done ?? 0).toLocaleString()} / {total.toLocaleString()}</span> : null}
                </p>
                {item.description ? <p className="mt-0.5 text-body-sm text-on-surface-variant">{item.description}</p> : null}
                {pct !== undefined ? (
                    <div
                        role="progressbar"
                        aria-valuemin={0}
                        aria-valuemax={100}
                        aria-valuenow={Math.round(pct)}
                        aria-label={typeof item.title === "string" ? item.title : "Progress"}
                        className="mt-2 h-1 overflow-hidden rounded-full bg-on-surface/10"
                    >
                        <div className="h-full rounded-full bg-primary transition-[width] duration-medium2" style={{ width: `${pct}%` }} />
                    </div>
                ) : null}
            </div>
            {item.action ? (
                <button
                    type="button"
                    onClick={() => {
                        item.action?.onClick();
                        // "View" on something still running leaves it on screen.
                        if (!running) close();
                    }}
                    className={cn(
                        "-my-1 shrink-0 rounded-extra-small px-2 py-1 text-label-lg text-primary",
                        interactive(),
                    )}
                >
                    {item.action.label}
                </button>
            ) : null}
            <button
                type="button"
                onClick={close}
                aria-label="Dismiss"
                className={cn(
                    "-my-1 -mr-1 inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full",
                    "before:absolute before:left-1/2 before:top-1/2 before:h-touch before:w-touch before:-translate-x-1/2 before:-translate-y-1/2 before:content-['']",
                    "text-on-surface-variant",
                    interactive(),
                )}
            >
                <Icon icon={X} size="sm" />
            </button>
        </div>
    );
}

"use client";

import type { IconGlyph } from "../primitives/Icon";
import { MoreVertical } from "@/ui/symbols";
import { cn } from "../cn";
import { Button, IconButton, type ButtonSize } from "../primitives/Button";
import { Menu, MenuItem } from "./Menu";
import { Tooltip } from "./Tooltip";
import { useWindowClass } from "./position";

/**
 * Top actions that fold on a phone
 *
 * The collection page used to show three big filled buttons in a row on a
 * phone and they overflowed. M3's rule is one filled button per screen, and
 * a page should not have to work out its own breakpoint to honour it — so
 * this decides what fits, from a `priority` each item declares:
 *
 *   primary    the one filled button. Only the first is ever rendered filled.
 *   secondary  the next most useful action — tonal on a wide screen.
 *   overflow   everything else — an icon button with a tooltip when there's
 *              room, folded into the phone's ⋮ menu when there isn't.
 *   menu       always behind ⋮, on every screen. For a page whose bar has
 *              no room for a row of icons (the collection studio's one bar).
 *
 * Phone: primary only - as a filled ICON (owner, 2026-09-26: the studio bar
 * is icons only, the room goes to the grid) - everything else behind ⋮. Tablet: primary filled,
 * secondary tonal, the rest behind ⋮. Laptop and up: primary filled,
 * secondary tonal, the rest as icon buttons — nothing hidden.
 */
export type ToolbarAction = {
    key: string;
    label: string;
    icon: IconGlyph;
    onClick: () => void;
    priority: "primary" | "secondary" | "overflow" | "menu";
    disabled?: boolean;
};

export type ToolbarProps = {
    /** Names the menu for screen readers when it folds on a phone, e.g. "Collection actions". */
    label: string;
    actions: ToolbarAction[];
    /** The labelled buttons' height. `xs` for a bar that should not shout. */
    size?: ButtonSize;
    className?: string;
};

export function Toolbar({ label, actions, size, className }: ToolbarProps) {
    const w = useWindowClass();
    const compact = w === "compact";
    /* A tablet (600-839) fits the filled and the tonal buttons, not a row of
       icon buttons as well - that is where the row overflowed. */
    const folds = compact || w === "medium";

    const primary = actions.find(a => a.priority === "primary");
    const rest = actions.filter(a => a !== primary);
    const secondary = compact ? [] : rest.filter(a => a.priority === "secondary");
    const inMenu = rest.filter(a => a.priority === "menu" || (folds && !secondary.includes(a)));
    const asIcons = folds ? [] : rest.filter(a => a.priority === "overflow");

    return (
        <div className={cn("flex min-w-0 items-center gap-2", className)}>
            {primary && (compact ? (
                <Tooltip content={primary.label}>
                    <IconButton icon={primary.icon} label={primary.label} variant="filled" onClick={primary.onClick} disabled={primary.disabled} />
                </Tooltip>
            ) : (
                <Button icon={primary.icon} size={size} onClick={primary.onClick} disabled={primary.disabled}>
                    {primary.label}
                </Button>
            ))}
            {secondary.map(a => (
                <Button key={a.key} icon={a.icon} size={size} variant="tonal" onClick={a.onClick} disabled={a.disabled} className="shrink-0">
                    {a.label}
                </Button>
            ))}
            {asIcons.map(a => (
                <Tooltip key={a.key} content={a.label}>
                    <IconButton icon={a.icon} label={a.label} onClick={a.onClick} disabled={a.disabled} />
                </Tooltip>
            ))}
            {inMenu.length > 0 && (
                <Menu label={label} placement="bottom-end" trigger={p => <IconButton {...p} icon={MoreVertical} label={label} />}>
                    {inMenu.map(a => (
                        <MenuItem key={a.key} icon={a.icon} onSelect={a.onClick} disabled={a.disabled}>
                            {a.label}
                        </MenuItem>
                    ))}
                </Menu>
            )}
        </div>
    );
}

"use client";

import { cloneElement, useCallback, useEffect, useId, useRef, useState, type PointerEvent as ReactPointerEvent, type ReactElement, type ReactNode } from "react";
import { cn } from "../cn";
import { place, type Placement } from "./position";

export type TooltipProps = {
    /** The word or two the tooltip says. Never the only place that meaning exists. */
    content: ReactNode;
    /** One element that receives the hover, focus and aria wiring. */
    children: ReactElement;
    placement?: Placement;
    /** Wait before showing, so a cursor crossing a toolbar does not flash six tips. */
    delay?: number;
    className?: string;
};

/** A touch has to rest this long before it counts as "tell me about this". */
const LONG_PRESS_MS = 400;

/**
 * A hint on hover, long-press or keyboard focus.
 *
 * Rules that keep it honest: it never holds information that exists nowhere
 * else, it never contains a control (it is not focusable), and an icon-only
 * button keeps its own `aria-label` - the tooltip describes, it does not name.
 *
 * 🔴 TOUCH GETS IT TOO. A pointer-enter-only tooltip is missing on every
 * phone, and `pointerenter` fires on a tap, so a touch used to flash the tip
 * for the length of the tap and then lose it. A touch opens the tip by
 * resting; a lift, a scroll or a second tap closes it. The tip itself is
 * `pointer-events-none`, so it can never swallow the tap underneath.
 */
export function Tooltip({ content, children, placement = "top", delay = 500, className }: TooltipProps) {
    const id = `tip-${useId()}`;
    const anchor = useRef<HTMLElement | null>(null);
    const tip = useRef<HTMLDivElement | null>(null);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [open, setOpen] = useState(false);

    const show = useCallback(
        (immediate = false) => {
            if (timer.current) clearTimeout(timer.current);
            timer.current = setTimeout(
                () => {
                    const el = tip.current;
                    if (!el || !anchor.current) return;
                    el.showPopover();
                    place(anchor.current, el, placement);
                    setOpen(true);
                },
                immediate ? 0 : delay,
            );
        },
        [delay, placement],
    );

    const hide = useCallback(() => {
        if (timer.current) clearTimeout(timer.current);
        tip.current?.hidePopover();
        setOpen(false);
    }, []);

    /** A finger held still on the element. A scroll cancels it. */
    const touchHold = useCallback(() => {
        if (timer.current) clearTimeout(timer.current);
        timer.current = setTimeout(() => {
            const el = tip.current;
            if (!el || !anchor.current) return;
            el.showPopover();
            place(anchor.current, el, placement);
            setOpen(true);
        }, LONG_PRESS_MS);
    }, [placement]);

    useEffect(() => {
        return () => {
            if (timer.current) clearTimeout(timer.current);
        };
    }, []);
    // Esc closes a tooltip too - the popover API only does that for `auto`.
    // So does a scroll: on a phone the tip is anchored to an element that is
    // moving away from it, and `manual` popovers never close themselves.
    useEffect(() => {
        if (!open) return;
        const onKey = (e: KeyboardEvent) => e.key === "Escape" && hide();
        document.addEventListener("keydown", onKey);
        window.addEventListener("scroll", hide, true);
        return () => {
            document.removeEventListener("keydown", onKey);
            window.removeEventListener("scroll", hide, true);
        };
    }, [open, hide]);

    const child = cloneElement(children, {
        ref: (node: HTMLElement | null) => {
            anchor.current = node;
            const r = (children as unknown as { ref?: unknown }).ref;
            if (typeof r === "function") (r as (n: HTMLElement | null) => void)(node);
            else if (r && typeof r === "object") (r as { current: HTMLElement | null }).current = node;
        },
        "aria-describedby": open ? id : undefined,
        // A mouse hovers; a finger rests. Same tip, two ways in.
        onPointerEnter: (e: ReactPointerEvent) => { if (e.pointerType !== "touch") show(); },
        onPointerLeave: (e: ReactPointerEvent) => { if (e.pointerType !== "touch") hide(); },
        onPointerDown: (e: ReactPointerEvent) => { if (e.pointerType === "touch") touchHold(); },
        onPointerUp: (e: ReactPointerEvent) => { if (e.pointerType === "touch") hide(); },
        onPointerCancel: hide,
        onFocus: () => show(true),
        onBlur: hide,
    } as Record<string, unknown>);

    return (
        <>
            {child}
            <div
                ref={tip}
                id={id}
                popover="manual"
                role="tooltip"
                className={cn(
                    "m3-pop m3-tip pointer-events-none max-w-[16rem] rounded-small border-0 bg-inverse-surface px-2 py-1 text-label-md text-inverse-on-surface shadow-level-3",
                    className,
                )}
            >
                {content}
            </div>
        </>
    );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { Button } from "../primitives/Button";
import { place, type Placement } from "./position";
import { usePersistedState } from "./usePersistedState";

/**
 * A first-run guide: one small card that sits next to the button it is talking
 * about and moves on as the work moves on (owner, 2026-10-01).
 *
 *   <Tour id="nft-studio" at={stepReached} steps={[{ key, title, body, target }]} />
 *
 * `at` is how far the person's own work has got (0 = nothing yet). The card
 * shows the furthest of that and the steps they pressed Next on, so it never
 * explains something they have already done. Skip hides it for good, on this
 * browser. Nothing is blocked: the page works the same with the card open.
 *
 * `target` returns the element to point at, or null while it is not on screen
 * (another tab, a popup open) - the card waits. A modal Sheet covers it by
 * itself: a dialog lives in the browser's top layer.
 */
export interface TourStep {
    key: string;
    title: string;
    body: ReactNode;
    target: () => Element | null;
    placement?: Placement;
}

/** The first visible button or tab whose words (or label) start with `text`. For `target`. */
export function tourTarget(text: string): Element | null {
    if (typeof document === "undefined") return null;
    for (const el of document.querySelectorAll<HTMLElement>("button, [role=tab]")) {
        // On a phone a button is often only its icon: its label still names it.
        if (el.offsetParent && [el.textContent, el.getAttribute("aria-label"), el.title].some((t) => (t || "").trim().startsWith(text))) return el;
    }
    return null;
}

export function Tour({ id, steps, at = 0 }: { id: string; steps: TourStep[]; at?: number }) {
    const [saved, setSaved] = usePersistedState<{ skip: boolean; passed: number }>(`tour:${id}`, { skip: false, passed: 0 });
    const card = useRef<HTMLDivElement>(null);
    const ring = useRef<HTMLDivElement>(null);
    const [shown, setShown] = useState(false);
    const index = Math.max(at, saved.passed);
    const step = saved.skip ? undefined : steps[index];

    useEffect(() => {
        if (!step) return;
        const tick = () => {
            const el = step.target() as HTMLElement | null;
            const ok = !!el && !!card.current && !document.querySelector("dialog[open]");
            setShown(ok);
            if (!ok) return;
            place(el!, card.current!, step.placement ?? "bottom", 12);
            const r = el!.getBoundingClientRect();
            Object.assign(ring.current!.style, { left: `${r.left - 4}px`, top: `${r.top - 4}px`, width: `${r.width + 8}px`, height: `${r.height + 8}px` });
        };
        tick();
        // ponytail: a 400 ms look instead of observers. Targets come and go with tabs,
        // popups and scrolling; one cheap measure covers all of them.
        const t = setInterval(tick, 400);
        window.addEventListener("resize", tick);
        return () => { clearInterval(t); window.removeEventListener("resize", tick); };
    }, [step]);

    if (!step) return null;
    const last = index >= steps.length - 1;
    return (
        <>
            <div ref={ring} aria-hidden className={shown ? "pointer-events-none fixed z-tooltip rounded-large ring-2 ring-primary" : "hidden"} />
            <div
                ref={card}
                role="status"
                className={`fixed z-tooltip w-72 max-w-[calc(100vw-1rem)] rounded-large bg-inverse-surface p-4 text-inverse-on-surface shadow-level-3 ${shown ? "" : "invisible"}`}
            >
                <p className="text-label-md opacity-70">Step {index + 1} of {steps.length}</p>
                <p className="mt-1 text-title-md">{step.title}</p>
                <div className="mt-1 text-body-md">{step.body}</div>
                <div className="mt-3 flex items-center justify-between gap-2">
                    <Button variant="text" size="xs" className="text-inverse-on-surface" onClick={() => setSaved({ skip: true, passed: index })}>Skip</Button>
                    <Button variant="tonal" size="xs" onClick={() => setSaved(last ? { skip: true, passed: index } : { skip: false, passed: index + 1 })}>
                        {last ? "Done" : "Next"}
                    </Button>
                </div>
            </div>
        </>
    );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from "react";
import { X } from "@/ui/symbols";
import { cn } from "../cn";
import { IconButton } from "../primitives/Button";
import { useMediaQuery } from "./position";

/*
 * 🔴 A modal <dialog> sits in the browser's top layer, above every z-index,
 * and makes the rest of the page inert. The toast area lives in <body>, so
 * a toast fired while a Sheet is open ("Couldn't download", "Undo") landed
 * BEHIND it, unseen and unclickable. While any Sheet is open, the toast area
 * joins the top layer too, above the newest Sheet.
 */
const TOASTS = 'section[aria-label^="Notifications"]';
export function liftToasts() {
    // The download card (Download.tsx) is its own top-layer popover: move it above this Sheet too.
    const d = document.querySelector<HTMLElement>("[data-download-layer]");
    if (d?.matches(":popover-open")) { d.hidePopover(); d.showPopover(); }
    const t = document.querySelector<HTMLElement>(TOASTS);
    if (!t) return;
    if (!t.hasAttribute("popover")) t.setAttribute("popover", "manual");
    t.classList.add("m3-toast-layer");
    // Re-showing moves it to the top of the top layer, above this Sheet.
    if (t.matches(":popover-open")) t.hidePopover();
    t.showPopover();
}
export function dropToasts() {
    const t = document.querySelector<HTMLElement>(TOASTS);
    if (!t || document.querySelector("dialog[open]")) return;
    if (t.matches(":popover-open")) t.hidePopover();
    t.removeAttribute("popover");
    t.classList.remove("m3-toast-layer");
}

/*
 * 🔴 The page behind a popup must not scroll. Each popup used to remember
 * `body.overflow` on open and put it back on close; with one popup opened from
 * another (wallet popup over Settings) and the PARENT closing first, the child
 * restored a stale "hidden" and the page stayed frozen. Count the open popups
 * instead: the first locks, the last unlocks.
 */
let scrollLocks = 0;
let scrollBefore = "";
export function lockPageScroll() {
    if (scrollLocks++ === 0) {
        scrollBefore = document.body.style.overflow;
        document.body.style.overflow = "hidden";
    }
    return () => {
        if (--scrollLocks === 0) document.body.style.overflow = scrollBefore;
    };
}

export type WindowProps = {
    open: boolean;
    onClose: () => void;
    /** Names the window. Screen readers only, unless `showTitle` (editors draw their own). */
    title: ReactNode;
    /** Draws the title (and `description`) at the top of the scrolling content. No bar, no line. */
    showTitle?: boolean;
    /** One line under the title saying what this decides. Needs `showTitle`. */
    description?: ReactNode;
    /** Hides the ✕. Only for a decision that must be made (then give it buttons). */
    hideClose?: boolean;
    /**
     * Same 3:2 shape at every size.
     * `lg` nearly fills a desktop screen; `md` 75%, `sm` 60%, `xs` 40% (a question).
     * On a phone `lg`, `md` and `sm` are nearly the whole screen, a strip of
     * the page showing on top; `xs` stays a small card.
     * `tall` is the one exception to 3:2: a portrait card (27 rem wide, up to
     * 46 rem high) for a list that wants height, like the wallet picker.
     */
    /** `fit`: a narrow card exactly as tall as what is in it - a form like sign-in. */
    size?: "lg" | "md" | "sm" | "xs" | "tall" | "fit";
    /** Left pane: a picture, SVG, animation, a live preview. On a phone it becomes a strip on top. */
    stage?: ReactNode;
    /** On a phone: `strip` (default) a short fixed strip on top; `flow` the stage at its natural height, scrolling with the content. */
    stagePhone?: "strip" | "flow";
    /** Buttons for the top-right of the content. No bar, no line: they sit on the same surface. */
    actions?: ReactNode;
    /** Pinned bottom buttons (primary last). Same surface, no line. Leave out when the window has none. */
    footer?: ReactNode;
    /** Content edge to edge, not scrolling: an editor that owns its own canvas. */
    flush?: boolean;
    className?: string;
    children?: ReactNode;
};

/**
 * The one big popup. Every dialog, wizard and editor in AMNT is this.
 *
 * - One shape: 3:2, centred. It never grows or shrinks with its content;
 *   only the content scrolls, inside it. A step that is short stays in the
 *   same box as a step that is long.
 * - No header, no footer bar, no lines: one surface. The ✕ sits outside the
 *   top-right corner, on the dimmed page (a phone has no outside: it sits in
 *   the top strip, beside the grab handle).
 * - Phone: nearly full screen, sliding up, a strip of the page left on top;
 *   pull the handle down to close.
 *
 * Built on `<dialog showModal()>`, like Sheet: top layer, focus trap, Esc and
 * `inert` page for free. Geometry lives in ui.css (`.m3-window`).
 */
/** How far down you have to pull a phone's window before letting go closes it. */
const DRAG_CLOSE_PX = 96;

export function Window({ open, onClose, title, showTitle, description, hideClose, size = "lg", stage, stagePhone = "strip", actions, footer, flush, className, children }: WindowProps) {
    const ref = useRef<HTMLDialogElement | null>(null);
    const titleId = `window-${useId()}`;
    /* Under 840 px, or a phone turned sideways, there is no room for a big
       window with a ✕ beside it: it becomes the whole screen. */
    const compact = useMediaQuery("(max-width: 839px), (max-height: 520px)");
    const card = size === "xs";
    const full = compact && !card;
    const flowStage = compact && stagePhone === "flow";

    /* Pull the top of a phone's window down to close it: only the handle
       drags, so a scrolling body never fights the gesture, and only downwards. */
    const [drag, setDrag] = useState(0);
    const dragFrom = useRef<number | null>(null);
    const onDragStart = useCallback((e: React.PointerEvent) => {
        if (e.pointerType === "mouse" || (e.target as HTMLElement).closest("button")) return;
        e.currentTarget.setPointerCapture(e.pointerId);
        dragFrom.current = e.clientY;
    }, []);
    const onDragMove = useCallback((e: React.PointerEvent) => {
        if (dragFrom.current !== null) setDrag(Math.max(0, e.clientY - dragFrom.current));
    }, []);
    const onDragEnd = useCallback(() => {
        if (dragFrom.current === null) return;
        dragFrom.current = null;
        const travelled = drag;
        setDrag(0);
        if (travelled > DRAG_CLOSE_PX) onClose();
    }, [drag, onClose]);

    useEffect(() => {
        const el = ref.current;
        if (!el) return;
        if (open && !el.open) {
            el.showModal();
            liftToasts();
        }
        if (!open && el.open) {
            el.close();
            dropToasts();
        }
        if (!open) {
            dragFrom.current = null;
            setDrag(0);
        }
    }, [open]);
    useEffect(() => () => { if (ref.current?.open) { ref.current.close(); dropToasts(); } }, []);

    // The page behind must not scroll under the window, on iOS especially.
    useEffect(() => (open ? lockPageScroll() : undefined), [open]);

    return (
        <dialog
            ref={ref}
            data-placement={full ? "bottom" : "center"}
            data-size={size}
            data-full={full || undefined}
            aria-labelledby={titleId}
            onCancel={e => {
                // Esc: the parent owns `open`, the DOM does not close behind its back.
                e.preventDefault();
                onClose();
            }}
            onClick={e => {
                if (e.target === ref.current) onClose();
            }}
            className="m3-sheet m3-window"
            /* While a finger is down the window follows it exactly. */
            style={drag ? { translate: `0 ${drag}px`, transition: "none" } : undefined}
        >
            {showTitle ? null : <h2 id={titleId} className="sr-only">{title}</h2>}
            <div className={cn("flex h-full overflow-hidden bg-surface-container-lowest text-on-surface shadow-level-4 dark:bg-surface-container", full ? "flex-col rounded-t-extra-large" : "rounded-extra-large", compact && !full && "flex-col")}>
                {full ? (
                    /* The phone's top strip: the grab handle in the middle, the ✕ at
                       the right, so the ✕ never sits on top of the content's own bar. */
                    <div
                        className="relative grid h-10 shrink-0 touch-none place-items-center"
                        onPointerDown={onDragStart}
                        onPointerMove={onDragMove}
                        onPointerUp={onDragEnd}
                        onPointerCancel={onDragEnd}
                    >
                        <span aria-hidden className="h-1 w-8 rounded-full bg-on-surface-variant/[0.4]" />
                        {hideClose ? null : <IconButton icon={X} label="Close" size="sm" onClick={onClose} className="absolute right-2 top-1" />}
                    </div>
                ) : null}
                {stage && !flowStage ? (
                    <div className={cn("m-3 shrink-0 overflow-hidden rounded-large bg-surface-container", compact ? "mx-4 mt-1 h-40" : "w-[40%]")}>
                        {stage}
                    </div>
                ) : null}
                <div className={cn("flex min-h-0 min-w-0 flex-1 flex-col", className)}>
                    {actions ? (
                        <div className={cn("flex shrink-0 items-center justify-end gap-2 px-6 pt-5", full && "pt-1")}>{actions}</div>
                    ) : null}
                    <div
                        className={cn(
                            "min-h-0 flex-1",
                            flush ? "flex flex-col overflow-hidden" : "overflow-y-auto overscroll-contain px-6 py-5",
                            full && !flush && "pt-2",
                        )}
                    >
                        {showTitle ? (
                            <div className="mb-4">
                                <h2 id={titleId} className="text-headline-sm text-on-surface">{title}</h2>
                                {description ? <p className="mt-1 text-body-md text-on-surface-variant">{description}</p> : null}
                            </div>
                        ) : null}
                        {stage && flowStage ? <div className="mb-4 overflow-hidden rounded-large bg-surface-container">{stage}</div> : null}
                        {children}
                    </div>
                    {footer ? (
                        <>
                            {/* No line: the content fades out under the buttons instead. */}
                            <div aria-hidden className="-mt-6 h-6 shrink-0 bg-gradient-to-t from-surface-container-high to-transparent" />
                            <div className="flex shrink-0 flex-wrap justify-end gap-2 px-6 pb-[max(1.25rem,env(safe-area-inset-bottom))]">{footer}</div>
                        </>
                    ) : null}
                </div>
            </div>
            {/* Outside the corner on a desktop (Canva), inside it on a phone. */}
            {hideClose || full ? null : (
                <IconButton icon={X} label="Close" variant="tonal" onClick={onClose} className="absolute left-full top-0 ml-3 shadow-level-2" />
            )}
        </dialog>
    );
}

"use client";

import { useCallback, useEffect, useState } from "react";

export type Placement = "bottom-start" | "bottom-end" | "top-start" | "top-end" | "bottom" | "top" | "right-start";

/**
 * Places a floating element next to its anchor, flipping when it would run off
 * the bottom and sliding when it would run off the side. Deliberately small:
 * CSS anchor positioning will replace it once Safari and Firefox ship it, and
 * a positioning library is a dependency we do not need for a menu.
 */
export function place(anchor: HTMLElement, floater: HTMLElement, placement: Placement = "bottom-start", offset = 6) {
    const a = anchor.getBoundingClientRect();
    const w = floater.offsetWidth;
    const h = floater.offsetHeight;
    const margin = 8;
    /* Beside the anchor (a sidebar row's menu), falling back below it when
       there is no room on the right — a phone. */
    if (placement === "right-start" && a.right + offset + w + margin <= window.innerWidth) {
        const top = Math.min(Math.max(margin, a.top), Math.max(margin, window.innerHeight - h - margin));
        floater.style.position = "fixed";
        floater.style.left = `${Math.round(a.right + offset)}px`;
        floater.style.top = `${Math.round(top)}px`;
        floater.style.setProperty("--m3-pop-origin", "top left");
        return;
    }
    const wantsTop = placement.startsWith("top");
    const roomBelow = window.innerHeight - a.bottom;
    const roomAbove = a.top;
    const onTop = wantsTop ? roomAbove > h + offset + margin || roomAbove > roomBelow : roomBelow < h + offset + margin && roomAbove > roomBelow;

    let left: number;
    if (placement.endsWith("-end")) left = a.right - w;
    else if (placement === "bottom" || placement === "top") left = a.left + a.width / 2 - w / 2;
    else left = a.left;
    left = Math.min(Math.max(margin, left), Math.max(margin, window.innerWidth - w - margin));

    // Never off the screen: a tall panel (the colour picker) near the bottom slides up instead of hanging off.
    const top = Math.min(Math.max(margin, onTop ? a.top - h - offset : a.bottom + offset), Math.max(margin, window.innerHeight - h - margin));

    floater.style.position = "fixed";
    floater.style.left = `${Math.round(left)}px`;
    floater.style.top = `${Math.round(top)}px`;
    floater.style.setProperty("--m3-pop-origin", `${onTop ? "bottom" : "top"} ${left + w / 2 < a.left + a.width / 2 ? "left" : "right"}`);
}

/** Keeps a floating element glued to its anchor while it is open. */
export function useAnchoredPosition(
    anchor: React.RefObject<HTMLElement>,
    floater: React.RefObject<HTMLElement>,
    open: boolean,
    placement: Placement = "bottom-start",
) {
    const reposition = useCallback(() => {
        if (anchor.current && floater.current) place(anchor.current, floater.current, placement);
    }, [anchor, floater, placement]);

    useEffect(() => {
        if (!open) return;
        reposition();
        // `true` catches scrolling inside any ancestor, not just the window.
        window.addEventListener("scroll", reposition, true);
        window.addEventListener("resize", reposition);
        return () => {
            window.removeEventListener("scroll", reposition, true);
            window.removeEventListener("resize", reposition);
        };
    }, [open, reposition]);

    return reposition;
}

/** True when the viewport matches, kept in sync. SSR-safe: false first. */
export function useMediaQuery(query: string) {
    const [matches, setMatches] = useState(false);
    useEffect(() => {
        const mq = window.matchMedia(query);
        setMatches(mq.matches);
        const onChange = (e: MediaQueryListEvent) => setMatches(e.matches);
        mq.addEventListener("change", onChange);
        return () => mq.removeEventListener("change", onChange);
    }, [query, setMatches]);
    return matches;
}

/* ── M3 window size classes ───────────────────────────────────────────── */

export type WindowClass = "compact" | "medium" | "expanded" | "large" | "xlarge";

/**
 * Which M3 window size class the viewport is in (§2.6). This is what a layout
 * asks before it chooses a navigation bar, a rail or a drawer.
 *
 * SSR-safe: "compact" first, because phone first means the phone layout is
 * what the server renders and what a slow client paints.
 */
export function useWindowClass(): WindowClass {
    const xlarge = useMediaQuery("(min-width: 1600px)");
    const large = useMediaQuery("(min-width: 1200px)");
    const expanded = useMediaQuery("(min-width: 840px)");
    const medium = useMediaQuery("(min-width: 600px)");
    if (xlarge) return "xlarge";
    if (large) return "large";
    if (expanded) return "expanded";
    if (medium) return "medium";
    return "compact";
}

"use client";

import { useEffect, useRef, useState, type Dispatch, type SetStateAction } from "react";

/**
 * A prompt bar never forgets (owner, 2026-09-26): its words and every
 * setting on it survive a refresh. This is the one way a bar remembers.
 *
 * Kept in `localStorage` under `amnt-bar:<key>`. SSR-safe: the first render
 * is `initial` on the server and in the browser alike (no hydration
 * mismatch), then the saved value lands in an effect. Nothing is written
 * until that read has happened, so the default never overwrites what was
 * saved. Blocked storage (private mode, quota) simply means it forgets.
 *
 * `ok` rejects a saved value that no longer makes sense - a model that was
 * retired, a mode that was renamed - so an old save can never send a bad id.
 */
export const PERSIST_PREFIX = "ship-bar:";

export function readPersisted(key: string): unknown {
    try {
        const raw = localStorage.getItem(PERSIST_PREFIX + key);
        return raw === null ? undefined : JSON.parse(raw);
    } catch {
        return undefined;
    }
}

export function writePersisted(key: string, value: unknown) {
    try {
        localStorage.setItem(PERSIST_PREFIX + key, JSON.stringify(value));
    } catch {
        /* storage blocked or full: this bar just forgets */
    }
}

export function usePersistedState<T>(
    key: string | null | undefined,
    initial: T,
    ok?: (v: unknown) => boolean,
): [T, Dispatch<SetStateAction<T>>] {
    const [value, setValue] = useState<T>(initial);
    /** The key whose saved value has been read. Nothing is written before. */
    const loaded = useRef<string | null>(null);
    /** The pass that read it: its `value` is still the default, never saved. */
    const justLoaded = useRef(false);
    const okRef = useRef(ok);
    okRef.current = ok;

    useEffect(() => {
        if (!key) return;
        const saved = readPersisted(key);
        const valid = saved !== undefined && (okRef.current ? okRef.current(saved) : typeof saved === typeof initial);
        if (valid) setValue(saved as T);
        loaded.current = key;
        justLoaded.current = true;
        // `initial` is a first-render default, not a dependency.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [key]);

    useEffect(() => {
        if (!key || loaded.current !== key) return;
        if (justLoaded.current) { justLoaded.current = false; return; }
        writePersisted(key, value);
    }, [key, value]);

    return [value, setValue];
}

/**
 * For a bar whose words live somewhere else (a parent's state, a store):
 * puts the saved words back once, if the box is empty, then saves every
 * change. `Composer` runs this for its `persistKey` prop.
 */
export function usePersistedText(key: string | null | undefined, value: string, onChange: (v: string) => void) {
    const loaded = useRef<string | null>(null);
    const justLoaded = useRef(false);
    const change = useRef(onChange);
    change.current = onChange;

    useEffect(() => {
        if (!key) return;
        const saved = readPersisted(key);
        if (typeof saved === "string" && saved && !value) change.current(saved);
        loaded.current = key;
        justLoaded.current = true;
        // Only on a new key: restoring is a mount-time thing.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [key]);

    useEffect(() => {
        if (!key || loaded.current !== key) return;
        // The restoring pass: the box still shows the old words (or none),
        // and writing them now would erase what was just asked for.
        if (justLoaded.current) { justLoaded.current = false; return; }
        writePersisted(key, value);
    }, [key, value]);
}

