export type ShellLink = { href: string; label: string; icon?: IconGlyph; count?: number; exact?: boolean };
export type ShellGroup = { label?: string; items: ShellLink[] };

const on = (pathname: string, l: ShellLink) => (l.exact || l.href === "/" ? pathname === l.href : pathname === l.href || pathname.startsWith(`${l.href}/`));

/* ── Sidebar shell ────────────────────────────────────────────────────── */

export type SidebarShellProps = {
    pathname: string;
    /** Logo / product name at the top. */
    brand: ReactNode;
    /** Under the brand: a team switcher, a search button. */
    top?: ReactNode;
    groups: ShellGroup[];
    /** Pinned to the bottom: the profile menu, a usage meter, "Upgrade". */
    footer?: ReactNode;
    /** Right side of the page's top bar: the bell, the ⌘K button, page actions. */
    actions?: ReactNode;
    /** The page title in the top bar. */
    title?: ReactNode;
    children: ReactNode;
    /** Remembers collapsed/open under this key. */
    storageKey?: string;
    /** The shell's own words, for a site in another language. */
    labels?: Partial<typeof SHELL_LABELS>;
};

export const SHELL_LABELS = { open: "Open menu", close: "Close menu", fold: "Fold the sidebar", unfold: "Open the sidebar", main: "Main" };

/**
 * The app frame most SaaS products use: a sidebar of sections on the left, a
 * slim bar above the page. Wide screens: the sidebar stays and folds down to
 * icons (remembered). Phones and tablets: the sidebar slides in from the left
 * over the page, and closes on a pick, Esc or a tap outside.
 *
 * Layout is CSS breakpoints, not JS, so the server sends the right shape and
 * nothing jumps when the page wakes up.
 */
export function SidebarShell({ pathname, brand, top, groups, footer, actions, title, children, storageKey = "shell-sidebar", labels }: SidebarShellProps) {
    const L = { ...SHELL_LABELS, ...labels };
    const [folded, setFolded] = usePersistedState<boolean>(storageKey, false, (v) => typeof v === "boolean");
    const [drawer, setDrawer] = useState(false);
    useEffect(() => setDrawer(false), [pathname]);
    useEffect(() => {
        if (!drawer) return;
        const esc = (e: KeyboardEvent) => e.key === "Escape" && setDrawer(false);
        window.addEventListener("keydown", esc);
        return () => window.removeEventListener("keydown", esc);
    }, [drawer]);

    const nav = (mini: boolean) => (
        <nav aria-label={L.main} className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-3 py-2">
            {groups.map((g, gi) => (
                <div key={g.label ?? gi} className="flex flex-col gap-0.5">
                    {g.label && !mini ? <p className="px-3 pb-1 pt-2 text-label-sm uppercase tracking-[0.14em] text-on-surface-variant">{g.label}</p> : null}
                    {g.items.map((l) => {
                        const here = on(pathname, l);
                        return (
                            <Link
                                key={l.href}
                                href={l.href}
                                aria-current={here ? "page" : undefined}
                                title={mini ? l.label : undefined}
                                className={cn(
                                    "flex min-h-11 items-center gap-3 rounded-small px-3 text-label-lg",
                                    here ? "bg-inverse-surface text-inverse-on-surface" : cn("text-on-surface-variant hover:text-on-surface", interactive()),
                                    mini && "justify-center px-0",
                                )}
                            >
                                {l.icon ? <Icon icon={l.icon} filled={here} /> : null}
                                {!mini ? <span className="min-w-0 flex-1 truncate">{l.label}</span> : <span className="sr-only">{l.label}</span>}
                                {l.count && !mini ? <CountBadge count={l.count} label={`${l.count} new`} /> : null}
                            </Link>
                        );
                    })}
                </div>
            ))}
        </nav>
    );

    return (
        <div className="flex min-h-dvh bg-surface text-on-surface">
            {/* Wide: the standing sidebar. */}
            <aside className={cn("sticky top-0 hidden h-dvh shrink-0 flex-col bg-surface-container-low transition-[width] duration-medium2 ease-standard expanded:flex", folded ? "w-[4.5rem]" : "w-[17rem]")}>
                <div className={cn("flex h-16 items-center gap-2 px-4", folded && "justify-center px-0")}>
                    {!folded ? <div className="min-w-0 flex-1">{brand}</div> : null}
                    <button type="button" onClick={() => setFolded(!folded)} aria-label={folded ? L.unfold : L.fold} aria-expanded={!folded} className={cn("inline-flex h-10 w-10 items-center justify-center rounded-small text-on-surface-variant", interactive())}>
                        <Icon icon={folded ? PanelLeftOpen : PanelLeftClose} />
                    </button>
                </div>
                {top && !folded ? <div className="px-3 pb-2">{top}</div> : null}
                {nav(folded)}
                {footer ? <div className={cn("p-3", folded && "flex justify-center")}>{footer}</div> : null}
            </aside>

            {/* Phones and tablets: the same sidebar, sliding over the page. */}
            {drawer ? (
                <div className="fixed inset-0 z-50 expanded:hidden">
                    <button type="button" aria-label={L.close} onClick={() => setDrawer(false)} className="absolute inset-0 bg-[rgb(var(--md-sys-color-scrim-rgb)/0.32)]" />
                    <aside role="dialog" aria-modal aria-label={L.main} className="absolute animate-in slide-in-from-left duration-200 rtl:slide-in-from-right inset-y-0 start-0 flex w-[min(20rem,86vw)] flex-col bg-surface-container-low shadow-level-3">
                        <div className="flex h-16 items-center gap-2 px-4">
                            <div className="min-w-0 flex-1">{brand}</div>
                            <button type="button" onClick={() => setDrawer(false)} aria-label={L.close} className={cn("inline-flex h-10 w-10 items-center justify-center rounded-small", interactive())}>
                                <Icon icon={X} />
                            </button>
                        </div>
                        {top ? <div className="px-3 pb-2">{top}</div> : null}
                        {nav(false)}
                        {footer ? <div className="p-3">{footer}</div> : null}
                    </aside>
                </div>
            ) : null}

            <div className="flex min-w-0 flex-1 flex-col">
                <header className="sticky top-0 z-30 flex h-16 items-center gap-2 bg-surface/90 px-gutter backdrop-blur">
                    <button type="button" onClick={() => setDrawer(true)} aria-label={L.open} className={cn("-ms-2 inline-flex h-10 w-10 items-center justify-center rounded-small expanded:hidden", interactive())}>
                        <Icon icon={MenuIcon} />
                    </button>
                    <div className="min-w-0 flex-1 truncate text-title-md">{title}</div>
                    {actions ? <div className="flex shrink-0 items-center gap-1">{actions}</div> : null}
                </header>
                <main className="min-w-0 flex-1 px-gutter pb-12 pt-2">{children}</main>
            </div>
        </div>
    );
}

/* ── Top-bar shell ────────────────────────────────────────────────────── */

export type TopbarShellProps = {
    pathname: string;
    brand: ReactNode;
    links: ShellLink[];
    /** Right side: bell, profile menu. */
    actions?: ReactNode;
    children: ReactNode;
};

/**
 * For products with five or fewer sections: the sections as tabs under the
 * logo, the page full width below. On a phone the tabs scroll sideways in
 * their own row - never a hamburger for five links.
 */
export function TopbarShell({ pathname, brand, links, actions, children }: TopbarShellProps) {
    return (
        <div className="flex min-h-dvh flex-col bg-surface text-on-surface">
            <header className="sticky top-0 z-30 bg-surface/90 backdrop-blur">
                <div className="mx-auto flex h-16 w-full max-w-content items-center gap-3 px-gutter">
                    <div className="min-w-0 flex-1">{brand}</div>
                    {actions ? <div className="flex shrink-0 items-center gap-1">{actions}</div> : null}
                </div>
                <nav aria-label="Main" className="mx-auto w-full max-w-content overflow-x-auto px-gutter [scrollbar-width:none]">
                    <ul className="flex gap-1">
                        {links.map((l) => {
                            const here = on(pathname, l);
                            return (
                                <li key={l.href}>
                                    <Link
                                        href={l.href}
                                        aria-current={here ? "page" : undefined}
                                        className={cn(
                                            "relative flex min-h-12 items-center gap-2 whitespace-nowrap rounded-t-small px-3 text-label-lg",
                                            here ? "text-on-surface after:absolute after:inset-x-3 after:bottom-0 after:h-[3px] after:bg-primary" : cn("text-on-surface-variant hover:text-on-surface", interactive()),
                                        )}
                                    >
                                        {l.icon ? <Icon icon={l.icon} size="sm" filled={here} /> : null}
                                        {l.label}
                                        {l.count ? <CountBadge count={l.count} label={`${l.count} new`} /> : null}
                                    </Link>
                                </li>
                            );
                        })}
                    </ul>
                </nav>
            </header>
            <main className="mx-auto w-full min-w-0 max-w-content flex-1 px-gutter pb-12 pt-6">{children}</main>
        </div>
    );
}

"use client";

import type { ReactNode } from "react";
import { cn } from "../cn";
import { NavigationBar, NavigationDrawer, NavigationRail, type NavItem } from "../navigation/Navigation";
import { useWindowClass } from "../components/position";
import { Card } from "../components/Card";
import { Sheet } from "../components/Sheet";

/**
 * The five layouts. A page picks one and composes inside it; it never builds
 * a shell of its own.
 *
 *   PublicLayout    marketing, docs, legal — a top bar and a footer, no nav.
 *   AppLayout       the signed-in product — destinations by window class.
 *   WorkspaceLayout the studio: a work canvas, an optional inspector, a
 *                   composer docked at the foot. The one arrangement kept
 *                   from the old UI (§1), redrawn entirely in M3.
 *   SettingsLayout  a list of sections beside one pane.
 *   DetailLayout    one thing: an agent, a run, a collection.
 *   AuthLayout      sign-in and approvals: the mark, one card, no navigation.
 *
 * Every one switches navigation on the M3 window size class (§2.6) and
 * reserves the space navigation takes, so nothing shifts when it appears.
 */

/* ── Public ───────────────────────────────────────────────────────────── */

export function PublicLayout({ header, footer, children, className }: { header?: ReactNode; footer?: ReactNode; children: ReactNode; className?: string }) {
    return (
        <div className={cn("flex min-h-dvh flex-col bg-surface text-on-surface", className)}>
            {header}
            <main className="flex-1">{children}</main>
            {footer}
        </div>
    );
}

/* ── Auth ─────────────────────────────────────────────────────────────── */

/**
 * Sign-in and approval screens (`/login`, `/authorize`). The mark, one card,
 * one line of small print - no navigation, because the page has one job and
 * a nav bar offers a way out of it. Vercel, Linear and Stripe all do this.
 *
 * `brand` sits in the same 64dp band, same corner, as on every other surface,
 * so arriving from the app doesn't make the logo jump. On a phone the card
 * starts near the top (the keyboard needs the bottom half); from `medium` up
 * it's centred.
 */
export function AuthLayout({ brand, footer, children, className }: { brand: ReactNode; footer?: ReactNode; children: ReactNode; className?: string }) {
    return (
        <div className="flex min-h-dvh flex-col bg-surface text-on-surface">
            <header className="flex h-16 shrink-0 items-center px-6">{brand}</header>
            <main className="flex flex-1 justify-center px-4 pb-8 pt-2 sm:items-center sm:pt-0">
                <Card padding="lg" className={cn("h-fit w-full max-w-[26rem] sm:p-8", className)}>
                    {children}
                </Card>
            </main>
            {footer ? <footer className="px-4 pb-6 text-center text-body-sm text-on-surface-variant">{footer}</footer> : null}
        </div>
    );
}

/* ── App ──────────────────────────────────────────────────────────────── */

export type AppLayoutProps = {
    items: NavItem[];
    /**
     * What the phone's navigation bar shows. M3 allows three to five
     * destinations there, and a product with more than five has to choose —
     * so the choice is made by the app, in one place, not by squeezing the
     * full list into an 80dp bar. Defaults to the first five of `items`.
     */
    compactItems?: NavItem[];
    pathname: string;
    /** The top app bar, built by the page that knows its title. */
    appBar?: ReactNode;
    /** Product mark / workspace switcher, shown in the drawer on large windows. */
    drawerHeader?: ReactNode;
    drawerFooter?: ReactNode;
    /** A FAB or menu button at the top of the rail. */
    railLeading?: ReactNode;
    children: ReactNode;
    className?: string;
};

export function AppLayout({ items, compactItems, pathname, appBar, drawerHeader, drawerFooter, railLeading, children, className }: AppLayoutProps) {
    const w = useWindowClass();
    const drawer = w === "large" || w === "xlarge";
    const rail = w === "medium" || w === "expanded";
    const bar = w === "compact";

    return (
        <div className={cn("flex min-h-dvh bg-surface text-on-surface", className)}>
            {drawer ? <NavigationDrawer items={items} pathname={pathname} header={drawerHeader} footer={drawerFooter} /> : null}
            {rail ? <NavigationRail items={items} pathname={pathname} leading={railLeading} /> : null}
            <div className="flex min-w-0 flex-1 flex-col">
                {appBar}
                <main className="min-w-0 flex-1 px-gutter pb-8">{children}</main>
                {bar ? <NavigationBar items={compactItems ?? items.slice(0, 5)} pathname={pathname} /> : null}
            </div>
        </div>
    );
}

/* ── Workspace ────────────────────────────────────────────────────────── */

export type WorkspaceLayoutProps = {
    /** The tool rail or panel on the left. Hidden on compact, where it becomes a sheet. */
    sidebar?: ReactNode;
    /** The raised work panel — the canvas, the grid, the editor. */
    children: ReactNode;
    /** Slides in from the right when something is selected. */
    inspector?: ReactNode;
    /** Docked at the foot: the prompt bar, the run controls. */
    composer?: ReactNode;
    /** Shown above everything: a title bar with the project name and actions. */
    appBar?: ReactNode;
    className?: string;
};

/**
 * The studio frame. The *arrangement* is the one thing kept from the old UI
 * (plan §1) because it is how the tool works, not how it looked: a sidebar on
 * a canvas, a raised work panel, a detail panel that slides in, a composer at
 * the foot. Every pixel of it is M3 surfaces, spacing and shape.
 *
 * `100dvh` and not `100vh`: on iOS Safari `100vh` is taller than the visible
 * screen, which put the composer under the address bar.
 */
export function WorkspaceLayout({ sidebar, children, inspector, composer, appBar, className }: WorkspaceLayoutProps) {
    const w = useWindowClass();
    const wide = w !== "compact";
    return (
        <div className={cn("flex h-dvh flex-col overflow-hidden bg-surface-dim text-on-surface", className)}>
            {appBar}
            <div className="flex min-h-0 flex-1">
                {wide && sidebar ? <aside className="w-20 shrink-0 overflow-y-auto bg-surface">{sidebar}</aside> : null}
                <main className="min-w-0 flex-1 overflow-hidden p-2">
                    <div className="h-full min-h-0 overflow-auto rounded-large bg-surface-container-low shadow-level-1">{children}</div>
                </main>
                {wide && inspector ? (
                    <aside className="w-[400px] shrink-0 overflow-y-auto bg-surface-container-low">{inspector}</aside>
                ) : null}
            </div>
            {composer ? <div className="shrink-0 bg-surface-container-low px-gutter py-2 shadow-level-up">{composer}</div> : null}
        </div>
    );
}

/* ── Settings ─────────────────────────────────────────────────────────── */

export type SettingsLayoutProps = {
    /** The section list. A row of tabs on compact, a column on wider windows. */
    sections: ReactNode;
    title?: ReactNode;
    children: ReactNode;
    className?: string;
};

export function SettingsLayout({ sections, title, children, className }: SettingsLayoutProps) {
    return (
        <div className={cn("mx-auto w-full max-w-content px-gutter py-6", className)}>
            {title ? <h1 className="mb-6 text-headline-sm text-on-surface">{title}</h1> : null}
            <div className="flex flex-col gap-6 expanded:flex-row">
                <div className="shrink-0 expanded:w-64">{sections}</div>
                <div className="min-w-0 flex-1">{children}</div>
            </div>
        </div>
    );
}

/* ── Detail ───────────────────────────────────────────────────────────── */

export type DetailLayoutProps = {
    /** The hero: name, price, state, the primary action. */
    header: ReactNode;
    children: ReactNode;
    /** Facts beside the content on wide windows, under it on a phone. */
    aside?: ReactNode;
    className?: string;
};

/**
 * One thing, in full. The aside comes *after* the main content in the DOM, so
 * a screen reader and a phone both get the thing itself before its metadata —
 * and CSS order puts it on the right when there is room.
 */
export function DetailLayout({ header, children, aside, className }: DetailLayoutProps) {
    return (
        <div className={cn("mx-auto w-full max-w-content px-gutter py-6", className)}>
            {header}
            <div className="mt-6 flex flex-col gap-6 expanded:flex-row">
                <div className="min-w-0 flex-1">{children}</div>
                {aside ? <div className="shrink-0 expanded:w-80">{aside}</div> : null}
            </div>
        </div>
    );
}

/* ── Canonical: list-detail ───────────────────────────────────────────── */

export type ListDetailProps = {
    /** The list. Always rendered — on a phone it IS the page. */
    list: ReactNode;
    /** The selected thing. `null` on a wide screen shows `empty` instead. */
    detail?: ReactNode;
    /** What the detail pane shows when nothing is selected. Never a blank half. */
    empty?: ReactNode;
    /** True when something is selected — on compact this is what swaps the panes. */
    selected?: boolean;
    /** Compact only: the back affordance above the detail. */
    onBack?: () => void;
    /** Width of the list pane from `medium` up. M3's own figure is 360dp. */
    listWidth?: string;
    className?: string;
};

/**
 * Android's **list-detail** canonical layout —
 * github.com/android/user-interface-samples/tree/main/CanonicalLayouts
 *
 * Compact: one pane. The list is the page; choosing something replaces it with
 * the detail, and back returns. Both panes stay MOUNTED — only one is shown —
 * so the list keeps its scroll position and its filters when you come back.
 * Unmounting it is the bug every hand-rolled version of this ships with.
 *
 * Medium and up: both panes at once, the list fixed and the detail filling.
 *
 * 🔴 Selection belongs in the URL, not in this component. The caller passes
 * `selected`, so a deep link opens the right pane and back/forward work — a
 * `useState` version breaks both.
 */
export function ListDetail({ list, detail, empty, selected, onBack, listWidth = "w-[360px]", className }: ListDetailProps) {
    const w = useWindowClass();
    const twoPane = w !== "compact";

    if (!twoPane) {
        return (
            <div className={cn("flex min-h-0 flex-1 flex-col", className)}>
                {/* `hidden`, not unmounted: scroll position and filters survive. */}
                <div className={cn("min-h-0 flex-1", selected && "hidden")}>{list}</div>
                {selected ? (
                    <div className="flex min-h-0 flex-1 flex-col">
                        {onBack ? (
                            <div className="shrink-0 px-2 py-1">
                                <button
                                    type="button"
                                    onClick={onBack}
                                    className="m3-state m3-focus inline-flex min-h-touch items-center gap-1 rounded-full px-3 text-label-lg text-on-surface outline-none"
                                >
                                    ← Back
                                </button>
                            </div>
                        ) : null}
                        <div className="min-h-0 flex-1">{detail}</div>
                    </div>
                ) : null}
            </div>
        );
    }

    return (
        <div className={cn("flex min-h-0 flex-1", className)}>
            <div className={cn("min-h-0 shrink-0 overflow-y-auto", listWidth)}>{list}</div>
            {/* One container step apart — law 11 put the divider here. */}
            <div className="min-h-0 min-w-0 flex-1 overflow-y-auto bg-surface-container-low">
                {selected ? detail : empty}
            </div>
        </div>
    );
}

/* ── Canonical: supporting pane ───────────────────────────────────────── */

export type SupportingPaneProps = {
    /** The work itself. Owns the room on every size. */
    children: ReactNode;
    /** The help: an inspector, filters, details. Never required to use the page. */
    supporting: ReactNode;
    /** Compact only: is the bottom sheet open. */
    open?: boolean;
    onOpenChange?: (open: boolean) => void;
    /** The sheet's title on compact. */
    title?: ReactNode;
    className?: string;
};

/**
 * Android's **supporting pane** canonical layout.
 *
 * Expanded and up: a permanent 360dp pane beside the work.
 * Compact and medium: the same content in a bottom sheet at half height, with
 * a drag handle — because a phone has no room for two columns, and a side
 * sheet on a 360px screen is the whole screen with extra steps.
 *
 * The sheet is a native `<dialog>`, so the browser supplies the top layer, the
 * focus trap, Esc, and `inert` on the page behind it. `amnt-kb-lift` keeps it
 * above the on-screen keyboard.
 */
export function SupportingPane({ children, supporting, open, onOpenChange, title, className }: SupportingPaneProps) {
    const w = useWindowClass();
    const side = w === "expanded" || w === "large" || w === "xlarge";

    if (side) {
        return (
            <div className={cn("flex min-h-0 flex-1", className)}>
                <div className="min-h-0 min-w-0 flex-1">{children}</div>
                <aside className="min-h-0 w-[360px] shrink-0 overflow-y-auto bg-surface-container-low">{supporting}</aside>
            </div>
        );
    }

    return (
        <div className={cn("flex min-h-0 flex-1 flex-col", className)}>
            <div className="min-h-0 flex-1">{children}</div>
            <Sheet
                open={Boolean(open)}
                onClose={() => onOpenChange?.(false)}
                placement="bottom"
                size="md"
                title={title ?? "Details"}
            >
                {supporting}
            </Sheet>
        </div>
    );
}

import Link from "next/link";
import type { ReactNode } from "react";
import type { IconGlyph } from "../primitives/Icon";
import { Icon } from "../primitives/Icon";
import { cn } from "../cn";
import { interactive } from "../state-layer";

export type NavListItem = {
    key: string;
    label: string;
    icon: IconGlyph;
    /** A link row. Give `href` or `onSelect`, not both. */
    href?: string;
    /** A button row, for navigation that is not a URL (the settings popup). */
    onSelect?: () => void;
    /** This row is where you are: filled icon, secondary-container, `aria-current`. */
    current?: boolean;
    /** After the label: a count, or a › on a phone list. */
    trailing?: ReactNode;
};

export type NavListGroup = {
    key: string;
    /** Omit on the first group when the page title already names it. */
    label?: string;
    items: NavListItem[];
};

const ROW =
    /* A 40dp row with an 8px corner (2026-10-09): dense like a pro sidebar. */
    "flex h-12 w-full shrink-0 items-center gap-3 rounded-small px-3 text-left text-label-lg medium:h-10 " +
    "transition-[background-color] duration-short4 ease-standard";

/**
 * The section list of a page that has sections — M3's navigation drawer rows,
 * inside the page instead of at the window's edge. The settings popup and
 * My stuff both use it, so the two can never drift.
 *
 * No client JS of its own: link rows are plain links, and the caller works out
 * `current` (from the pathname, or from state).
 */
export function NavList({ label, groups, className }: { label: string; groups: NavListGroup[]; className?: string }) {
    return (
        <nav aria-label={label} className={cn("flex min-w-0 flex-col gap-2", className)}>
            {groups.map((g) => (
                <div key={g.key} className="flex flex-col">
                    {g.label ? <p className="px-3 pb-1 pt-3 text-label-md text-on-surface-variant">{g.label}</p> : null}
                    {g.items.map((it) => {
                        const cls = cn(ROW, it.current ? "bg-secondary-container text-on-surface" : "text-on-surface-variant", interactive());
                        const inner = (
                            <>
                                <Icon icon={it.icon} size="sm" filled={it.current} />
                                <span className="min-w-0 flex-1 truncate">{it.label}</span>
                                {it.trailing}
                            </>
                        );
                        return it.href ? (
                            <Link key={it.key} href={it.href} aria-current={it.current ? "page" : undefined} className={cls}>
                                {inner}
                            </Link>
                        ) : (
                            <button key={it.key} type="button" onClick={it.onSelect} aria-current={it.current ? "page" : undefined} className={cls}>
                                {inner}
                            </button>
                        );
                    })}
                </div>
            ))}
        </nav>
    );
}

import Link from "next/link";
import { ChevronDown } from "@/ui/symbols";
import type { IconGlyph } from "../primitives/Icon";
import { Icon } from "../primitives/Icon";
import { interactive } from "../state-layer";
import { cn } from "../cn";

export type NavMenuLink = { label: string; href: string; icon: IconGlyph; desc?: string };
export type NavMenuGroup = { title?: string; items: NavMenuLink[] };

const isExternal = (href: string) => href.startsWith("http");

/**
 * The site header's "Products ▾ / Resources ▾" panel.
 *
 * Not `Menu`: that is a list of ACTIONS (role=menuitem, arrow keys). This is a
 * list of LINKS, so it stays plain links in a <nav> and opens on hover or on
 * keyboard focus with CSS alone - server-rendered, zero client JS.
 *
 * ponytail: no Esc-to-close (focus leaving closes it). Add a client island if
 * that is ever reported.
 */
export function NavMenu({ label, groups }: { label: string; groups: NavMenuGroup[] }) {
    return (
        <div className="group/nav relative">
            <button
                type="button"
                className="flex min-h-touch items-center gap-1 whitespace-nowrap rounded-extra-small text-label-lg text-on-surface-variant transition-state duration-short4 ease-standard hover:text-on-surface group-focus-within/nav:text-on-surface focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
            >
                {label}
                <Icon icon={ChevronDown} className="h-4 w-4 transition-transform duration-short4 ease-standard group-hover/nav:rotate-180 group-focus-within/nav:rotate-180" />
            </button>
            {/* pt-2 is a hover bridge: the pointer crosses it without leaving the group. */}
            <div className="invisible absolute left-0 top-full z-50 pt-2 opacity-0 transition-[opacity,visibility] duration-short4 ease-standard group-hover/nav:visible group-hover/nav:opacity-100 group-focus-within/nav:visible group-focus-within/nav:opacity-100">
                <div className="flex gap-2 rounded-large bg-surface-container-lowest p-2 shadow-level-3 dark:bg-surface-container-high">
                    <NavMenuGroups groups={groups} className="flex-row" />
                </div>
            </div>
        </div>
    );
}

/** The groups on their own - the header panel lays them side by side, the
 *  phone menu stacks them. `compact` drops the one-line descriptions. */
export function NavMenuGroups({ groups, compact, className }: { groups: NavMenuGroup[]; compact?: boolean; className?: string }) {
    return (
        <div className={cn("flex flex-col gap-2", className)}>
            {groups.map((g, i) => (
                <div key={g.title ?? i} className={compact ? undefined : "w-64"}>
                    {g.title && <p className="px-3 pb-1 pt-2 text-label-sm uppercase tracking-wider text-on-surface-variant">{g.title}</p>}
                    <ul>
                        {g.items.map((item) => (
                            <li key={item.href}>
                                <Link
                                    href={item.href}
                                    target={isExternal(item.href) ? "_blank" : undefined}
                                    rel={isExternal(item.href) ? "noopener noreferrer" : undefined}
                                    className={cn("group/item flex min-h-touch items-center gap-3 rounded-medium p-2 text-on-surface", interactive())}
                                >
                                    {/* One ink at rest, AMNT blue under the pointer (ui.css) - like every menu. */}
                                    <span className="flex aspect-square w-9 shrink-0 items-center justify-center rounded-medium bg-surface-container-high text-on-surface">
                                        <Icon icon={item.icon} className="h-5 w-5" hoverFill />
                                    </span>
                                    <span className="flex min-w-0 flex-col">
                                        <span className="text-label-lg text-on-surface">
                                            {item.label}
                                            {isExternal(item.href) && <span aria-hidden="true"> ↗</span>}
                                        </span>
                                        {!compact && item.desc && <span className="text-body-sm text-on-surface-variant">{item.desc}</span>}
                                    </span>
                                </Link>
                            </li>
                        ))}
                    </ul>
                </div>
            ))}
        </div>
    );
}

"use client";

import Link from "next/link";
import { createContext, forwardRef, type ButtonHTMLAttributes, type ReactNode } from "react";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "../primitives/Icon";
import { CountBadge } from "../primitives/Badge";
import { interactive } from "../state-layer";

/**
 * M3 navigation — https://m3.material.io/components/navigation-bar
 *   · /navigation-rail · /navigation-drawer · /top-app-bar
 *
 * One set of destinations, four presentations, chosen by window size class
 * (§2.6) and never by hand:
 *
 *   compact            NavigationBar  (bottom, 3–5 destinations)
 *   medium, expanded   NavigationRail (left, 80dp)
 *   large, xlarge      NavigationDrawer (left, 360dp, labels always visible)
 *
 * A layout picks one. A page never does — it does not know how wide it is.
 */

/**
 * Opens the app's navigation drawer from anywhere inside the frame.
 *
 * The shell provides it. A page that owns its own top bar (every studio)
 * reads it to put the ☰ in ITS bar, so a phone gets one row of chrome
 * instead of the shell's brand bar stacked on the studio's bar.
 * `null` outside a shell: then there is no drawer to open and no ☰ to show.
 */
export const NavDrawerContext = createContext<(() => void) | null>(null);

export type NavItem = {
    href: string;
    label: string;
    icon: IconGlyph;
    /** The filled version, shown when this destination is the current one. */
    activeIcon?: IconGlyph;
    /** A number on the item: unread, pending, failed. */
    count?: number;
};

const isActive = (pathname: string, href: string) =>
    href === "/" ? pathname === "/" : pathname === href || pathname.startsWith(`${href}/`);

/* ── Navigation bar (compact) ─────────────────────────────────────────── */

export type NavigationBarProps = {
    items: NavItem[];
    /** The current path, from `usePathname()` in the layout. */
    pathname: string;
    className?: string;
};

/**
 * M3 navigation bar: 80dp tall, at the bottom, 3–5 destinations. The active
 * one gets a `secondary-container` pill behind its icon — that pill IS the
 * indicator, and it is the only thing that says which destination you are on
 * besides the label weight, so it is never removed to "clean it up".
 */
export function NavigationBar({ items, pathname, className }: NavigationBarProps) {
    return (
        <nav
            aria-label="Main"
            className={cn(
                "sticky bottom-0 z-nav flex h-20 w-full shrink-0 items-stretch justify-around gap-1",
                "bg-surface-container px-2 pb-[env(safe-area-inset-bottom)] shadow-level-up",
                className,
            )}
        >
            {items.map(item => {
                const on = isActive(pathname, item.href);
                const Glyph = on ? (item.activeIcon ?? item.icon) : item.icon;
                return (
                    <Link
                        key={item.href}
                        href={item.href}
                        aria-current={on ? "page" : undefined}
                        className={cn("flex min-w-0 flex-1 flex-col items-center gap-1 pt-3 rounded-medium", interactive())}
                    >
                        <span
                            className={cn(
                                /* check-design-allow: the indicator pill. The 80dp bar row around it is the target. */
                                "relative flex h-8 w-14 items-center justify-center rounded-small",
                                "transition-[background-color] duration-short4 ease-standard",
                                on ? "bg-secondary-container text-on-secondary-container" : "text-on-surface-variant",
                            )}
                        >
                            <Icon icon={Glyph} size="md" filled={on} hoverFill />
                            {item.count ? (
                                <CountBadge count={item.count} label={item.label} className="absolute -right-1 top-0" />
                            ) : null}
                        </span>
                        <span className={cn("max-w-full truncate text-label-md", on ? "text-on-surface" : "text-on-surface-variant")}>
                            {item.label}
                        </span>
                    </Link>
                );
            })}
        </nav>
    );
}

/* ── Navigation rail (medium / expanded) ──────────────────────────────── */

export type NavigationRailProps = {
    items: NavItem[];
    pathname: string;
    /** A FAB or menu button at the top of the rail. */
    leading?: ReactNode;
    className?: string;
};

/** M3 navigation rail: 80dp wide, on the left, icons with labels underneath. */
export function NavigationRail({ items, pathname, leading, className }: NavigationRailProps) {
    return (
        <nav
            aria-label="Main"
            className={cn(
                "sticky top-0 z-nav flex h-dvh w-20 shrink-0 flex-col items-center gap-3 overflow-y-auto bg-surface py-3",
                className,
            )}
        >
            {leading ? <div className="mb-2">{leading}</div> : null}
            {items.map(item => (
                <NavRailItem key={item.href} {...item} active={isActive(pathname, item.href)} />
            ))}
        </nav>
    );
}

/**
 * One rail destination: the icon in a 56x32 pill, the label underneath. The
 * whole row is the target; hovering shades the pill, tints the icon and fills
 * it. The current one is filled on a `secondary-container` pill.
 */
export function NavRailItem({
    href,
    label,
    icon,
    activeIcon,
    count,
    active,
    onClick,
}: NavItem & { active: boolean; onClick?: () => void }) {
    return (
        <Link href={href} onClick={onClick} aria-current={active ? "page" : undefined} className={RAIL_ITEM}>
            <RailFace label={label} icon={icon} activeIcon={activeIcon} count={count} active={active} />
        </Link>
    );
}

/**
 * The same rail item as a button - for a destination that opens a menu
 * (the shell's "New") instead of a page. Spread a Menu trigger's props on it.
 */
export const NavRailButton = forwardRef<
    HTMLButtonElement,
    Omit<NavItem, "href"> & { active?: boolean } & Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children">
>(function NavRailButton({ label, icon, activeIcon, count, active = false, className, ...rest }, ref) {
    return (
        <button ref={ref} type="button" {...rest} className={cn(RAIL_ITEM, className)}>
            <RailFace label={label} icon={icon} activeIcon={activeIcon} count={count} active={active} />
        </button>
    );
});

const RAIL_ITEM = "m3-rail m3-focus flex w-full flex-col items-center gap-1 rounded-medium py-1";

function RailFace({ label, icon, activeIcon, count, active }: Omit<NavItem, "href"> & { active: boolean }) {
    return (
        <>
            <span
                className={cn(
                    /* check-design-allow: the indicator pill. The rail row around it is the target. */
                    "m3-state m3-rail-pill relative flex h-8 w-12 items-center justify-center rounded-small",
                    "transition-[background-color] duration-short4 ease-standard",
                    active ? "bg-secondary-container text-on-secondary-container" : "text-on-surface-variant",
                )}
            >
                <Icon icon={active ? (activeIcon ?? icon) : icon} size="md" filled={active} hoverFill />
                {count ? <CountBadge count={count} label={label} className="absolute -right-1 top-0" /> : null}
            </span>
            {/* No side padding: the 80dp rail has to fit "Collections" whole. */}
            <span className={cn("max-w-full truncate text-label-md tracking-normal", active ? "text-on-surface" : "text-on-surface-variant")}>
                {label}
            </span>
        </>
    );
}

/* ── Navigation drawer (large+) ───────────────────────────────────────── */

export type NavigationDrawerProps = {
    items: NavItem[];
    pathname: string;
    /** A product mark or a workspace switcher at the top. */
    header?: ReactNode;
    /** Account, settings, sign-out — pinned to the foot. */
    footer?: ReactNode;
    /** Grouped destinations get a heading; pass them as extra children. */
    children?: ReactNode;
    className?: string;
};

/**
 * M3 standard navigation drawer: 360dp, always visible on large windows.
 * Each destination is a 56dp `full`-cornered row — M3's anatomy, and the
 * reason a drawer row is not a list row.
 */
export function NavigationDrawer({ items, pathname, header, footer, children, className }: NavigationDrawerProps) {
    return (
        <nav
            aria-label="Main"
            className={cn("sticky top-0 z-nav flex h-dvh w-[360px] shrink-0 flex-col gap-1 overflow-y-auto bg-surface p-3", className)}
        >
            {header ? <div className="px-4 py-3">{header}</div> : null}
            {items.map(item => {
                const on = isActive(pathname, item.href);
                const Glyph = on ? (item.activeIcon ?? item.icon) : item.icon;
                return (
                    <Link
                        key={item.href}
                        href={item.href}
                        aria-current={on ? "page" : undefined}
                        className={cn(
                            "flex h-10 shrink-0 items-center gap-3 rounded-small px-3",
                            "transition-[background-color] duration-short4 ease-standard",
                            on ? "bg-secondary-container text-on-surface" : "text-on-surface-variant",
                            interactive(),
                        )}
                    >
                        <Icon icon={Glyph} size="md" filled={on} hoverFill />
                        <span className="min-w-0 flex-1 truncate text-label-lg">{item.label}</span>
                        {item.count ? <CountBadge count={item.count} label={item.label} /> : null}
                    </Link>
                );
            })}
            {children}
            {footer ? <div className="mt-auto pt-3">{footer}</div> : null}
        </nav>
    );
}

/* ── Top app bar ──────────────────────────────────────────────────────── */

export type TopAppBarProps = {
    title: ReactNode;
    /** Back arrow, menu button or product mark. */
    leading?: ReactNode;
    /** Up to three icon buttons, plus an overflow menu. */
    actions?: ReactNode;
    /**
     * small   64dp, one line — the default.
     * medium  112dp, title on its own line under the actions.
     * large   152dp, display-sized title. For a landing or a detail hero.
     */
    size?: "small" | "medium" | "large";
    /** Raises the bar onto `surface-container` once the page has scrolled. */
    scrolled?: boolean;
    className?: string;
};

export function TopAppBar({ title, leading, actions, size = "small", scrolled, className }: TopAppBarProps) {
    return (
        <header
            className={cn(
                "sticky top-0 z-sticky w-full shrink-0 transition-[background-color] duration-medium2 ease-standard",
                scrolled ? "bg-surface-container" : "bg-surface",
                className,
            )}
        >
            <div className={cn("flex items-center gap-1 px-1", size === "small" ? "h-16" : "h-16")}>
                {leading}
                {size === "small" ? (
                    <h1 className="min-w-0 flex-1 truncate px-3 text-title-lg text-on-surface">{title}</h1>
                ) : (
                    <span className="flex-1" />
                )}
                {actions ? <div className="flex shrink-0 items-center gap-1 px-1">{actions}</div> : null}
            </div>
            {size !== "small" ? (
                <h1
                    className={cn(
                        "px-4 pb-6 text-on-surface",
                        size === "medium" ? "text-headline-sm" : "text-headline-md",
                    )}
                >
                    {title}
                </h1>
            ) : null}
        </header>
    );
}

import type { ReactNode } from "react";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "./Icon";

/**
 * M3 badge — https://m3.material.io/components/badges
 *
 * A short, non-interactive label: a state, a chain, a count. If it can be
 * clicked it is a Chip or a Button, not a Badge.
 *
 * Shape (recorded per law §2.3): `small`. Counts use `full`.
 *
 * ⚠️ There are no invented tones. M3 gives four container pairs — `primary`,
 * `secondary`, `tertiary`, `error` — and those are the only ones. A badge
 * never carries meaning by colour alone: the word inside it does that, which
 * is why `tone` has no "success" and no "warning".
 *
 * `premium` is the one M3 custom colour (tokens.ts `customColors`): the gold
 * on Pro items, with the word "Pro" inside, owner 2026-09-27.
 */

const TONE = {
    neutral: "bg-surface-container-highest text-on-surface-variant",
    primary: "bg-primary-container text-on-primary-container",
    secondary: "bg-secondary-container text-on-secondary-container",
    tertiary: "bg-tertiary-container text-on-tertiary-container",
    error: "bg-error-container text-on-error-container",
    // Gold in both themes: the pale container on light, the bright role on dark (its container is brown).
    premium: "bg-premium-container text-on-premium-container dark:bg-premium dark:text-on-premium",
} as const;

const SOLID = {
    neutral: "bg-inverse-surface text-inverse-on-surface",
    primary: "bg-primary text-on-primary",
    secondary: "bg-inverse-surface text-inverse-on-surface",
    tertiary: "bg-tertiary text-on-tertiary",
    error: "bg-error text-on-error",
    premium: "bg-premium text-on-premium",
} as const;

export type BadgeTone = keyof typeof TONE;

export type BadgeProps = {
    tone?: BadgeTone;
    variant?: "tonal" | "solid" | "outlined";
    size?: "sm" | "md";
    icon?: IconGlyph;
    /** Prices and counts: keeps digits aligned between rows (§2.2). */
    numeric?: boolean;
    className?: string;
    children: ReactNode;
};

export function Badge({ tone = "neutral", variant = "tonal", size = "md", icon, numeric, className, children }: BadgeProps) {
    return (
        <span
            className={cn(
                "inline-flex shrink-0 items-center gap-1 whitespace-nowrap rounded-small",
                size === "sm" ? "h-5 px-1.5 text-label-sm" : "h-6 px-2 text-label-md",
                variant === "solid" ? SOLID[tone] : TONE[tone],
                variant === "outlined" && "bg-surface-container-high text-on-surface-variant",
                numeric && "tnum",
                className,
            )}
        >
            {icon ? <Icon icon={icon} size="sm" className="h-4 w-4" /> : null}
            {children}
        </span>
    );
}

export type CountBadgeProps = { count: number; max?: number; label: string; className?: string };

/**
 * M3's small/large badge: the number on a nav item or an avatar. Anything over
 * `max` reads "99+", because a four-digit badge stops being a badge.
 */
export function CountBadge({ count, max = 99, label, className }: CountBadgeProps) {
    if (count <= 0) return null;
    return (
        <span
            aria-label={`${count} ${label}`}
            className={cn(
                "inline-flex h-4 min-w-[16px] items-center justify-center rounded-full bg-error px-1 text-label-sm text-on-error tnum",
                className,
            )}
        >
            {count > max ? `${max}+` : count}
        </span>
    );
}

/* ── Product state ────────────────────────────────────────────────────── */

/**
 * An agent's state as a dot plus a word.
 *
 * The roles come from `tokens.semantic`, which maps a product state to an M3
 * role — §2.1 forbids inventing a colour for one. The dot alone never carries
 * the meaning: colour-blind users and screen readers both get the word, and
 * `running` is the only state that also moves, because it is the only one
 * that is changing.
 */
const AGENT_STATE = {
    live: { tone: "text-positive", label: "Live" },
    running: { tone: "text-primary", label: "Running" },
    paused: { tone: "text-on-surface-variant", label: "Paused" },
    failed: { tone: "text-error", label: "Failed" },
    draft: { tone: "text-outline", label: "Draft" },
} as const;

export type StatusProps = {
    state: keyof typeof AGENT_STATE;
    /** Defaults to the state's own word. */
    children?: ReactNode;
    /** Dot only, with the state still announced to screen readers. */
    dotOnly?: boolean;
    className?: string;
};

export function Status({ state, children, dotOnly, className }: StatusProps) {
    const s = AGENT_STATE[state];
    return (
        <span className={cn("inline-flex items-center gap-1.5 text-label-md", s.tone, className)}>
            <span aria-hidden className={cn("h-2 w-2 shrink-0 rounded-full bg-current", state === "running" && "m3-pulse")} />
            {dotOnly ? <span className="sr-only">{children ?? s.label}</span> : (children ?? s.label)}
        </span>
    );
}

/* ── Divider ──────────────────────────────────────────────────────────── */

export type DividerProps = {
    orientation?: "horizontal" | "vertical";
    /** M3 inset divider: indented to line up with list text past the leading icon. */
    inset?: boolean;
    /** A word in the gap, like "or" between two ways to sign in. Still no line. */
    label?: string;
    className?: string;
};

/** M3 divider — 1dp of `outline-variant`, and never a colour of its own. */
/**
 * 🔴 Law 11: this draws NO line. It is the semantic separator plus the space a
 * line used to occupy — the gap is what the eye reads, the role is what a
 * screen reader reads. Kept as a component so the two stay in step, and so the
 * ~2 call sites did not each have to invent their own margin.
 *
 * If you want a visible rule, you want a surface step or a `Section` instead.
 */
export function Divider({ orientation = "horizontal", inset, label, className }: DividerProps) {
    if (label) {
        return (
            <div role="separator" aria-label={label} className={cn("text-center text-label-md uppercase text-on-surface-variant", className)}>
                {label}
            </div>
        );
    }
    return (
        <div
            role="separator"
            aria-orientation={orientation}
            className={cn(
                "shrink-0",
                orientation === "horizontal" ? "h-4 w-full" : "w-4 self-stretch",
                inset && orientation === "horizontal" && "ml-4",
                className,
            )}
        />
    );
}

"use client";

import Link from "next/link";
import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from "react";
import type { IconGlyph } from "../primitives/Icon";
import { cn } from "../cn";
import { Icon } from "./Icon";
import { Spinner } from "./Progress";
import { interactive } from "../state-layer";

/**
 * M3 common buttons — https://m3.material.io/components/buttons
 *
 * Five variants, in order of emphasis. Pick by how important the action is on
 * the screen, never by how it looks:
 *
 *   filled    the one thing the screen is for. At most one per view.
 *   tonal     an important action next to the filled one.
 *   elevated  the same emphasis as tonal, but on a busy or scrolling surface
 *             where a tonal fill would disappear.
 *   outlined  a secondary action that still needs a boundary.
 *   text      the lowest emphasis: in a card footer, in a dialog, in a row.
 *
 * Shape (2026-10-09): `small`, an 8px corner, on every size. Pills read as
 * a phone OS; a firm small corner reads as a tool. A dense data action uses
 * `size="xs"`, 32dp tall.
 *
 * Every variant gets the same state layer and the same focus ring, from
 * `src/ui/state-layer.ts`. No variant invents a hover colour.
 */

const VARIANT = {
    /* Flat fills, no lift on hover: the state layer is the only hover. Only
       `filled` is blue; every other variant is neutral ink, so one screen
       never has three blue buttons competing. */
    filled: "bg-primary text-on-primary",
    /* A see-through ink fill, not a fixed grey: it stays visible on the
       white page AND on a grey card, where a grey button used to vanish. */
    tonal: "bg-on-surface/[0.07] text-on-surface",
    elevated: "bg-surface-container-lowest text-on-surface shadow-level-1 dark:bg-surface-container-high",
    /* A 1px hairline, drawn inset so the box never grows. */
    outlined: "bg-transparent text-on-surface shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.14)] disabled:shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.12)]",
    text: "text-on-surface",
    /** Destructive. M3 has no danger variant; `error` is the role for it. */
    danger: "bg-error text-on-error",
} as const;

/**
 * M3 button heights. 40dp is the spec default; `xs` is AMNT's dense step for
 * table rows and toolbars, and it still carries a 48dp touch target.
 */
const SIZE = {
    xs: "h-8 px-3 text-label-lg gap-1.5",
    md: "h-10 px-4 text-label-lg gap-2",
    lg: "h-12 px-5 text-title-sm gap-2",
} as const;

/** Text buttons sit closer to their neighbours: M3 gives them 12dp, not 24dp. */
const TEXT_PAD = { xs: "px-2", md: "px-3", lg: "px-4" } as const;

export type ButtonVariant = keyof typeof VARIANT;
export type ButtonSize = keyof typeof SIZE;

/** The shared shape of every button-like thing, so a link matches a button. */
export function buttonStyles(variant: ButtonVariant = "filled", size: ButtonSize = "md", fullWidth?: boolean) {
    return cn(
        "inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-small",
        /* 🔴 The shape never changes on press. It used to animate the corner
           from 9999px to 12px, which a browser interpolates in px: the pill
           stayed round, snapped square at the last frame, then jumped back
           round on release - read as a glitch (owner, 2026-09-28). The press
           is the M3 state layer, nothing else. */
        "transition-press",
        /* 40dp box (M3), 48dp to a finger: the hit area is a pseudo-element,
           so the button itself never grows. */
        "before:absolute before:inset-x-0 before:top-1/2 before:h-touch before:-translate-y-1/2 before:content-['']",
        VARIANT[variant],
        SIZE[size],
        variant === "text" && TEXT_PAD[size],
        fullWidth && "w-full",
        interactive({ inverse: variant === "filled" || variant === "danger" }),
        "disabled:pointer-events-none disabled:text-on-surface/[0.38]",
        /* M3 disabled: a 12% container on the filled kinds; the outlined one
           keeps its stroke at 12%; a text button has no container at all. */
        variant === "outlined" || variant === "text" ? "disabled:bg-transparent" : "disabled:bg-on-surface/[0.12] disabled:shadow-none",
    );
}

type Common = {
    variant?: ButtonVariant;
    size?: ButtonSize;
    /** Leading icon. Decorative — the label says what the button does. */
    icon?: IconGlyph;
    /** Trailing icon: a chevron, an external-link mark. */
    trailingIcon?: IconGlyph;
    fullWidth?: boolean;
    children?: ReactNode;
};

export type ButtonProps = Common &
    Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
        /** Swaps the leading icon for a spinner and blocks the click. */
        loading?: boolean;
        /** Announced while `loading`. Without it a screen reader hears nothing change. */
        loadingLabel?: string;
    };

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
    { variant = "filled", size = "md", icon, trailingIcon, fullWidth, loading, loadingLabel = "Working…", children, className, disabled, type = "button", ...rest },
    ref,
) {
    const iconSize = size === "lg" ? "md" : "sm";
    return (
        <button
            ref={ref}
            type={type}
            disabled={disabled || loading}
            aria-busy={loading || undefined}
            className={cn(buttonStyles(variant, size, fullWidth), className)}
            {...rest}
        >
            {loading ? <Spinner size="sm" label={loadingLabel} /> : icon ? <Icon icon={icon} size={iconSize} /> : null}
            {children}
            {trailingIcon && !loading ? <Icon icon={trailingIcon} size={iconSize} /> : null}
        </button>
    );
});

export type ButtonLinkProps = Common & {
    href: string;
    /** Opens in a new tab and adds the rel that stops the new page reaching back. */
    external?: boolean;
    className?: string;
    "aria-label"?: string;
    prefetch?: boolean;
};

/**
 * A link that looks like a button. It is an `<a>`, because it navigates —
 * which means middle-click, ⌘-click and "copy link address" all work.
 */
export function ButtonLink({ href, external, variant = "filled", size = "md", icon, trailingIcon, fullWidth, children, className, prefetch, ...rest }: ButtonLinkProps) {
    const iconSize = size === "lg" ? "md" : "sm";
    const inner = (
        <>
            {icon ? <Icon icon={icon} size={iconSize} /> : null}
            {children}
            {trailingIcon ? <Icon icon={trailingIcon} size={iconSize} /> : null}
        </>
    );
    const cls = cn(buttonStyles(variant, size, fullWidth), className);
    if (external) {
        return (
            <a href={href} target="_blank" rel="noopener noreferrer" className={cls} {...rest}>
                {inner}
            </a>
        );
    }
    return (
        <Link href={href} prefetch={prefetch} className={cls} {...rest}>
            {inner}
        </Link>
    );
}

/* ── Icon button ──────────────────────────────────────────────────────── */

const ICON_VARIANT = {
    standard: "text-on-surface-variant",
    filled: "bg-primary text-on-primary",
    tonal: "bg-on-surface/[0.07] text-on-surface",
    outlined: "bg-transparent text-on-surface shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.14)]",
    /** Save, and nothing else: the one green button (tokens.ts `positive`). */
    positive: "bg-positive text-on-positive",
} as const;

const ICON_SIZE = { sm: "h-8 w-8", md: "h-10 w-10", lg: "h-12 w-12" } as const;

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
    icon: IconGlyph;
    /** Required: the button has no words, so this IS its name. */
    label: string;
    variant?: keyof typeof ICON_VARIANT;
    size?: keyof typeof ICON_SIZE;
    /** A toggle icon button. Sets `aria-pressed` and the selected state layer. */
    pressed?: boolean;
};

/**
 * M3 icon button — https://m3.material.io/components/icon-buttons
 *
 * 40dp visual box, 48dp touch target. The extra hit area is a transparent
 * pseudo-element, so growing it never moves the neighbours.
 */
export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
    { icon, label, variant = "standard", size = "md", pressed, className, type = "button", ...rest },
    ref,
) {
    return (
        <button
            ref={ref}
            type={type}
            aria-label={label}
            aria-pressed={pressed}
            data-selected={pressed || undefined}
            className={cn(
                "inline-flex shrink-0 items-center justify-center rounded-small transition-press",
                /* 48dp to the finger without a 48dp box. */
                "before:absolute before:left-1/2 before:top-1/2 before:h-touch before:w-touch before:-translate-x-1/2 before:-translate-y-1/2 before:content-['']",
                ICON_VARIANT[variant],
                ICON_SIZE[size],
                interactive({ inverse: variant === "filled" || variant === "positive" }),
                "disabled:pointer-events-none disabled:text-on-surface/[0.38] disabled:bg-transparent",
                className,
            )}
            {...rest}
        >
            <Icon icon={icon} size={size === "sm" ? "sm" : "md"} />
        </button>
    );
});

/* ── FAB ──────────────────────────────────────────────────────────────── */

const FAB_SIZE = { sm: "h-10 w-10 rounded-medium", md: "h-14 w-14 rounded-large", lg: "h-20 w-20 rounded-extra-large" } as const;

export type FabProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
    icon: IconGlyph;
    label: string;
    size?: keyof typeof FAB_SIZE;
    /** An extended FAB shows its label. Use it when the action needs a word. */
    extended?: boolean;
};

/**
 * M3 FAB — https://m3.material.io/components/floating-action-button
 *
 * The single most important action on a screen, and only when it is a screen
 * where that action is the point. If a page has two, neither is a FAB.
 */
export const Fab = forwardRef<HTMLButtonElement, FabProps>(function Fab(
    { icon, label, size = "md", extended, className, type = "button", ...rest },
    ref,
) {
    return (
        <button
            ref={ref}
            type={type}
            aria-label={extended ? undefined : label}
            className={cn(
                "inline-flex items-center justify-center gap-3 bg-primary text-on-primary shadow-level-3",
                "transition-press",
                extended ? "h-12 rounded-medium px-5 text-label-lg" : FAB_SIZE[size],
                interactive({ inverse: true }),
                className,
            )}
            {...rest}
        >
            <Icon icon={icon} size={size === "lg" ? "lg" : "md"} />
            {extended ? label : null}
        </button>
    );
});

"use client";

import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from "react";
import Link from "next/link";
import type { IconGlyph } from "../primitives/Icon";
import { Check, X } from "@/ui/symbols";
import { cn } from "../cn";
import { Icon } from "./Icon";
import { interactive } from "../state-layer";

/**
 * M3 chips — https://m3.material.io/components/chips
 *
 * Four kinds, and the kind is decided by what the chip DOES, not how it looks:
 *
 *   assist      helps with the current task: "Add to calendar", "Share".
 *   filter      narrows a set. Toggles. Shows a check when on.
 *   input       a thing the user entered: a tag, a recipient. Has a remove X.
 *   suggestion  a shortcut the app is offering: a prompt, a saved query.
 *
 * Shape (recorded per law §2.3): `small` — M3's chip corner, 8dp.
 * Height is 32dp, and the 48dp touch target is added without growing the box.
 */

/* M3 flat chip (material-web md-comp-*-chip): no fill, a 1dp stroke drawn
   inset so the box never grows; selected is `secondary-container` with no
   stroke. The stroke is `outline-variant`, the calmer M3 2025 value, so a row
   of chips reads as a set of options and not as a row of boxes. The icon is
   muted ink (2026-10-09); selected is the blue tint, the one place a chip
   uses the accent, so "picked" reads at a glance. */
const UNSELECTED = "bg-transparent text-on-surface shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-on-surface-rgb)/0.14)] [&>[data-chip-icon]]:text-on-surface-variant";
const SELECTED = "bg-primary-container text-on-primary-container shadow-[inset_0_0_0_1px_rgb(var(--md-sys-color-primary-rgb)/0.24)]";

export type ChipKind = "assist" | "filter" | "input" | "suggestion";

const BASE =
    "inline-flex h-8 shrink-0 select-none items-center gap-2 whitespace-nowrap rounded-small px-3 text-label-lg " +
    "transition-press " +
    /* 48dp to the finger, on a 32dp box. */
    "before:absolute before:left-1/2 before:top-1/2 before:h-touch before:w-full before:-translate-x-1/2 before:-translate-y-1/2 before:content-['']";

export type ChipProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "onSelect"> & {
    kind?: ChipKind;
    /** Filter and input chips: whether this one is on. */
    selected?: boolean;
    /** Leading icon, or an avatar element for an input chip. */
    icon?: IconGlyph;
    avatar?: ReactNode;
    /** Input chips: shown as a trailing X. Makes the chip removable. */
    onRemove?: () => void;
    /** The word on the remove button, e.g. "Remove tag Solana". */
    removeLabel?: string;
    children: ReactNode;
};

export const Chip = forwardRef<HTMLButtonElement, ChipProps>(function Chip(
    { kind = "assist", selected, icon, avatar, onRemove, removeLabel, children, className, type = "button", disabled, ...rest },
    ref,
) {
    /* A filter chip is a toggle, so it announces pressed state; everything
       else is a plain button. An input chip is not a toggle at all. */
    const isToggle = kind === "filter";
    const on = Boolean(selected);

    return (
        <span className={cn("relative inline-flex", disabled && "pointer-events-none opacity-[0.38]")}>
            <button
                ref={ref}
                type={type}
                disabled={disabled}
                aria-pressed={isToggle ? on : undefined}
                data-selected={on || undefined}
                /* The prompt bar folds a chip to an icon on a phone (ui.css). */
                data-chip=""
                className={cn(
                    BASE,
                    on ? SELECTED : kind === "suggestion" || kind === "assist" ? UNSELECTED : cn(UNSELECTED, "text-on-surface-variant"),
                    /* An input chip that can be removed leaves room for the X. */
                    onRemove && "pr-1",
                    avatar && "pl-1",
                    interactive(),
                    className,
                )}
                {...rest}
            >
                {on && isToggle ? <Icon icon={Check} size="sm" className="h-[18px] w-[18px]" /> : null}
                {avatar}
                {icon && !(on && isToggle) ? <Icon icon={icon} size="sm" data-chip-icon="" className="h-[18px] w-[18px]" /> : null}
                {children}
                {onRemove ? <span aria-hidden className="w-[18px]" /> : null}
            </button>
            {onRemove ? (
                /* Its own button, not a click zone inside the chip: removing is
                   a different action from selecting and needs its own name. */
                <button
                    type="button"
                    onClick={onRemove}
                    disabled={disabled}
                    aria-label={removeLabel ?? "Remove"}
                    className={cn(
                        "absolute right-1 top-1/2 inline-flex h-[18px] w-[18px] -translate-y-1/2 items-center justify-center rounded-full",
                        "text-on-surface-variant",
                        "before:absolute before:left-1/2 before:top-1/2 before:h-touch before:w-touch before:-translate-x-1/2 before:-translate-y-1/2 before:content-['']",
                        interactive(),
                    )}
                >
                    <Icon icon={X} width={16} height={16} strokeWidth={2} aria-hidden focusable={false} />
                </button>
            ) : null}
        </span>
    );
});

export type ChipLinkProps = {
    href: string;
    /** This chip is the page you are on: shown selected, announced as current. */
    current?: boolean;
    icon?: IconGlyph;
    /** A count after the label, e.g. 36 items. */
    count?: number;
    prefetch?: boolean;
    className?: string;
    children: ReactNode;
};

/**
 * An assist chip that GOES somewhere: a category, a tag, a style. A link,
 * never a button, so crawlers and "open in new tab" work. Same shape, height
 * and 48dp touch target as `Chip`.
 */
export function ChipLink({ href, current, icon, count, prefetch, className, children }: ChipLinkProps) {
    return (
        <Link
            href={href}
            prefetch={prefetch}
            aria-current={current ? "page" : undefined}
            className={cn(
                "relative",
                BASE,
                current ? SELECTED : UNSELECTED,
                interactive(),
                className,
            )}
        >
            {icon ? <Icon icon={icon} size="sm" data-chip-icon="" className="h-[18px] w-[18px]" /> : null}
            {children}
            {count !== undefined ? <span className="text-on-surface-variant">{count}</span> : null}
        </Link>
    );
}

export type ChipGroupProps = {
    /** What the set of chips is for, e.g. "Filter by chain". */
    label: string;
    /** Chips wrap by default; `scroll` keeps them on one line on a phone. */
    overflow?: "wrap" | "scroll";
    children: ReactNode;
    className?: string;
};

/**
 * A set of chips. It is a `group` with a name, so a screen reader says what
 * the row of chips is filtering before reading the chips themselves.
 */
export function ChipGroup({ label, overflow = "wrap", children, className }: ChipGroupProps) {
    return (
        <div
            role="group"
            aria-label={label}
            className={cn(
                "flex gap-2",
                overflow === "wrap" ? "flex-wrap" : "overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
                className,
            )}
        >
            {children}
        </div>
    );
}

import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../cn";
import { SYMBOL_VIEWBOX, type Glyph } from "./symbols.generated";

export type { Glyph };

/**
 * What any component means by "an icon": a Material Symbol from `@/ui/symbols`.
 *
 * It is an alias rather than a re-export of `Glyph` so the hundreds of
 * `icon?: IconGlyph` props read as intent ("something Icon can draw") instead
 * of as an implementation detail.
 */
export type IconGlyph = Glyph;

/**
 * M3 icon sizes. 24dp is the spec default and what almost everything uses;
 * 18 is for dense rows and chips, 32/40 for FABs and empty states.
 */
const SIZE = { sm: 18, md: 24, lg: 32, xl: 40 } as const;
export type IconSize = keyof typeof SIZE;

export type IconProps = Omit<ComponentPropsWithoutRef<"svg">, "role" | "children" | "ref"> & {
    /** A Material Symbol from `@/ui/symbols` — `import { Search } from "@/ui/symbols"`. */
    icon: IconGlyph;
    size?: IconSize;
    /**
     * M3's fill axis. An unselected destination is outlined, a selected one is
     * filled — that is how a nav bar shows where you are without spending a
     * colour on it. Ignored for a symbol whose fill is identical.
     */
    filled?: boolean;
    /**
     * Fills and tints on hover of the link, button or menu row around it
     * (owner, 2026-09-27: every menu icon answers the pointer). CSS only -
     * `.m3-icon-hover` in ui.css - so it costs no state and no JS.
     */
    hoverFill?: boolean;
    /** Only when the icon carries meaning on its own. Decorative icons stay hidden. */
    label?: string;
    className?: string;
};

/**
 * The only way an icon enters the UI.
 *
 * Material Symbols Rounded, weight 400, optical 24 — owner, 2026-09-23. They
 * arrive as path data generated at build time (scripts/icons-build.ts), not as
 * the variable webfont: the font is megabytes and every icon would be an empty
 * box until it landed.
 *
 * An icon with no `label` is `aria-hidden`: it is decoration next to a word,
 * and a screen reader announcing it twice is noise. An icon that IS the whole
 * control takes a `label`.
 */
export function Icon({ icon, size = "md", filled, hoverFill, label, className, width, height, ...rest }: IconProps) {
    const px = SIZE[size];
    // `strokeWidth` was lucide's. A Material Symbol is a filled path with no
    // stroke, so it is dropped here rather than forwarded onto an <svg> that
    // would ignore it and warn in dev - 200-odd call sites still pass it.
    const { strokeWidth: _stroke, ...svgProps } = rest as Record<string, unknown>;
    void _stroke;
    const a11y = {
        "aria-hidden": label ? undefined : true,
        "aria-label": label,
        role: label ? ("img" as const) : undefined,
        focusable: false,
    };

    return (
        <svg
            {...(svgProps as ComponentPropsWithoutRef<"svg">)}
            width={width ?? px}
            height={height ?? px}
            viewBox={SYMBOL_VIEWBOX}
            fill="currentColor"
            {...a11y}
            className={cn("shrink-0", hoverFill && "m3-icon-hover", className)}
        >
            {hoverFill && !filled && icon.f ? (
                <>
                    <path className="m3-icon-o" d={icon.d} />
                    <path className="m3-icon-f" d={icon.f} />
                </>
            ) : (
                <path d={filled && icon.f ? icon.f : icon.d} />
            )}
        </svg>
    );
}

import { cn } from "../cn";

/**
 * M3 progress indicators — https://m3.material.io/components/progress-indicators
 *
 * Two shapes, one meaning: something is happening. Determinate when the length
 * is known (an upload, a batch), indeterminate when it is not (a request).
 *
 * Shape decision (law: recorded per component): square track and indicator
 * (Ink, 2026-10-21), not M3's `full`.
 */

const CIRCULAR = { sm: "h-4 w-4", md: "h-6 w-6", lg: "h-12 w-12" } as const;

export type SpinnerProps = {
    size?: keyof typeof CIRCULAR;
    /** Announced to screen readers. Omit when a parent already says what is loading. */
    label?: string;
    className?: string;
};

/**
 * Indeterminate. Ink (2026-10-21): a pixel loader, not a circle - eight
 * squares round a 3x3 grid, one light chasing round (CSS in ui.css,
 * `.m3-pixload`). Takes the colour of the text around it, so it is correct
 * inside a filled button (`on-primary`) and on a page (`on-surface`)
 * without anyone choosing. Reduced motion: the squares sit still.
 */
export function Spinner({ size = "md", label, className }: SpinnerProps) {
    return (
        <span
            role={label ? "status" : undefined}
            aria-label={label}
            aria-hidden={label ? undefined : true}
            className={cn("m3-pixload", CIRCULAR[size], className)}
        >
            {Array.from({ length: 9 }, (_, i) => <i key={i} />)}
        </span>
    );
}

export type ProgressProps = {
    /** 0–100. Leave undefined for indeterminate. */
    value?: number;
    /** What is progressing. Required — a bare bar tells a screen reader nothing. */
    label: string;
    className?: string;
};

/**
 * Linear progress. 4dp tall, `primary` on `secondary-container`, square.
 *
 * The indeterminate animation is transform-only, so it never triggers layout,
 * and it stops entirely under `prefers-reduced-motion` (see globals.css).
 */
export function Progress({ value, label, className }: ProgressProps) {
    const determinate = typeof value === "number";
    const pct = determinate ? Math.max(0, Math.min(100, value)) : undefined;
    return (
        <div
            role="progressbar"
            aria-label={label}
            aria-valuenow={determinate ? pct : undefined}
            aria-valuemin={determinate ? 0 : undefined}
            aria-valuemax={determinate ? 100 : undefined}
            className={cn("h-1 w-full overflow-hidden bg-secondary-container", className)}
        >
            <div
                className={cn(
                    "h-full bg-primary",
                    determinate ? "transition-[width] duration-medium2 ease-standard" : "w-full animate-m3-progress origin-left",
                )}
                style={determinate ? { width: `${pct}%` } : undefined}
            />
        </div>
    );
}

import type { ReactNode } from "react";
import { cn } from "../cn";

export type SkeletonProps = {
    /** Match the shape of the real content: a row of text, a tile, an avatar. */
    shape?: "text" | "block" | "circle";
    className?: string;
};

/**
 * A placeholder with the shape of what is coming, so nothing jumps when the
 * real content lands (§6.3, CLS < 0.05).
 *
 * Not for anything under ~300ms — a flash reads as a glitch. It is the one
 * placeholder (`.m3-wash`, ui.css), the same as a picture's: a flat tint
 * of the theme's text colour with a soft light passing over it.
 */
export function Skeleton({ shape = "block", className }: SkeletonProps) {
    return (
        <span
            aria-hidden
            className={cn(
                "m3-wash block",
                shape === "text" && "h-4 rounded-extra-small",
                shape === "block" && "rounded-medium",
                shape === "circle" && "rounded-full",
                className,
            )}
        />
    );
}

export type KbdProps = { children: ReactNode; className?: string };

/** A key on the keyboard: ⌘K, esc, ↵. Always the real key, never a picture of one. */
export function Kbd({ children, className }: KbdProps) {
    return (
        <kbd
            className={cn(
                "inline-flex h-5 min-w-[20px] items-center justify-center rounded-extra-small",
                "bg-surface-container-highest px-1.5 text-label-sm text-on-surface-variant",
                className,
            )}
        >
            {children}
        </kbd>
    );
}

/** Text for screen readers only. Visible on focus when it wraps a focusable. */
export function VisuallyHidden({ children }: { children: ReactNode }) {
    return <span className="sr-only">{children}</span>;
}

